window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["medcurso:medcurso-gastrologia-gas-3"]={"block":"medcurso:medcurso-gastrologia-gas-3","label":"Medcurso · GAS 3","count":423,"questions":[{"id":"medcurso-gastrologia-gas-3-345474","number":"345474","sourceNumber":"345474","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Com relação ao câncer de pâncreas, é CORRETO afirmar que:","options":{"A":"A Icterícia obstrutiva ocorre precocemente quando o câncer é localizado na cauda do pâncreas.","B":"O tabagismo é o principal fator de risco ambiental para o desenvolvimento do câncer de\npâncreas.","C":"A tomografia computadorizada do abdome é o melhor método de imagem para rastreamento do\ncâncer de pâncreas.","D":"Todos os pacientes com mais de 60 anos de idade dever ser submetidos ao rastreamento do\ncâncer de pâncreas."},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-343821","number":"343821","sourceNumber":"343821","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Pac. ?, cirrótico, Child B, durante exames de rotina teve o diagnóstico de colelitíase.\nQual a sua conduta frente a esse diagnóstico?","options":{"A":"Caso não apresente ascite, indicar colecistectomia.","B":"Indicar colecistectomia, não esperar que apresente complicações.","C":"Apenas observar.","D":"Se estiver listado para transplante, realizar a colecistectomia previamente."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-343825","number":"343825","sourceNumber":"343825","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Mulher de 30 anos, chaga ao seu ambulatório com queixa de dor inespecífica no\nhipocôndrio esquerdo e epigástrio. Conta que realizou tomografia de abdome por conta própria e\nficou assustada ao ler o laudo. Laudo: massa na cauda do pâncreas, bem delimitada, com\ncontornos regulares, cápsula espessa, heterogênea, de padrão misto, sólido cístico, com\ncalcificações internas, medindo cerca de 4 cm. Qual a principal hipótese diagnóstica?","options":{"A":"Pseudocisto pancreático.","B":"Neoplasia cística mucinosa do pâncreas.","C":"Tumor de Frantz.","D":"Neoplasia intraductal mucinosa pancreática."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-345506","number":"345506","sourceNumber":"345506","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"O exame que não se encaixa na avaliação de um paciente que apresenta colelitíase\nsintomática e revelou na anamnese colúria e acolia semanas antes, mas está sem queixas ou\nsinais clínicos atuais é:","options":{"A":"CPRE.","B":"Eco endoscopia.","C":"Colangiografia trans operatória.","D":"Dosagem de enzimas caniculares."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-345507","number":"345507","sourceNumber":"345507","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"O abcesso hepático é uma condição grave, cujo quadro clínico coloca em risco a vida\ndo paciente. Seu tipo mais frequente é o:","options":{"A":"Iatrogênico.","B":"Amebiano.","C":"Fúngico.","D":"Piogênico."},"answer":"D","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-345509","number":"345509","sourceNumber":"345509","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente masculino, 65 anos, em acompanhamento ambulatorial de hepatite por vírus\nC, vem à consulta de rotina com quadro de dor\nabdominal, plenitude pós-prandial e anorexia.\n\nRealiza ultrassonografia de abdome que demonstra lesão hipoecóica com cerca de 3 cm de\ndiâmetro, com aspecto em mosaico. Assinale o diagnóstico mais provável:","options":{"A":"Metástase de tumor de próstata.","B":"Hepatocarcinoma primário.","C":"Adenoma hepatocelular.","D":"Hemangioma hepático."},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-343832","number":"343832","sourceNumber":"343832","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Gestante de 22 semanas comparece ao pronto socorro com queixas de dor abdominal\nem hipocôndrio direito há 12 horas, com piora à\nalimentação. Ao exame físico encontra-se em bom\nestado geral, febril, com sinal de Murphy positivo. A melhor conduta é:","options":{"A":"Realizar ultrassom e confirmando-se a principal suspeita, indicar tratamento cirúrgico,\nincluindo a\nopção da videolaparoscopia.","B":"Realizar ultrassom e, confirmando-se a principal suspeita, indicar tratamento cirúrgico,\ncontraindicando via laparoscópica.","C":"Indicar tratamento clínico conservador com tratamento cirúrgico eletivo após o parto.","D":"Realizar cintilografia com 99mTc-DISIDA e, confirmando-se a principal suspeita, indicar\ntratamento cirúrgico por incisão de kocher reduzida."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-345512","number":"345512","sourceNumber":"345512","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Assinale a alternativa que corresponde ao fator de risco mais forte para\ndesenvolvimento do hepatocarcinoma:","options":{"A":"Etilismo.","B":"Infecção pelo vírus da hepatite C.","C":"Ingestão de aflatoxinas.","D":"HbeAg do vírus da hepatite B positivo."},"answer":"D","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-345513","number":"345513","sourceNumber":"345513","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"O agente bacteriano mais frequente na colangite aguda é:","options":{"A":"Anaeróbios.","B":"Escherícia coli.","C":"Staphylococcus aureus.","D":"Pseudomonas aeruginosa."},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-283309","number":"283309","sourceNumber":"283309","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Mulher de 30 anos chega ao seu ambulatório com queixa de dor inespecífica no\nhipocôndrio esquerdo e epigástrio. Conta que realizou tomografia de abdome por conta própria e\nficou assustada ao ler o laudo. Laudo: massa na cauda do pâncreas, bem delimitada, com\ncontornos regulares, cápsula espessa, heterogênea, de padrão misto, sólido cístico, com\ncalcificações internas, medindo cerca de 4 cm. Qual a principal hipótese diagnóstica?","options":{"A":"Pseudocisto pancreático.","B":"Neoplasia cística mucinosa do pâncreas.","C":"Tumor de Frantz.","D":"Neoplasia intraductal mucinosa pancreática."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-283310","number":"283310","sourceNumber":"283310","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente sexo feminino, 28 anos, multípara, em uso de anticoncepcional oral há 5 anos,\ndurante exame ultrassonográfico de rotina foi evidenciado nódulo de 5,5 cm no segmento VI do\nfígado de aspecto exofítico. As sorologias para hepatites virais foram negativas. A ressonância\nmagnética com contraste hepato-específico fez o diagnóstico de adenoma hepatocelular. Qual a\nsua conduta?","options":{"A":"Suspender anticoncepcional oral e controle com 3 meses.","B":"Realizar biópsia percutânea para confirmação diagnóstica.","C":"Indicar cirurgia para ressecção.","D":"Indicar ablação por radiofrequência."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-283311","number":"283311","sourceNumber":"283311","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente sexo feminino, 28 anos, multípara, apresentou quadro de dor em andar\nsuperior do abdome, em barra, início súbito,\nde forte intensidade e vômitos incoercíveis. Evolução\nde 2 dias. Refere plenitude pós-prandial de longa data. Ao exame físico apresenta-se ictérica +/+4,\ndesidratada e taquicárdica. O abdome é difusamente doloroso à palpação, mais intensamente em\nepigástrica. Considerando a hipótese de pancreatite biliar, qual a resposta correta?","options":{"A":"Estabilizar hemodinamicamente e indicar papilotomia endoscópica.","B":"Estabilizar hemodinamicamente e indicar videocolecistectomia.","C":"Após normalização das enzimas pancreáticas e voltar a alimentação sem dor, indicar\nvideocolecistectomia.","D":"Após normalização das enzimas pancreáticas e voltar a alimentação sem dor, indicar\npapilotomia endoscópica."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-283312","number":"283312","sourceNumber":"283312","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente sexo feminino, 65 anos, refere icterícia e colúria com evolução de 2 meses, no\nmomento com prurido intenso, emagrecimento de 6Kg nesse período. Traz ultrassonografia de\nabdome que demonstra grande dilatação de vias biliares intra-hepáticas com vesícula biliar vazia e\ncolédoco de aspecto normal. Qual sua hipótese diagnóstica?","options":{"A":"Tumor de Klatskin.","B":"Doença de Caroli.","C":"Coledocolitíase primária.","D":"Doença de Wilson."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-281159","number":"281159","sourceNumber":"281159","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Assinale a alternativa que apresenta o tumor hepático benigno mais comum.","options":{"A":"Adenoma.","B":"Hiperplasia nodular focal.","C":"Hemangioma.","D":"Nódulos macrorregenerativos.","E":"Hamartomas."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-281170","number":"281170","sourceNumber":"281170","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente feminina, 50 anos, apresenta quadro de pancreatite aguda biliar. Qual dos\nseguintes achados representa o melhor fator preditivo da persistência de cálculos na via biliar\nprincipal?","options":{"A":"Lipase sérica à admissão superior a 1.000 u/l.","B":"Persistência de níveis séricos de amilase aumentados.","C":"Elevação persistente da bilirrubina.","D":"Presença de colédoco dilatado à admissão.","E":"Persistência de dor abdominal."},"answer":"D","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-251864","number":"251864","sourceNumber":"251864","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente masculino de 50 anos, com história de etilismo, chega a UPA com quadro de\ndor abdominal em faixa de forte intensidade e vômitos. Tem dor à palpação epigástrica e está\nafebril. Estável hemodinamicamente. Os exames demonstram um hemograma com 15.000\nleucócitos, amilase de 1.200 mg/dl e glicemia de 145 mg/dl. Qual a conduta mais correta?","options":{"A":"Encaminhar para internação hospitalar, antibioticoterapia e alta se houver melhora em 24h.","B":"Encaminhar para internação hospitalar, antibioticoterapia, hidratação parenteral, analgesia e\nalta\npós melhora do quadro.","C":"Encaminhar para internação hospitalar, analgesia, hidratação parenteral, jejum e alta após\nmelhora clínica.","D":"Observação na UPA por 24h, analgesia e alta após melhora clínica."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-247215","number":"247215","sourceNumber":"247215","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Assinale a alternativa que completa CORRETAMENTE a frase abaixo. A classificação\ntopográfica dos colangiocarcinomas mais utilizada é a de:","options":{"A":"Bismuth-Corlette.","B":"Ivory-Lewis.","C":"Ramson.","D":"Apache II.","E":"Siewert."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-247221","number":"247221","sourceNumber":"247221","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Assinale a alternativa que responde CORRETAMENTE à pergunta abaixo. Qual a\nvíscera oca mais comum na formação da fístula colistoentérica?","options":{"A":"Jejuno.","B":"Duodeno.","C":"Estômago.","D":"Flexura hepática do cólon.","E":"Íleo terminal."},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-251944","number":"251944","sourceNumber":"251944","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente ?, 53 anos, apresentava episódios de dor em HD tipo cólica, irradiação para\nas costas e vômitos, em crises auto-limitadas\ncom evolução de 3 anos. Há 36h apresentou nova\ncrise cursando com escleras ictéricas ++/+4 e colúria. Realizou Ultra-sonografia de abdome que\nrevelou imagem hiperecogênica com sombra acústica posterior na topografia da vesícula biliar (não\nvisibilizada), dilatação de vias biliares intra-hepáticas e colédoco normal. Qual a sua hipótese\ndiagnóstica?","options":{"A":"Tumor de Klatinsk.","B":"Síndrome de Caroli.","C":"Síndrome de Bouveret.","D":"Síndrome de Mirizzi."},"answer":"D","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-251946","number":"251946","sourceNumber":"251946","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente ?, 50 anos, portador de hepatite B, Child A, MELD 6, apresenta na tomografia\nde abdome com contraste dinâmico lesão\nhipervascular com washout precoce e diâmetro de 6,5 cm\nlocalizada em segmento III do fígado. A dosagem de alfa-feto-proteína foi de 1900 ng/ml. Qual a\nmelhor conduta?","options":{"A":"Indicar transplante hepático.","B":"Ablação por radiofrequência.","C":"Segmentectomia do segmento III.","D":"Alcoolização percutânea."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-251957","number":"251957","sourceNumber":"251957","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"As principais causas de pancreatites são a biliar e alcoólica, porém causas mais raras\nnão devem ser negligenciadas, o \"pancreas\ndivisum\" é uma delas e deve-se a:","options":{"A":"Trauma abdominal contuso contra a coluna.","B":"Lesão iatrogênica durante laparotomia interessando vias biliares.","C":"Lesão criptogenética.","D":"Defeito de fusão dos ductos cefálicos e dorsal."},"answer":"D","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-217672","number":"217672","sourceNumber":"217672","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente sexo feminino, 44 anos com diagnóstico de colelitíase. Durante a última crise\napresentou quadro de icterícia, colúria e acolia fecal. A Ultrassonografia revelou colédoco com 10\nmm de diâmetro e coledocolitíase (um cálculo de 0,5 cm, flutuante). A paciente não apresenta\nsinais ou sintomas infecciosos. Como conduziria esse caso?","options":{"A":"Indicar colecistectomia e exploração de vias biliares.","B":"Realizar colecistectomia e encaminhar para realizar colangiopancreatografia retrógrada\nendoscópica e papilotomia.","C":"Solicitar colangiopancreatografia retrógrada endoscópica e papilotomia e posterior\ncolecistectomia.","D":"Solicitar colangioressonância com contraste para afastar a possibilidade de neoplasia."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-217673","number":"217673","sourceNumber":"217673","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente sexo masculino, 50 anos, há 2 meses com crises de confusão mental,\nsudorese fria e hipotensão, que melhoram com\na ingestão de alimentos. Numa das crises\napresentava glicemia de 40 mg/dl. Ao exame físico não apresenta alterações. A ultrassonografia de\nabdome foi normal e a ressonância nuclear magnética demonstrou uma lesão sólida de 2 cm de\ncauda de pâncreas. Qual hipótese diagnóstica?","options":{"A":"Tumor neuroendócrino de pâncreas.","B":"Adenocarcinoma de pâncreas.","C":"Tumor de Frantz.","D":"Neoplasia papilar intraductal."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-217685","number":"217685","sourceNumber":"217685","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente, sexo masculino, 49 anos, etilista durante 30 anos, 500 ml/dia de bebida\ndestilada. Há 1 ano apresenta dor em andar superior do abdome, em barra, de forte intensidade\nmesmo estando em abstinência há 6 meses. O RX de abdome revela múltiplas calcificações em\ntopografia do pâncreas. Considerando-se o diagnóstico de pancreatite crônica, qual a indicação\ncirúrgica nesse paciente?","options":{"A":"Formação de pseudocisto de pâncreas.","B":"Associação com esteatorreia.","C":"Diabetes mellitus de difícil controle.","D":"Dor intratável."},"answer":"D","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-183180","number":"183180","sourceNumber":"183180","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Em relação à Colecistite Aguda Alitiásica (CAA), assinale a alternativa INCORRETA.","options":{"A":"O tratamento da CAA é cirúrgico.","B":"A laparatomia é a via de acesso preferencial no tratamento cirúrgico da CAA, considerando-se\nque essa é de maior gravidade e complexidade que\na colecistite litiásica.","C":"Citamegalovírus é fator etiológico frequente em pacientes imunodeprimidos.","D":"Pacientes graves internados em unidade de terapia intensiva, grandes queimados e pacientes\ncom choque prolongado são os que mais\nfrequentemente apresentam tal afecção.","E":"De 40% a 100% dos pacientes com CAA apresentam gangrena, empiema ou perfuração da\nvesícula no momento da operação."},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-182642","number":"182642","sourceNumber":"182642","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente feminino, 53 anos, apresentou queixas de plenitude pós-prandial e\ndesconforto abdominal há 2 meses, há 30 dias\napresenta icterícia e colúria. A ultrassonografia\ndemonstrou dilatação de vias biliares intra e extra-hepática, com vesícula biliar distendida,\nparedes\nespessadas, sem cálculos. Qual o exame com melhor poder diagnóstico?","options":{"A":"CPRE (Colangio-Pancreatografia Retrógrada Endoscópica).","B":"Colangiorressonância magnética com contraste.","C":"Tomografia computadorizada com contraste e cortes finos de pâncreas.","D":"Ecoendoscopia."},"answer":"D","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-182612","number":"182612","sourceNumber":"182612","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente feminino, 37 anos, realizou exame de ultrassonografia de abdome total como\nparte de check-up de sua empresa, sendo evidenciado nódulo hiperecogênico de 4cm em\nsegmento hepático IVa. Foi realizado tomografia computadorizada de abdome que confirmou a\nlesão de 4cm no segmento referido, com impregnação tardia do contraste. Provavelmente trata-se\nde:","options":{"A":"Adenoma.","B":"Hiperplasia nodular focal.","C":"Hepatocarcinoma.","D":"Hemangioma."},"answer":"D","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-159116","number":"159116","sourceNumber":"159116","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente sexo feminino, 37 anos, foi submetida à colecistectomia à Torek. No 1° dia de\nPO drenou 200ml de secreção biliosa pelo dreno\ntúbulo-laminar. O exame físico não demonstra\nsinais de irritação peritoneal. Qual a medida a ser tomada?","options":{"A":"Laparotomia exploradora imediata.","B":"Conduta expectante.","C":"Dosagem de amilase da secreção do dreno.","D":"Solicitar Colangiorressonância para diagnóstico."},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-159120","number":"159120","sourceNumber":"159120","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente do sexo masculino, 68 anos, apresenta quadro de icterícia com padrão\nobstrutivo com evolução de 8 semanas. Ao exame\nfísico apresenta-se ictérico +++/+4, emagrecido,\nmassa ovalada de consistência cística, indolor, móvel com a respiração em HD. O US de abdome\ndemonstra vesícula biliar muito distendida, sem cálculos, colédoco de 2 cm e com dilatação de vias\nbiliares intra-hepáticas. Qual a hipótese diagnóstica?","options":{"A":"Coledocolitíase.","B":"Hepatite aguda.","C":"Tumor de Klatskin.","D":"Tumor peri-ampular."},"answer":"D","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-159045","number":"159045","sourceNumber":"159045","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente de 6 anos, sexo feminino, eutrófica, com episódios de dor abdominal, massa\npalpável em quadrante superior direito do abdome e icterícia flutuante, sugere qual diagnóstico?","options":{"A":"Abscesso hepático.","B":"Cisto de colédoco.","C":"Hepatite aguda.","D":"Neoplasia hepática."},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-159071","number":"159071","sourceNumber":"159071","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente masculino, 70 anos, apresentando massa palpável em HD, endurecida e\nmóvel com a respiração. O US de abdome\nrevelou uma lesão sólida de 4,0 x 5,0 em segmento V. A\ntomografia computadorizada de abdome confirma a presença da lesão, a qual apresenta wash-out\nna fase precoce. Qual a hipótese diagnóstica?","options":{"A":"Hepatocarcinoma.","B":"Hemangioma.","C":"Hiperplasia nodular focal.","D":"Nódulo de regeneração."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-108671","number":"108671","sourceNumber":"108671","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Sobre o quadro clínico da apendicite, qual a opção CORRETA?","options":{"A":"EAS com piúria afasta o diagnóstico.","B":"A dor é sempre localizada em fossa ilíaca direita.","C":"Pode cursar com diarreia em sua fase inicial.","D":"A USG sempre determina o diagnóstico."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-108695","number":"108695","sourceNumber":"108695","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente feminina, 84 anos, deu entrada na UPA com queixas de dor abnominal difusa,\ntipo cólicas e vômitos com evolução de 48h.\nHá 24h com parada de eliminação de fezes e flatos.\n\nSolicitaram, RX de abdome em pé e deitado, que demostrou distensão difusa de delgado e de todo\ncólon. Com base apenas nesses dados, como diferenciar uma obstrução mecânica de um íleo\nmetabólico?","options":{"A":"Verificar se há macicez móvel;","B":"Realizar toque retal;","C":"Avaliar se o Sinal de Joubert é positivo;","D":"Realizar tonometria do suco gástrico."},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-108736","number":"108736","sourceNumber":"108736","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Nos casos de diverticulite aguda tipo Hinchey III, a conduta CORRETA é:","options":{"A":"Colostomia em alça;","B":"Cirurgia de Hartmann;","C":"Ressecção do seguimento afetado e anastomose primária;","D":"Sutura do divertículo com drenagem."},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-84463","number":"84463","sourceNumber":"84463","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Em relação à doença de crohn, é incorreto afirmar: I - perfuração livre ou hemorragia\nmaciça são indicações de cirurgia de urgência. II- megacólon tóxico sem resposta inicial ao\ntratamento clínico deverá ser tratado com colectomia subtotal. III- as fístulas enterovesicais são\ncirúrgicas na maioria das vezes.","options":{"A":"apenas I.","B":"apenas III.","C":"I e III.","D":"I, II e III.","E":"apenas III."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-84464","number":"84464","sourceNumber":"84464","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"A indicação cirúrgica mais comum nos casos de doença de Crohn decorre de:","options":{"A":"Perfuração livre.","B":"Hemorragia maciça.","C":"Degeneração maligna.","D":"Obstrução intestinal.","E":"Diarreia frequente."},"answer":"D","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-84484","number":"84484","sourceNumber":"84484","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Causa de megacólon tóxico:","options":{"A":"Fecaloma.","B":"Retocolite ulcerativa.","C":"Diverticulite.","D":"Megacólon Chagásico.","E":"Trombose hemorroidária complicada."},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-84490","number":"84490","sourceNumber":"84490","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"O segmento do cólon mais sujeito torções, originado quadro de volvo é o:","options":{"A":"Ceco.","B":"Cólon transverso.","C":"Ângulo esplênico.","D":"Sigmoide.","E":"Reto alto."},"answer":"D","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-84511","number":"84511","sourceNumber":"84511","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"O antígeno carcinoembrionário:","options":{"A":"Tem valor prognóstico no câncer colorretal.","B":"Não é influenciado pelo tabagismo.","C":"É um antígeno específico no câncer colorretal (CCR).","D":"Tem valor no screening de câncer colorretal.","E":"Pouco sensível."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-84457","number":"84457","sourceNumber":"84457","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"<p>Nos tumores de reto baixo, temos como opções terapêuticas, EXCETO:</p>","options":{"A":"Ablação por radiofrequência.","B":"Excisão transanal.","C":"Amputação abdominoperineal do reto.","D":"Radioterapia e quimioterapia.","E":"Excisão videolaparoscópica."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-84510","number":"84510","sourceNumber":"84510","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"São sinais clínicos e laboratoriais da trombose mesentérica, EXCETO:","options":{"A":"Dor abdominal localizada no compartimento central do abdome, de forte intensidade e que\napresenta remissão com o uso de opiáceos.","B":"A distensão abdominal é de aparecimento tardio, seguindo-se ao quadro álgico.","C":"Choque e peritonite indicam evolução tardia, com possibilidade de cura remota.","D":"Grandes oclusões venosas podem levar a quadro precoce de choque.","E":"A amilase sérica encontra-se elevada em 50% dos pacientes."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-50053","number":"50053","sourceNumber":"50053","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Uma mulher de 35 anos refere dor intensa recorrente em cólica no quadrante inferior\ndireito do abdômen há vários dias, que está\npiorando progressivamente. Não refere dor epigástrica\nou periumbilical prévia, febre significativa ou anorexia. Já apresentou um quadro semelhante no\npassado. Todos os seguintes achados são possíveis, EXCETO:","options":{"A":"Temperatura de 38°C, hipersensibilidade de quadrante inferior direito, diarreia e fístula anal;","B":"Resultados normais ao exame físico, 20 hemácias por campo de grande aumento na urina;","C":"Apendicite aguda, mesmo se não houver anorexia e a temperatura corporal for normal;","D":"Uma pequena massa dolorosa na região inguinal direita."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-50111","number":"50111","sourceNumber":"50111","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Lactente de 6 meses em aleitamento materno exclusivo, eutrófico, com história de dor\nabdominal de início súbito com cólicas intermitentes, com posterior aparecimento de vômitos e\nfezes gelatinosas misturadas com sangue e muco. Ao exame físico, criança afebril, muito irritada,\ncom massa dolorosa em região do flanco direito. Mãe informa como antecedentes pessoais\nresfriado há 10 dias. História vacinal adequada para a idade. Pergunta-se: Qual a principal hipótese\ndiagnóstica?","options":{"A":"Diverticulite de Meckel.","B":"Intussuscepção intestinal.","C":"Enterocolite necrotizante.","D":"Apendicite aguda."},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-50099","number":"50099","sourceNumber":"50099","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente masculino, 12 anos, refere que há 12 horas iniciou quadro de dor em região\nmesogástrica, ao tentar se alimentar apresentou vômitos e há 2 horas está com febre (TA 37,8°C).\nAo exame físico apresenta dor à palpação profunda em fossa ilíaca direita com descompressão\nbrusca dolorosa. Diante desse quadro, qual a conduta mais adequada?","options":{"A":"Indicar laparotomia exploradora;","B":"Observar por 12 horas a evolução do quadro;","C":"Solicitar ultrassonografia de abdômen;","D":"Solicitar tomografia computadorizada do abdômen;"},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-37097","number":"37097","sourceNumber":"37097","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Escolar, nove anos, apresentando retorragia, anemia e, em três ocasiões, prolapso\nretal. Realizado colonoscopia e foi visualizada\nmais de 80 nodulações ao longo do trato intestinal.\nVocê pensaria em:","options":{"A":"Polipose Juvenil.","B":"Síndrome de Peutz-Jeghers.","C":"Polipose Adenomatosa Familiar.","D":"Hiperplasia Nodular Linfoide.","E":"Nenhuma das anteriores."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-37147","number":"37147","sourceNumber":"37147","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Qual destas patologias é a mais sugestiva em apresentar hemorragia maciça de origem\ncolônica de caráter agudo?","options":{"A":"colite granulomatosa","B":"colite ulcerativa","C":"carcinoma","D":"polipose familiar","E":"diverticulose difusa"},"answer":"E","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-37148","number":"37148","sourceNumber":"37148","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"É possível observar Melena em decorrência de:","options":{"A":"Lesões sigmoideanas","B":"Lesões retais","C":"Lesões do cólon direito","D":"Lesões do canal anal","E":"Em todos os casos acima"},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-343192","number":"343192","sourceNumber":"343192","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Lesões eritematosas, migratórias, com vesículas e bolhas na superfície, evoluindo para\ncura com hiperpigmentação são típicas de\neritema necrolítico. Tal condição tem elevada\nassociação com qual alternativa abaixo?","options":{"A":"Sarcoma estromas gastrointestinal","B":"VIPoma","C":"Insulinoma","D":"Glucagonoma"},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-343199","number":"343199","sourceNumber":"343199","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Mulher, 49 anos, procura atendimento médico com dor abdominal em cólicas há 9 dias,\nintermitentes, que cessavam com escopolamina. Há 2 dias apresentou piora da dor e icterícia\nassociada à febre alta e vômitos. No momento em regular estado geral, desidratada, taquicárdica,\ntaquipneica, confusa, febril, ictérica. Tem dor intensa à palpação de abdome superior, sem sinais de\nirritação peritoneal. Hemograma com leucocitose importante, amilase normal, com discreto\naumento provas de lesão hepatocelular. Realizou ecografia de abdome que evidenciou: vesícula\nbiliar com parede de 2 mm, com cálculos em seu interior, múltiplos, todos com tamanho menor que\n10 mm e ducto colédoco com 16 mm, sem visualização de sua porção distal, prejudicado por\ninterposição gasosa. Qual o provável diagnóstico e conduta adequada?","options":{"A":"Pancreatite aguda biliar ? Pancreatectomia corpocaudal.","B":"Pancreatite aguda biliar ? Dieta zero, hidratação endovenosa e antibioticoprofilaxia.","C":"Colecistite aguda Tokyo 3 - derivação externa guiada por imagem.","D":"Colangite aguda - drenagem da via biliar e antibioticoterapia."},"answer":"D","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-343202","number":"343202","sourceNumber":"343202","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Jovem, masculino, 32 anos, é internado por episódios de vômitos de início há 24 horas,\nassociado a dor abdominal refratária à analgésicos simples. Nega febre. Nega trauma recente.\n\nNega sintomas urinários. Refere anorexia. Ao exame físico: regular estado geral, desidratado\n\n+++/4, corado, anictérico, afebril, taquicárdico. Ausculta pulmonar normal. Abdome com cicatriz\nprévia de laparotomia mediana por trauma (há\n3 anos), distendido, ruídos abdominais muito\nreduzidos, doloroso em epigástrio e todo andar superior, mas sem sinais de peritonite. Realizou\nradiografia (abaixo) e foi submetido a ultrassonografia que visualizou vesícula biliar com parede de\n3 mm, com cálculos em seu interior, múltiplos, todos com tamanho menor que 5 mm, e ducto\ncolédoco com 4 mm. O pâncreas não foi visualizado por interposição gasosa. A principal hipótese\ndiagnóstica e o tratamento mais adequado é:","options":{"A":"Pancreatite aguda biliar - jejum, analgesia e hidratação, e posteriormente colecistectomia.","B":"Colecistite aguda - colecistectomia.","C":"Colecistite aguda - colangiopancreatografia retrógrada endoscópica.","D":"Bridas - cirurgia de Hartmann."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":["question_bank/media/medcurso/medcurso-gastrologia-gas-3/343202.png"],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-315162","number":"315162","sourceNumber":"315162","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente com diagnostico de pancreatite crônica internado por massa palpável em\nepigástrio com aparecimento após episódio de agudização da pancreatite. Qual das seguintes\ncomplicações é a mais provável?","options":{"A":"Ascite pancreática.","B":"Neoplasia pancreática.","C":"Pseudocisto pancreático.","D":"Trombose de veia esplênica.","E":"Pseudoaneurisma roto."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-275975","number":"275975","sourceNumber":"275975","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"A pancreatite aguda é caracterizada como uma resposta inflamatória do pâncreas a um\nconjunto possível de situações. Dentre os fatores etiológicos listados abaixo, qual alternativa\n\nrefere-se aos de maior prevalência?","options":{"A":"Fibrose cística e causas genéticas.","B":"Hipertrigliceridemia e causa medicamentosa.","C":"Litíase biliar e alcoólica.","D":"Neoplasia e traumática.","E":"Infecciosa e vascular."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-275979","number":"275979","sourceNumber":"275979","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Onde está localizado o Tumor de Klatskin?","options":{"A":"Na papila duodenal.","B":"No cólon esquerdo.","C":"No estômago.","D":"Na confluência dos ductos hepáticos.","E":"No esôfago médio."},"answer":"D","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-275981","number":"275981","sourceNumber":"275981","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"No paciente cirrótico é necessário fazer o rastreamento periódico na pesquisa de\nhepatocarcinoma. Como fazer esse rastreamento?","options":{"A":"Ultrassonografia e dosar antígeno carcinogênico embrionário (CEA) a cada três meses.","B":"Tomografia de seis em seis meses.","C":"Dosar alfafetoproteína, CEA e CA 19-9 de seis em seis meses.","D":"Ultrassonografia e dosar alfafetoproteína a cada seis meses.","E":"Ultrassonografia e dosar CA 19-9 a cada seis meses."},"answer":"D","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-275983","number":"275983","sourceNumber":"275983","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente com colecistopatia crônica calculosa e coledocolitíase com colédoco de 8 mm\nde diâmetro. O tratamento de eleição é?","options":{"A":"Colecistectomia videolaparoscópica.","B":"Colecistectomia convencional.","C":"Colecistectomia videolaparoscópica associada à exploração do colédoco pelo ducto cístico para\nretirada dos cálculos.","D":"Colecistectomia convencional e a realização de CPER com papilotomia para retirada do(s)\ncálculo(s).","E":"Retirada dos cálculos por CPER."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-275986","number":"275986","sourceNumber":"275986","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Na neoplasia da cabeça de Pâncreas, qual o primeiro sinal ou sintoma que geralmente\napresenta?","options":{"A":"Emagrecimento.","B":"Icterícia.","C":"Sinal de Cullen.","D":"Dor no hipocôndrio direito.","E":"Massa palpável."},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-249292","number":"249292","sourceNumber":"249292","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Qual das alternativas abaixo apresenta a manobra utilizada para a palpação da\nvesícula biliar?","options":{"A":"Manobra de Traube.","B":"Manobra de Blumberg.","C":"Manobra de Murphy.","D":"Manobra de McBurney."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-249307","number":"249307","sourceNumber":"249307","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"O sinal de Courvoisier-Terrier caracteriza-se pela presença de vesícula palpável,\nindolor, na vigência de icterícia. É mais comum em qual tipo de lesão abaixo?","options":{"A":"Tumor de Klatskin.","B":"Neoplasias periampulares.","C":"Carcinoma de vesícula biliar.","D":"Carcinoma hepatocelular."},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-231374","number":"231374","sourceNumber":"231374","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Qual o melhor procedimento para litíase biliar na papila duodenal maior","options":{"A":"Papilotomia aberta","B":"Exploração biliar por laparotomia","C":"Colecistectomia vídeo","D":"Colangiopapilotomia endoscópica","E":"Anastomose biliodigestiva"},"answer":"D","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-231381","number":"231381","sourceNumber":"231381","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"O tumor de vias biliares que acomete a bifurcação dos ductos biliares direito e esquerdo\né denominado:","options":{"A":"Tumor de Wilms","B":"Tumor de Klatskin","C":"Sarcoma","D":"Hepatoblastoma","E":"Hepatocarcinoma"},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-249424","number":"249424","sourceNumber":"249424","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente feminina, 32 anos, com queixa de dor abdominal em cólicas há 7 dias,\nintermitentes, que cessavam com\nantiespasmódico simples. Há 1 dia com piora da dor, que passou\na ser progressiva além do aparecimento de icterícia súbita, febre aferida de 39°C e queda\nimportante do estado geral. Ao exame físico encontra-se em mal estado geral, desidratada,\ntaquicárdica, taquipneica, confusa, febril, ictérica. Sem alterações no exame físico cardiopulmonar,\nporém com dor intensa à palpação de abdome superior, sem sinais de irritação peritoneal.\n\nHemograma com leucocitose importante, amilase normal, com discreto aumento de ALT. Realizou\necografia de abdome que evidenciou: vesícula biliar com parede de 2mm, com cálculos em seu\ninterior, múltiplos, todos com tamanho menor que 10mm e ducto colédoco com 12mm, porém sem\nvisualização de sua porção distal, prejudicado por interposição gasosa. Qual o provável diagnóstico\ne conduta adequada?","options":{"A":"Colecistite aguda Tokyo 2 ? colecistectomia videolaparoscópica.","B":"Colecistite aguda Tokyo 3 ? derivação externa guiada por imagem.","C":"Colangite aguda ? drenagem da via biliar e antibioticoterapia.","D":"Colangite aguda ? colecistectomia de urgência e antibioticoterapia."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-212188","number":"212188","sourceNumber":"212188","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente de 44 anos, sexo feminino, bancária, previamente hígida, sem ingestão de\nálcool, admitida em pronto atendimento com\nquadro de dor abdominal em andar superior, em barra,\ncom irradiação para dorso há cerca de 6 horas, refratária a analgesia oral e associada a vômitos.\n\nAo exame, estado geral regular, corada, desidratada (2 em 4+), ictérica (1 em 4+), taquipneica e\ntaquicárdica. Ausculta cardíaca normal e ausculta pulmonar com murmúrio vesicular diminuído em\nbases. Abdome globoso, pouco distendido e pouco doloroso à palpação, sem descompressão\ndolorosa. Exames séricos evidenciam leucograma de 15.000/mm³, sem desvio, hemoglobina de 10\ne hematócrito de 26%, amilase de 3.500 mg/dl, creatinina de 1,8, cálcio de 9, LDH de 300, ALT de\n170, bilirrubina total de 4,6 e direta de 3,1, glicemia de 200, PCR 10. Radiografia de abdome aguda\nevidencia distensão difusa de alças de delgado, sem pneumoperitônio. Assinale a alternativa\nCORRETA a respeito do caso.","options":{"A":"A dosagem de proteína C-reativa tem valor prognóstico para essa doença.","B":"Antibioticoterapia com carbapenêmicos está indicada nas primeiras 24 horas.","C":"Pelos parâmetros clínicos e laboratoriais, podemos classificar essa doença como grave.","D":"Tomografia de abdome com contraste está indicada dentro das primeiras 12 horas da admissão.","E":"A instalação de nutrição parenteral é imprescindível para diminuir os efeitos deletérios\ndecorrentes do catabolismo da doença."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-219869","number":"219869","sourceNumber":"219869","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Em relação à Pancreatite Aguda (PA), assinale a alternativa CORRETA:","options":{"A":"A adequação da reposição hídrica é um dos aspectos isolados mais importantes da terapia\nclínica.","B":"O tratamento cirúrgico do pseudocisto deve ser idealmente mais precoce.","C":"Os níveis de lipase tendem a ser mais elevados na PA biliar, enquanto os da amilase se elevam\nmais na PA alcoólica.","D":"Os níveis séricos de amilase guardam estreita relação com a gravidade do quadro."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-212140","number":"212140","sourceNumber":"212140","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Assinale a alternativa correta sobre o carcinoma hepatocelular.","options":{"A":"O carcinoma do tipo fibrolamelar, na maioria das vezes, não está associado à cirrose.","B":"No ocidente, o principal fator de risco para a doença é a cirrose por álcool.","C":"O rastreamento padrão da doença é ressonância magnética semestralmente.","D":"Pacientes Child B são os melhores candidatos à ressecção hepática.","E":"Hipertensão portal não contraindica ressecção em lesões grandes."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-219892","number":"219892","sourceNumber":"219892","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"DDK, 32 anos, sexo feminino, decoradora, realizou uma série de exames pois tem\nintenção de interromper o uso de\nanticoncepcional para engravidar. Os exames laboratoriais foram\nnormais, porém a ultrassonografia mostrou nódulo de 20 mm no segmento IV do fígado. Foi\nsolicitada tomografia, que evidenciou massa heterogênea bem delimitada com realce precoce na\nfase arterial. Em relação a esta situação, assinale a alternativa CORRETA:","options":{"A":"A paciente tem risco de ruptura espontânea do nódulo caso se confirme uma gravidez.","B":"Depois de instalada, a lesão não regride mesmo após a suspensão do anovulatório.","C":"Estas lesões são benignas, geralmente reproduzindo a arquitetura hepática em nódulos isolados\nautônomos.","D":"Não há necessidade de ressecção do nódulo, pois não há risco de degeneração maligna"},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-212146","number":"212146","sourceNumber":"212146","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente de 42 anos, sexo feminino, apresentando quadro de dor abdominal localizada\nno hipocôndrio direito há cerca de 26 horas,\nassociado à febre, com calafrios e icterícia. Ao exame\nfísico, apresenta-se orientada, febril ao toque, ictérica (3+/4+), desidratada e corada. Abdome\nflácido, doloroso à palpação profunda do hipocôndrio direito, sinal de Murphy negativo, vesícula\nbiliar não palpável. Exames laboratoriais evidenciam leucocitose com desvio à esquerda, enzimas\ncanaliculares e bilirrubinas aumentadas. Ultrassonografia do abdome superior revela vesícula biliar\ncom paredes finas contendo inúmeros cálculos, colédoco de 1,3 cm com a presença de cálculo no\nseu interior. Quais os diagnósticos e a conduta mais adequada, nesse momento?","options":{"A":"Colelitíase e colangite aguda ? papilotomia endoscópica com retirada do cálculo.","B":"Colecistite aguda e colangite aguda ? tratamento clínico com antibioticoterapia.","C":"Colelitíase, coledocolitíase e colangite aguda ? tratamento clínico com antibioticoterapia.","D":"Colelitíase, colecistite aguda e coledocolitíase ? tratamento clínico com antibioticoterapia.","E":"Colelitíase e colecistite aguda ? tratamento clínico com antibioticoterapia seguido de\ncolecistectomia videolaparoscópica."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-219894","number":"219894","sourceNumber":"219894","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Em relação à Colangite, assinale a alternativa CORRETA:","options":{"A":"A dor é geralmente intensa e se associa com reação peritoneal (defesa abdominal localizada).","B":"Deve-se evitar a manipulação (instrumentação) das vias biliares na fase aguda devido ao risco\nde septicemia.","C":"É essencial a presença de algum grau de obstrução da via biliar principal para instalação do\nquadro.","D":"Febre, icterícia e choque compõem a tríade de Charcot."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-219849","number":"219849","sourceNumber":"219849","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Em relação aos tumores malignos de localização hepática, assinale a alternativa\nINCORRETA:","options":{"A":"A cirrose, por quase todas etiologias, está associada a um aumento da ocorrência de carcinoma\nhepatocelular.","B":"O fígado cirrótico é mais suscetível ao implante de metástases de tumores de outros órgãos.","C":"Os hepatomas geralmente são mais vascularizados que o parênquima normal.","D":"Os níveis séricos de alfafetoproteína podem guardar relação com o prognóstico do câncer\nhepático."},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-201754","number":"201754","sourceNumber":"201754","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Exemplo de laparotomia oblíqua utilizada para cirurgia do fígado e vias biliares:","options":{"A":"Incisão de Davis.","B":"Incisão de Kocher.","C":"Incisão de Lennander.","D":"Incisão de Jalaguier.","E":"Incisão de McBurney."},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-201791","number":"201791","sourceNumber":"201791","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"O marcador tumoral mais específico para o carcinoma hepatocelular é:","options":{"A":"CA-19-9.","B":"CA-125-5.","C":"Alfafetoproteína.","D":"Antígeno Carcinogênico Embrionário (CEA).","E":"Anticorpos antimitocôndria."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-216301","number":"216301","sourceNumber":"216301","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Sobre as metástases hepáticas dos tumores colorretais é INCORRETO afirmar que","options":{"A":"metástases colorretais não tratadas apresentam prognóstico reservado com sobrevida média de\n6 a 12 meses.","B":"a presença de doença extra-hepática geralmente contraindica a ressecção cirúrgica.","C":"a principal indicação de embolização portal se dá nos casos onde a ressecção hepática não é\nviável.","D":"a ressecção é a modalidade mais efetiva e garante sobrevida de 5 anos em até 80% dos\npacientes."},"answer":"D","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-216312","number":"216312","sourceNumber":"216312","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"A Hiperplasia Nodular Focal representa o segundo mais frequente tumor hepático\nbenigno. É INCORRETO afirmar que","options":{"A":"a grande característica é lesão hipervascularizada com presença de cicatriz central radiada.","B":"a ocorrência de rotura e sangramento é extremamente rara.","C":"o tratamento cirúrgico é o tratamento de escolha.","D":"o mapeamento com radioisótopos apresenta baixa sensibilidade diagnóstica, mas alta\nespecificidade."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-181307","number":"181307","sourceNumber":"181307","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente do sexo feminino, 36 anos, 4 gestações prévias, com quadro de dor em\nhipocôndrio direito associada à náuseas, há 4 meses. Exame físico do abdome normal, IMC = 32.\nUltrassonografia de abdome evidencia vesícula de paredes finas contendo imagens\nhiperecogênicas que ocasionam sombra acústica posterior em seu interior de tamanhos variáveis.\nDosagens de bilirrubinas e enzimas canaliculares normais. Submetida à colecistectomia\nconvencional, com certa dificuldade devido à gordura abdominal e sem sangramento importante.\nEvolui a partir do quinto dia pós-operatório com icterícia progressiva, dor abdominal de leve\nintensidade. A principal hipótese diagnóstica para esse caso é:","options":{"A":"Coleperitônio.","B":"Doença de Bouveret.","C":"Síndrome de Mirizzi.","D":"Lesão iatrogênica de via biliar.","E":"Lesão de artéria hepática esquerda."},"answer":"D","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-181327","number":"181327","sourceNumber":"181327","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente de 91 anos, hipertenso, diabético, amputação de membros inferiores\ninfragenicular há 2 anos, apresenta quadro\nde icterícia, adinamia e perda ponderal. Refere dispneia\nem repouso. Ao exame físico, regular estado geral, consciente, orientado, ictérico 3/4+, fc 82 bpm,\nfr 26. ECOG 3. Abdome globoso, flácido, fundo de vesícula palpável em rebordo costal direito,\nindolor. Propedêutica revela ausência de litíase em vesícula e via biliar, lesão em cabeça de\npâncreas de 4,5 cm em seu maior diâmetro, artérias mesentérica e hepática livres e veia\nmesentérica em íntimo contato com lesão em mais de 180 graus, adenopatias inter aorta-cavais.\n\nQual a conduta mais adequada para esse paciente?","options":{"A":"Drenagem biliar percutânea.","B":"Duodenopancreatectomia cefálica.","C":"Drenagem endoscópica de via biliar.","D":"Ecoendoscopia para estadiamento e biópsia de lesão para início de neoadjuvância.","E":"Ecoendoscopia para estadiamento e biópsia de lesão e drenagem de via biliar no mesmo ato."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-181359","number":"181359","sourceNumber":"181359","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Em relação aos abscessos hepáticos, é correto afirmar:","options":{"A":"pacientes idosos e diabéticos têm melhor prognóstico.","B":"as causas portais são mais frequentes que as criptogênicas.","C":"ocorre com mais frequência em homens, na proporção de 5:1.","D":"apendicite aguda é a principal causa de abscesso hepático piogênico.","E":"a incidência é baixa (entre 2 e 17 casos/100000 indivíduos) e é mais frequente na população\noriental."},"answer":"E","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-181376","number":"181376","sourceNumber":"181376","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Sobre as condições inflamatórias da vesícula e da via biliar, assinale a alternativa\ncorreta.","options":{"A":"A colangite branda é indicação de descompressão da via biliar de emergência.","B":"Em quadros de dengue a colecistite alitiásica infere um melhor prognóstico à doença.","C":"A síndrome de Mirizzi tipo I deve ser tratada com colecistectomia e anastomose bilio-digestiva.","D":"A vesícula esclero-atrófica é um processo inflamatório agudo e deve ser abordada nas primeiras\n48 horas do quadro.","E":"As colecistites agudas podem cursar com elevação dos níveis de amilase sem que haja um\nquadro de pancreatite aguda associado."},"answer":"E","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-158772","number":"158772","sourceNumber":"158772","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente alcoólatra crônico, masculino, 60 anos, é admitido no hospital com pancreatite\naguda. Tiveram episódios semelhantes no\npassado que foram resolvidos sem complicações. Foi\nverificado nos exames laboratoriais nível de amilase elevado e encontrado na tomografia\ncomputadorizada um pseudocisto pancreático. Qual o melhor tratamento para esse paciente?","options":{"A":"Aspiração simples.","B":"Tratamento cirúrgico.","C":"Drenagem percutânea.","D":"Tratamento endoscópico.","E":"Observação e tomografias seriadas de controle."},"answer":"E","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-161396","number":"161396","sourceNumber":"161396","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Sobre os tumores endócrinos pancreáticos funcionais, aponte a alternativa\nINCORRETA.","options":{"A":"O Insulinoma é o tumor funcionante mais comum do pâncreas endócrino, a idade média de\napresentação é de 45 anos, a localização predominante é corpo, cauda e cabeça pancreática.\nPodendo também se localizar, em menor incidência, no duodeno, hilo esplênico ou ligamento\ngastrocólico.","B":"A tríade de Whipple se caracteriza por sintomas de hipoglicemia neuroglicopênicos induzidos por\njejum, baixos níveis de glicose e alívio dos sintomas após administração de glicose.","C":"O Glucagonoma também tem incidência elevada. São mais comuns em homens, com tendência\na ser maior. Quase sempre se originam no\npâncreas. Apresentação clássica inclui diabetes,\ndermatite, trombose venosa profunda e depressão, e também\n\nestado catabólico grave.","D":"A síndrome de Zollinger-Ellison é decorrente da superprodução de gastrina, deve ser investigada\nnos pacientes com ulceração péptica grave\nrefratária, diarreia secretória persistente, esofagite\ngrave. Nível sérico elevado de gastrina, juntamente com pH inferior a 2 no aspirado gástrico, é\nquase diagnóstico da síndrome."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-161219","number":"161219","sourceNumber":"161219","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Assinale a alternativa INCORRETA com relação à coledocolitíase.","options":{"A":"A coledocolitíase primária é usualmente de cálculos pigmentares marrons, que são uma\ncombinação de pigmentos biliares precipitados e colesterol.","B":"Muitos cálculos do colédoco são clinicamente silenciosos e podem ser identificados por uma\ncolangiografia, se realizada rotineiramente durante a colecistectomia.","C":"A icterícia com coledocolitíase é mais provável de ser dolorosa, pois o começo da obstrução é\nagudo, causando rápida distensão do ducto biliar e irritação das fibras que causam a dor.","D":"A tríade de Charcot é caracterizada pela hipotensão, dor no quadrante superior direito e\nicterícia."},"answer":"D","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-158762","number":"158762","sourceNumber":"158762","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Dadas as afirmativas sobre a colelitíase e suas complicações, I. Pacientes que\ndesenvolvem síndrome de Mirizzi devem ser\ntratados com CPRE.; II. O exame padrão-ouro para\ndiagnóstico de colelitíase é a colangioressonância.; III. Estabelecido o diagnóstico de colangite\ngrave, suporte clínico intensivo e descompressão da via biliar são mandatórios.; IV. Pacientes com\npancreatite aguda biliar devem ser submetidos a CPRE e colecistectomia na mesma internação\napós resolução do quadro agudo. Verifica-se que está(ão) correta(s) apenas:","options":{"A":"II e IV.","B":"I e IV.","C":"I e III.","D":"III.","E":"II."},"answer":"D","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-161223","number":"161223","sourceNumber":"161223","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Assinale a alternativa INCORRETA a respeito dos fatores de risco da pancreatite\naguda.","options":{"A":"A pancreatite por cálculos biliares é mais observada em mulheres entre 50-70 anos de idade.","B":"O consumo excessivo de álcool é a segunda causa mais comum de pancreatite aguda no\nmundo e é mais prevalente em jovens do sexo\nmasculino (30-45 anos de idade).","C":"A lesão pancreática direta pode ser induzida por metabólitos triglicerídeos e deve ser suspeitada\nem pacientes com nível de triglicerídeo mais alto\ndo que 1.000 mg/dL.","D":"A hipotensão intraoperatória prolongada não tem relação com a pancreatite aguda."},"answer":"D","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-158774","number":"158774","sourceNumber":"158774","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Dadas as afirmativas sobre os abscessos hepáticos: I. A drenagem do abscesso\nhepático piogênico único deve ser realizada o\nmais precoce possível; II. Os abscessos múltiplos\napresentam incidência e mortalidade maiores em relação ao abscesso único; III. A principal causa\nde abscesso hepático piogênico é a apendicite tardiamente diagnosticada; IV. O abscesso\namebiano é único em 78% dos casos e é raro em cirróticos. Verifica-se que está (ão) CORRETA\n\n(S) apenas:","options":{"A":"I.","B":"I e IV.","C":"II e III.","D":"III e IV.","E":"I, II e III."},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-161227","number":"161227","sourceNumber":"161227","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Em relação à colecistite aguda alitiásica, assinale a alternativa INCORRETA.","options":{"A":"Embora a fisiopatologia exata seja pobremente compreendida, a concentração de solutos\nbiliares e a estase na vesícula biliar certamente têm um papel importante.","B":"Os fatores de risco para o desenvolvimento de colecistite alitiásica são: idade avançada,\ndoenças graves, queimaduras, trauma, uso prolongado\nde nutrição parenteral total, diabetes e\nimunossupressão.","C":"A drenagem percutânea de uma vesícula distendida e inflamada é indicada para todos os\npacientes com colecistite aguda alitiásica.","D":"O quadro clínico da colecistite alitiásica pode ser similar ao da doença calculosa com febre,\nanorexia e dor no quadrante superior direito."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-161237","number":"161237","sourceNumber":"161237","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Aponte a alternativa INCORRETA quanto às lesões polipoides da vesícula biliar.","options":{"A":"Os pólipos de colesterol se apresentam como lesões ecogênicas pediculadas da vesícula biliar,\ngeralmente menores que 1 cm, e frequentemente únicos.","B":"Adenomiomatose é observada como uma lesão séssil localizada comumente no fundo da\nvesícula, com características microcísticas dentro da lesão.","C":"Os adenomas são proliferações benignas da parede da vesícula que pode ser difíceis de\ndiferenciar de um adenocarcinoma no pré-operatório, porque a única diferença é a invasão\ntransmural, e detectá-la por ultrassonografia pode ser um desafio.","D":"Tamanho maior que 10 mm é um fator de risco para adenocarcinoma, junto com o crescimento,\npresença de cálculos na vesícula biliar, e\nidade acima dos 60 anos."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-161244","number":"161244","sourceNumber":"161244","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Assinale a alternativa INCORRETA acerca do câncer da vesícula biliar.","options":{"A":"O carcinoma da vesícula biliar é uma neoplasia agressiva que traz um prognóstico sombrio. O\nprognóstico desfavorável decorre da alta proporção de pacientes apresentando-se com doença\navançada.","B":"A presença de colelitíase é considerada como fator de risco primário, e cálculos maiores (> 3\ncm) trazem um risco aumentado de desenvolvimento de câncer.","C":"No estadiamento do câncer de vesícula biliar, os tumores T3 são aqueles que invadem o tecido\nconjuntivo perimuscular, sem extensão além da serosa ou intra-hepática.","D":"A vesícula em porcelana e pólipos de vesícula maiores que 10 mm são fatores de risco\nadicionais para o desenvolvimento do carcinoma."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-152664","number":"152664","sourceNumber":"152664","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Tumor de Klatskin é de origem:","options":{"A":"Biliar.","B":"Esplênica.","C":"Gástrica.","D":"Hepática.","E":"Duodenal."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-152668","number":"152668","sourceNumber":"152668","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente com colecistopatia crônica calculosa e coledocolitíase com colédoco de 8 mm\nde diâmetro, sem icterícia, o tratamento é:","options":{"A":"Colecistectomia videolaparoscópica.","B":"Colecistectomia convencional.","C":"Colecistectomia videolaparoscópica associada à exploração do colédoco por videolaparoscopia\npara retirada do(s) cálculo(s).","D":"Colecistectomia videolaparoscópica e a realização de CPRE com papilotomia para retirada do(s)\ncálculo(s).","E":"As respostas C e D estão corretas."},"answer":"E","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-152670","number":"152670","sourceNumber":"152670","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"No paciente cirrótico, como se faz o rastreamento na pesquisa de hepatocarcinoma?","options":{"A":"Ultrassonografia + dosar alfa-fetoproteína a cada seis meses.","B":"Ultrassonografia + dosar antígeno carcinogênico embrionário (CEA) a cada três meses.","C":"Tomografia de seis em seis meses.","D":"Dosar alfa-fetoproteína, CEA e CA 19-9 de seis em seis meses.","E":"Ultrassonografia + dosar CA 19-9 a cada seis meses."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-134874","number":"134874","sourceNumber":"134874","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente de 65 anos, sexo masculino, portador de laparotomia prévia (ráfia de úlcera\nduodenal perfurada há 15 anos), vem ao pronto-socorro com queixa de dor abdominal, náuseas,\nvômitos (inicialmente com restos alimentares e depois biliosos), além da parada de eliminação de\ngases e fezes há 24 horas. Ao exame clínico, apresenta algum grau de desidratação, distensão\nabdominal e ruídos hidroaéreos presentes e aumentados. A radiografia do abdome mostra\ndistensão das alças do intestino delgado com a presença de níveis hidroaéreos. Considerando o\ndiagnóstico de abdome agudo obstrutivo, sendo uma suboclusão intestinal, a MELHOR conduta,\nneste caso, é:","options":{"A":"Laparotomia exploradora.","B":"Descompressão abdominal através de sonda nasogástrica aberta em sifonagem e correção\nhidroeletrolítica.","C":"Tomografia abdominal.","D":"Êntero-clisma com solução glicerinada."},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-131346","number":"131346","sourceNumber":"131346","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Qual o exame mais importante para a pesquisa de câncer de reto?","options":{"A":"Toque retal.","B":"Pesquisa de sangue oculto nas fezes.","C":"Ultrassom abdominal.","D":"Todas as anteriores.","E":"NDA."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-131338","number":"131338","sourceNumber":"131338","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Qual das seguintes afirmações está CORRETA em relação às angiodisplasias do\ncólon?","options":{"A":"Fulguração da angiodisplasia deve ser realizada durante uma colonoscopia eletiva,\nindependente da história de sangramento anterior.","B":"O sangramento da angiodisplasia é mais comum no lado esquerdo do paciente idoso.","C":"Uma angiografia normal durante um sangramento ativo exclui angiodisplasia como causa de\nhemorragia.","D":"As angiodisplasias variam de 1,5 a 2 mm e histologicamente são caracterizadas por capilares\ndilatados e tortuosos localizados na lâmina própria.","E":"Nenhuma das alternativas acima está correta."},"answer":"D","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-131356","number":"131356","sourceNumber":"131356","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Febre alta, taquicardia, dilatação colônica e leucocitose. Pensar em:","options":{"A":"Doença de Chron.","B":"Enteropatia chagásica.","C":"Megacólon tóxico.","D":"Diverticulose.","E":"Apendicite."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-131369","number":"131369","sourceNumber":"131369","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"O câncer colorretal, que ocorre durante a gravidez, é mais comum no:","options":{"A":"Reto.","B":"Sigmoide.","C":"Descendente.","D":"Transverso.","E":"Ascendente."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-109730","number":"109730","sourceNumber":"109730","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Homem de 62 anos com dor na fossa ilíaca esquerda há 1 semana, acompanhada de\ndiarreia. Dor evolutiva, náuseas, vômitos e febre. Já teve dois episódios similares. Um com\nremissão espontânea e outro à custa de antibiótico via oral. Não possui fator de risco\ncardiopulmonar. Ao exame clínico está febril (39ºC), taquicárdico (115/min) e normotenso. Abdome\nflácido e ligeiramente distendido, com dor à palpação do quadrante inferior esquerdo e\ndescompressão brusca positiva na fossa ilíaca esquerda. Leucocitose de 20.000/mm³. Qual é a\nhipótese diagnóstica e o próximo passo investigatório, RESPECTIVAMENTE?","options":{"A":"Abdome agudo e RX do abdome.","B":"Abdome agudo e ultrassonografia de abdome.","C":"Diverticulite aguda e ultrassonografia de abdome.","D":"Diverticulite aguda e tomografia computadorizada do abdome."},"answer":"D","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-110032","number":"110032","sourceNumber":"110032","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Das alternativas abaixo, qual delas apresenta um fator que interfere em pior\nprognóstico, o caso de abdome agudo obstrutivo?","options":{"A":"Obstrução do 1/3 proximal do intestino delgado.","B":"Obstrução do sigmoide.","C":"Estrangulamento de alça intestinal.","D":"Insuficiência renal aguda."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-86674","number":"86674","sourceNumber":"86674","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"As afirmativas abaixo são causas mais comuns de hemorragia digestiva baixa no adulto\njovem: I ? Divertículo de Meckel, pólipos. II ? Câncer, angiodisplasia. III ? Doença inflamatória\nintestinal, pólipos.","options":{"A":"Apenas afirmativa I está correta.","B":"Apenas afirmativas I e II estão corretas.","C":"Apenas afirmativa II está correta.","D":"Apenas afirmativa III está correta.","E":"Todas afirmativas estão erradas."},"answer":"D","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-86820","number":"86820","sourceNumber":"86820","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"A causa mais frequente de hemorragia digestiva baixa é:","options":{"A":"Neoplasia do intestino grosso;","B":"Hemorroidas;","C":"Doença diverticular;","D":"Varizes colônicas;","E":"Colites."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-86665","number":"86665","sourceNumber":"86665","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Qual dos agentes seguintes tem demonstrado melhora no índice de fechamento de\nfístulas enterocutâneas em doença de Crohn?","options":{"A":"Metotrexate.","B":"5-ASA.","C":"Infliximab.","D":"Corticoide.","E":"Azatioprina."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-86678","number":"86678","sourceNumber":"86678","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Correlacione a primeira coluna com a segunda conforme seus conhecimentos: 1. CEA;\n\n2. CA 72.4; 3. CA 19.9; 4. Alfafetoproteína; 5. CA-125. ( ) CA de ovário ( ) Hepatocarcinoma ( ) CA\nde cólon ( ) CA gástrico ( ) CA de pâncreas","options":{"A":"5-4-2-3-1.","B":"4-5-3-2-1.","C":"3-4-5-2-1.","D":"1-3-5-4-2.","E":"5-4-1-2-3."},"answer":"E","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-158441","number":"158441","sourceNumber":"158441","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"O carcinoma hepatocelular é a neoplasia primária do fígado mais comum, responsável\npor pelo menos meio milhão de mortes\nanualmente no mundo. Com relação ao tratamento cirúrgico\nde ressecção hepática, marque a INCORRETA:","options":{"A":"A ressecção hepática não é bem tolerada em pacientes cirróticos (Child-Pugh C).","B":"No que se refere a pacientes com função hepática ruim, estes não devem ser operados.","C":"Constitui fator prognóstico negativo: tumores grandes (> 5 cm), multifocais, invasão vascular,\nalto grau de diferenciação celular.","D":"Constitui contraindicação para ressecção hepática a presença de metástases extra-hepáticas\nlinfonodos regionais.","E":"Tempo de protrombina é um dos critérios da classificação Child-Pugh."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-158443","number":"158443","sourceNumber":"158443","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Com relação à patologia representada pela figura abaixo marque a assertiva\nINCORRETA: (Conforme imagem do caderno de questões)","options":{"A":"Na seta maior nota-se imagem hipoecogênica com sombra acústica posterior caracterizando um\ncálculo na vesícula biliar.","B":"As setas menores evidenciam espessamento e edema da parede da vesícula biliar característica\nde processo inflamatório da colecistite.","C":"A dor em quadrante superior direito do abdome associado a anorexia, náuseas, vômito e febre\nsão características da patologia indicada.","D":"Em 30% dos casos é possível palpar massa no hipocôndrio direito que normalmente representa\num bloqueio do omento e alças intestinais em\nresposta ao processo inflamatório da vesícula.","E":"Pancreatite aguda, hepatite, e apendicite aguda são as principais doenças que devem ser\nincluídas no diagnóstico diferencial de colecistite aguda."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":["question_bank/media/medcurso/medcurso-gastrologia-gas-3/158443.png"],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-108564","number":"108564","sourceNumber":"108564","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente ictérico, com dor e distensão abdominal, parada na eliminação de gases e\nfezes, febril e com episódios de vômito.\nQual o exame de imagem você solicitaria inicialmente neste\ncaso?","options":{"A":"TC abdome.","B":"USG abdome.","C":"CPRE.","D":"Rotina radiológica para abdome agudo.","E":"Colangioressonância."},"answer":"D","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-108571","number":"108571","sourceNumber":"108571","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Assinale a INCORRETA:","options":{"A":"As principais causas de erro na condução do abdome agudo são a história e o exame físico\nincompletos.","B":"A combinação de uma história clínica e um exame físico corretos permite identificar as doenças\nem 75 a 90% dos pacientes.","C":"Em pacientes com dor abdominal de etiologia não-esclarecida, a avaliação seriada contribui para\no acerto do diagnóstico, com sensibilidade\nequivalente a alguns exames de imagem.","D":"A dor referida ao toque retal é comum e patognomônica de várias patologias.","E":"A maioria dos pacientes idosos com colecistite e apendicite aguda apresenta-se afebril."},"answer":"D","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-108572","number":"108572","sourceNumber":"108572","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente de 30 anos, no quarto mês de gestação, com quadro clínico sugestivo de\napendicite aguda. Assinale a alternativa INCORRETA:","options":{"A":"A apendicite é a causa mais frequente de abdome agudo na gestação.","B":"Apendicite ocorre em mulheres grávidas e não grávidas da mesma faixa etária na mesma\nproporção.","C":"Esse caso requer cirurgia imediata.","D":"Apendicites complicadas resultam em mortalidade\n\nfetal de 20% e desencadeamento de parto prematuro em cerca de 10% dos casos.","E":"A conduta conservadora seria indicada para esse caso somente se a mãe estivesse em sepse,\npara preservar as condições do feto."},"answer":"E","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-108573","number":"108573","sourceNumber":"108573","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente deu entrada no atendimento de urgência com quadro de dor abdominal em\nquadrante inferior esquerdo, astenia, febre moderada e dificuldade para evacuar. Ao exame físico\napresenta abaulamento doloroso à palpação nessa região. Qual o exame ideal para estabelecer o\ndiagnóstico e a conduta desse caso?","options":{"A":"Ultrassonografia do abdome.","B":"Enema opaco.","C":"Colonoscopia.","D":"Tomografia do abdome.","E":"Enteroscopia."},"answer":"D","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-49590","number":"49590","sourceNumber":"49590","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"A causa mais comum de obstrução intestinal é:","options":{"A":"Mecânica.","B":"Neoplásica.","C":"Verminose.","D":"Corpo estranho.","E":"Hidroeletrolítica."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-49601","number":"49601","sourceNumber":"49601","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente masculino, 65 anos, com queixa de dor abdominal tipo cólica, associada com\ndistensão abdominal, parada de eliminação de gases e fezes, há 24h. Relata início de vômitos\nbiliosos, há 6 horas. Ao exame físico, observa-se: PA:140 x 90 mmHg, FC: 100 bpm, FR 28 rpm,\nTax: 38°C, desidratação +++/4+. Abdome globoso, timpânico, doloroso difusamente à palpação\nprofunda. Ruídos hidroaéreos metálicos. A conduta imediata é:","options":{"A":"Avaliar as condições circulatórias e respitatórias e estabilizá-las.","B":"Descompressão imediata do trato digestivo alto.","C":"Iniciar ventilação não invasiva.","D":"Encaminhar ao centro cirúrgico imediatamente.","E":"Acesso venoso profundo."},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-49646","number":"49646","sourceNumber":"49646","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente de 17 anos, feminina, foi atendida no Ambulatório de Coloproctologia com\nqueixas de eliminação de sangue nas fezes, há dois meses. Ao exame clínico, encontrava-se com\nbom estado geral, corada e o exame proctológico evidenciou a presença de múltiplos pólipos\npequenos, sésseis e pediculados em reto e sigmoide. Relata que o pai faleceu com câncer de reto\naos 38 anos e tem dois tios que foram operados devido a tumores no intestino. Após realizar uma\ncolonoscopia, retornou com o resultado que revelou polipose múltipla em todo o cólon e reto, o\nlaudo histopatológico foi adenomas. A hipótese diagnóstica mais provável é:","options":{"A":"Polipose adenomatosa.","B":"Polipose juvenil.","C":"Síndrome de Peutz-Jeghers.","D":"Síndrome de Lynch.","E":"Síndrome de Cowden."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-49648","number":"49648","sourceNumber":"49648","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente de 17 anos, feminina, foi atendida no Ambulatório de Coloproctologia com\nqueixas de eliminação de sangue nas fezes, há dois meses. Ao exame clínico, encontrava-se com\nbom estado geral, corada e o exame proctológico evidenciou a presença de múltiplos pólipos\npequenos, sésseis e pediculados em reto e sigmoide. Relata que o pai faleceu com câncer de reto\naos 38 anos e tem dois tios que foram operados devido a tumores no intestino. Após realizar uma\ncolonoscopia, retornou com o resultado que revelou polipose múltipla em todo o cólon e reto, o\nlaudo histopatológico foi adenomas. A conduta terapêutica mais recomendada para a paciente é:","options":{"A":"Proctocolectomia total e anastomose ilional.","B":"Proctocolectomia total e ileostomia.","C":"Polipectomias endoscópicas seriadas.","D":"Proctocolectomia total e anastomose bolsa-ilioanal.","E":"Colonoscopia anual."},"answer":"D","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-49571","number":"49571","sourceNumber":"49571","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Em uma linha imaginária que vai do umbigo à espinha ilíaca anterossuperior, o ponto\nlocalizado na junção do 1/3 médio com o lateral é chamado:","options":{"A":"Davis.","B":"Kehr.","C":"Kocher.","D":"Mc Burney.","E":"Rovsing."},"answer":"D","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-362491","number":"362491","sourceNumber":"362491","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente do sexo feminino, 48 anos, deu entrada no pronto socorro queixando dor\nintensa, de início súbito, em região\nepigástrica e que irradiava para o dorso, associada a vômitos,\ncom evolução de 8 horas. Se apresentava normocorada, anictérica, levemente dispneica e\nnormotensa, com abdome bastante doloroso à palpação em todo o andar superior, sem sinais de\nirritação peritoneal. A paciente foi internada para investigação e seus exames laboratoriais\nevidenciaram 12.000 leucócitos com desvio à esquerda, hematócrito e hemoglobina normais,\nfosfatase alcalina 250U/l, amilase 2.300mg/dl e ultrassonografia com colelitíase. Foi prescrita\nhidratação venosa, analgesia potente e antieméticos, mas não foram iniciados antibióticos. A\npaciente evoluiu com estabilidade hemodinâmica, bom débito urinário e regularização da frequência\nrespiratória, porém manteve quadro de importante desconforto abdominal. No 5° dia de internação,\nfoi submetida a tomografia que evidenciou vesícula biliar tópica, normodistendida, com cálculos e\naumento do volume e heterogeneidade pancreática com formação de coleção de cerca de 9,0 x\n4,0cm ao longo do corpo do pâncreas e densificação da gordura adjacente, sem sinais de\ncompressão gástrica. Sobre o caso descrito, assinale a alternativa CORRETA:","options":{"A":"A ausência da antibioticoterapia no tratamento inicial foi responsável pela complicação descrita\nacima.","B":"Por tratar-se de abscesso peripancreático, o próximo passo na conduta do caso é a drenagem\ncirúrgica da loja pancreática.","C":"A evolução insatisfatória do caso e a formação da coleção pancreática, classificam o caso como\npancreatite grave e indica início imediato de antibioticoterapia de largo espectro.","D":"Já que não há compressão gástrica e a paciente se encontra hemodinamicamente estável, o\ntratamento da coleção neste momento é expectante e sem uso de antibióticos."},"answer":"D","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-362512","number":"362512","sourceNumber":"362512","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente do sexo feminino, 35 anos, é transferida de Manacapuru para investigação\ndiagnóstica e continuidade de tratamento.\nEstava internada por 3 dias com história de dor tipo\ncólica em HD associada a vômitos, após alimentação rica em gordura, sendo tratada clinicamente\ncom analgésicos e antiespasmódicos. À admissão em Manaus, encontrava-se em BEG, lúcida,\neupneica, ictérica +14, normotensa. Seu abdome era globoso, doloroso a palpação profunda em\nHD, sem irritação peritoneal. Sua investigação laboratorial evidenciou leucograma 7.500 leucócitos,\nhemoglobina 12g/dl e hematócrito 38%, transaminases normais, bilirrubina total 3,5mg/dl, bilirrubina\ndireta 3,2mg/dl, fosfatase alcalina 350mg/dl, Gama GT 680mg/dl e amilase 120mg/dl. O paciente foi\nsubmetido a ultrassom à beira do leito que evidenciou vesícula de paredes finas contendo\nmicrocálculos e via biliar principal de 1 cm de diâmetro. Sobre o caso descrito, assinale a\nalternativa\nINCORRETA:","options":{"A":"A opção diagnóstica e terapêutica invasiva de escolha para o caso é a associação da\nultrassonografia endoscópica com a varredura da via\nbiliar por colangiopancreatografia retrógrada\nendoscópica.","B":"Há risco de pancreatite aguda após o procedimento terapêutico endoscópico neste caso.","C":"Caso o tratamento endoscópico tenha sucesso para tratamento da patologia acima, a conduta\nmais adequada seria alta hospitalar para\ncolecistectomia laparoscópica eletiva após 8 semanas.","D":"Caso o tratamento endoscópico não obtenha sucesso para tratamento da patologia acima, a\nabordagem da via biliar principal via laparoscopia tem melhores resultados que a via laparotômica,\ndesde que o cirurgião tenha habilidade suficiente na condução cirúrgica do caso."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-362503","number":"362503","sourceNumber":"362503","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente do sexo feminino, 62 anos, tabagista e diabética, apresenta quadro de icterícia\nprogressiva há cerca de 1 mês, associada a prurido cutâneo e emagrecimento, sendo internada\npara investigação diagnóstica. Seu exame físico apresentava icterícia +++/4 e massa palpável,\nindolor, de contornos bem definidos em HD. Ausência de linfonodos cervicais palpáveis. Sua\navaliação laboratorial evidenciou leucograma e transaminases normais, bilirrubina total: 12mg/dI,\nbilirrubina direta: 11 ,5mg/dI, fosfatase alcalina: 840mg/dl, gama GT: 1.200mg/dl e CA 19-9:\n250U/mI. Optou-se pela solicitação de tomografia computadorizada com contraste venoso que\nevidenciou volumosa dilatação da vesícula biliar e das vias biliares intra e extra-hepáticas, além\nde\nmassa sólida de 5cm em cabeça do pâncreas que invade colédoco distal e tem íntima relação com\nos vasos mesentéricos. Sobre o caso, assinale a alternativa CORRETA:","options":{"A":"Caso observemos envolvimento menor que 180 graus da circunferência da artéria mesentérica\nsuperior, a quimioterapia neoadjuvante pode\ntornar a ressecção tumoral factível.","B":"A definição da conduta frente a esta tumoração depende de biópsia aspirativa por agulha,\nrealizada via radiologia intervencionista.","C":"Não existe possibilidade de tratamento curativo sem a duodenopancreatectomia e, apesar deste\nprocedimento ter morbidade elevada, ele é amplamente acessível já que a maior parte dos\npacientes apresenta doença ressecável ao diagnóstico.","D":"Caso constatada a irressecabilidade do tumor, o tratamento endoscópico paliativo da icterícia\ndeste paciente é contraindicado."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-327242","number":"327242","sourceNumber":"327242","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Você é chamado para avaliar uma paciente de 60 anos, obesa e diabética, que está\ninternada há 3 dias devido a quadro de dor tipo cólica em HD, irradiada para o dorso, associada a\nvômitos, após ingesta de alimentação rica em gordura. Refere episódios semelhantes prévios que\nmelhoraram com analgesia no domicílio. Na sua admissão, foi realizada ultrassonografia de\nabdome que evidenciou vesícula biliar de paredes espessadas e cálculo de 1,5cm impactado em\ninfundíbulo, sendo internada para tratamento clínico com dieta zero e analgesia. Neste momento,\nqueixa de manutenção do quadro doloroso e náuseas. Nega febre desde o início do quadro. Seu\nestado geral é bom e encontra-se eupneica, afebril, anictérica e normotensa. Seu abdome é\ngloboso, doloroso à palpação profunda em HD, com sinal de Murphy positivo e plastrão palpável.\nSobre a avaliação e proposta terapêutica desta paciente, assinale a alternativa CORRETA:","options":{"A":"A falha no tratamento clínico foi devida a ausência de prescrição de antibióticos na admissão","B":"A ausência de febre e de comprometimento sistêmico sugere que podemos seguir com o\ntratamento clínico, estando indicada a\ninvestigação diagnóstica com ressonância magnética de vias\nbiliares","C":"O quadro agudo sem remissão com o tratamento clínico, em paciente obesa, na sexta década\nde vida, contraindica a abordagem\nlaparoscópica no caso acima","D":"O quadro descrito acima possivelmente evoluiu com elevação das titulações séricas das\ntransaminases e proteína C reativa, com\nbilirrubinas, fostatase alcalina e gama GT sem alterações\nrelevantes."},"answer":"D","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-327248","number":"327248","sourceNumber":"327248","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente do sexo masculino, 65 anos, sobrepeso, tabagista e diabético, procura\natendimento médico devido a quadro de icterícia progressiva e inapetência há cerca de 1 mês.\nNega dor abdominal ou vômitos. Ao exame físico, apresenta-se em BEG, eupneico, afebril,\nnormotenso, ictérico +++/4, com abdome plano, flácido, indolor à palpação. Sinal de\nCurvoisier-Terrier presente. Sinal de Murphy negativo. Perfil laboratorial: Hematócrito 32%,\nHemoglobina 11g/dl; Bilirrubinas totais: 18mg/dl, Bilirrubina direta: 15mg/dl, Fosfatase alcalina:\n\n634mg/dl e GamaGT: 1.200mg/dl. Foi submetida a USG de abdome que evidenciou ausência de\ncálculos na vesícula biliar, dilatação expressiva do colédoco e massa sólida na cabeça do\npâncreas. Sobre o caso descrito, assinale a alternativa INCORRETA:","options":{"A":"Os dados acima não nos permitem avaliar adequadamente o diagnóstico e o estadiamento da\npatologia em questão, estando indicada tomografia computadorizada helicoidal contrastada com\ncortes finos na topografia pancreática e a dosagem sérica de CA 19-9.","B":"A avaliação do envolvimento dos vasos mesentéricos e veia portal é crucial para a definição da\nmodalidade de tratamento cirúrgico, seja a duodenopancreatectomia curativa ou modalidades\ncirúrgicas paliativas como a anastomose bilio-digestiva e alcoolização do plexo celíaco.","C":"Estudos recentes demonstram que a avaliação tomográfica de massas na cabeça do pâncreas\ntem acurácia superior a ultrassonografia\nendoscópica, sobretudo em nodulações de pequeno\nvolume, limitando a sua indicação para a realização de biópsia de pacientes com doença avançada.","D":"Caso o paciente apresente massas passíveis de ressecção ou em situação borderline, com\ninvasão parcial dos vasos mesentéricos e veia porta, a conduta terapêutica inicial para o caso é a\nquimioterapia neoadvuvante associada ou não a radioterapia."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-327250","number":"327250","sourceNumber":"327250","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente do sexo feminino, 34 anos, dá entrada no pronto atendimento com quadro de\ndor em HD associada a vômitos, que migrou\npara o dorso e todo o abdome superior após algumas\nhoras, evoluindo com piora expressiva de intensidade. Refere episódios prévios de dor em HD, mas\nnunca tão intensos. Ao exame físico, a paciente se encontrava bastante desidratada, taquicárdica,\nlevemente dispneica, normotensa e oligúrica. Seu abdome era plano, bastante doloroso à palpação\nprofunda em todo andar superior do abdome, sem irritação peritoneal. Sua investigação\npropedêutica revelou colelitíase, leucocitose discreta e hiperamilasemia. A paciente foi internada\nem dieta zero, sendo prescrita hidratação venosa, analgesia com derivados da morfina e\nantieméticos. Após 48h, evoluiu com estabilização hemodinâmica, normalização da frequência\nrespiratória e do débito urinário, porém mantinha quadro doloroso abdominal, agora com distensão,\nsendo mantida a internação. No 8º dia de internação, evoluiu com sinais de choque e febre, sendo\nsubmetido a tomografia de abdome que revelou coleção peripancreática contendo gás no seu\ninterior. Sobre o caso acima, assinale a alternativa CORRETA:","options":{"A":"Podemos afirmar que o paciente evoluiu de forma insatisfatória porque não foi iniciada\nantibioticoterapia ao ser definido o diagnóstico de pancreatite aguda moderadamente grave.","B":"A conduta adequada é a coleta de hemocultura ou coleta de secreção guiada por tomografia\npara cultura, início de antibioticoterapia de largo\nespectro e tratamento de suporte do estado de\nchoque, não estando indicada a abordagem cirúrgica neste momento.","C":"A nutrição parenteral, quando iniciada após as 48h de internação, é considerada profilática para\na complicação descrita acima.","D":"Os dados fornecidos nos permitem afirmar que havia indicação de colecistectomia de urgência\napós 48 horas do início do quadro e a perda\ndo timing do tratamento cirúrgico ocasionou a\ncomplicação descrita."},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-298194","number":"298194","sourceNumber":"298194","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"A dor abdominal é a manifestação mais comum e marcante da pancreatite crônica.\nEntre as características citadas, qual delas\nNÃO é comumente encontrada?","options":{"A":"Crises dolorosas recorrentes.","B":"Alívio com alimentação.","C":"Duração de 1 a 7 dias.","D":"Precipitada pelo abuso de álcool."},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-298210","number":"298210","sourceNumber":"298210","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente do sexo masculino, 48 anos, apresenta história de picos febris diários que\nevoluiu com dor contínua e progressiva, em hipocôndrio direito, associada a náuseas e vômitos.\nEvolução de 2 semanas. Ao exame físico, apresenta-se em BEG, eupneico, febril, ictérico ++/4,\nhemodinamicamente estável. Seu abdome é plano, flácido, doloroso à palpação profunda em\nhipocôndrio direito, sem irritação peritoneal. Hepatomegalia palpável. Leucograma: 18.000. A\nultrassonografia de abdome evidência volumosa coleção heterogênea, com debris em seu interior,\nem lobo hepático direito, com cerca de 15cm no maior diâmetro. Sobre o caso acima, assinale a\nalternativa CORRETA:","options":{"A":"A determinação da etiologia do caso é essencial para o direcionamento terapêutico e escolha da\nabordagem invasiva do tratamento.","B":"A evolução sub-aguda do caso nos permite inferir que o tratamento clínico para amebíase será\nresolutivo para o caso.","C":"A drenagem percutânea da loja, guiada por tomografia, pode ser opção adequada à drenagem\nvia laparotomia.","D":"O perfil laboratorial esperado para o caso inclui anemia severa, hipoalbuminemia,\nhiperbilirrubinemia indireta e transaminases normais."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-298220","number":"298220","sourceNumber":"298220","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente do sexo feminino, 42 anos, queixa dor abdominal de início súbito em\nhipocôndrio direito associada a mal-estar e\ntontura, há cerca de 2 horas. Nega episódios anteriores,\nfebre, vômitos e sintomas urinários. Nega comorbidades e a única medicação que faz uso regular é\nde anticoncepcional oral há 20 anos. Apresenta-se em BEG, anictérica, hipocorada, FC: 110bpm,\nFR: 26irpm e P.A.: 90x70mmHg, que normalizaram após infusão em bolus de 1.000ml de Ringer\nLactato. Seu abdome é plano, flácido, moderadamente doloroso à palpação do HD, sem irritação\nperitoneal. Leucograma normal, hemoglobina 7g/dl, hematócrito 22%. Demais exames laboratoriais\nnormais. Foi submetida a tomografia de abdome que evidenciou fígado de aspecto homogêneo,\nlesão tumoral de 6cm em lobo direito do fígado com sinais de sangramento recente e moderada\nquantidade de líquido livre na cavidade abdominal. Sobre o caso descrito, assinale a alternativa\nCORRETA:","options":{"A":"O caso ilustra clássica complicação de hiperplasia nodular focal, estando indicada a ressecção\ntumoral de urgência.","B":"Após estabilização do quadro de sangramento, há indicação de ressecção tumoral eletiva devido\na considerável potencial de malignidade.","C":"O quadro de sangramento sugere fortemente o diagnóstico de hemangioma hepático, estando\nindicado tratamento quimioterápico após recuperação do quadro urgente.","D":"A paciente deve ser submetida a colonoscopia para investigação de neoplasia primária de cólon."},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-298223","number":"298223","sourceNumber":"298223","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente do sexo feminino, 42 anos, com histórico de colelitíase, apresentou quadro de\ndor em hipocôndrio direito, tipo cólica, que rapidamente se tornou constante e intensa, migrando\npara todo o andar superior do abdome, há cerca de 6 horas, associada a vômitos, sendo internada\nno serviço de pronto atendimento. Seu abdome era globoso, doloroso à palpação profunda do\nandar superior, sem irritação peritoneal. Na investigação laboratorial, observou-se hiperamilasemia\nde 2.350mg/dl. Foi mantida em dieta zero com hidratação venosa e analgesia potente e evoluiu\napós 48 horas com manutenção da dor e dos vômitos, distensão abdominal, sinais clínicos de\ndesidratação moderada e hipotensão, taquipnéia, acidose metabólica à gasometria arterial e\nelevação da contagem de leucócitos e das titulações de uréia e creatinina séricas. Bilirrubinas,\ngama GT e fosfatase alcalina normais. Sobre o caso descrito, assinale a alternativa CORRETA:","options":{"A":"A nutrição parenteral é mais efetiva no tratamento desta paciente que a nutrição enteral,\nprincipalmente no que se refere a profilaxia da translocação bacteriana e diminuição da\nmortalidade.","B":"Há clara evolução para choque séptico, estando indicado o início de Imipenem e laparotomia\npara desbridamento do foco infeccioso.","C":"O paciente provavelmente preencherá critérios no score de Marshall para disfunção persistente\nde órgãos, evidenciando evolução grave, estando\nindicada terapia intensiva com tratamento de\nsuporte.","D":"Devido a provável evolução com abscesso retroperitoneal, a tomografia está indicada neste\nmomento, confirmando a indicação de laparotomia urgente para esta paciente."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-298224","number":"298224","sourceNumber":"298224","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente do sexo feminino, 26 anos, obesa, comparece ao ambulatório com uma\nultrassonografia evidenciando colelitíase. Refere apresentar discreto desconforto em hipocôndrio\ndireito e epigástrio e plenitude após alimentação rica em gordura, mas que melhora com medicação\nno domicílio. Nega crises de dor intensa, vômitos e internações hospitalares. Ao exame físico, se\napresenta em BEG, eupneica, afebril, anictérica, estável. Seu abdome é plano, flácido e indolor à\npalpação. Sobre o caso acima, qual das orientações a esta paciente pode ser considerada\nINCORRETA?","options":{"A":"Uma complicação possível da crise de inflamação na vesícula é a migração de um microcálculo\npara a via biliar principal, causando\nicterícia e indicando a realização de retirada deste cálculo por\nvia endoscópica.","B":"A obesidade é considerada um fator predisponente para a formação de cálculos na vesícula,\nprincipalmente se estiver associada com elevados índices de colesterol no sangue.","C":"Uma dieta sem gorduras, tais como frituras, óleo e azeites, pode evitar que a senhora entre em\ncrise de dor aguda e inflamação da vesícula até a programação da sua cirurgia laparoscópica.","D":"A senhora tem que operar essa vesícula o mais breve possível porque caso a senhora tenha\numa crise aguda de dor e necessite cirurgia de urgência, esta não poderá ser realizada por\nlaparoscopia."},"answer":"D","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-298228","number":"298228","sourceNumber":"298228","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente do sexo masculino, 52 anos, queixa de icterícia progressiva há 1 mês,\nassociada a prurido em todo o corpo, perda\nde peso (10kg em 2 meses), inapetência e alteração da\ncoloração da urina (?cor de guaraná?). Ao exame físico, o paciente encontra-se ictérico +++/4,\neupneico, afebril e hemodinamicamente estável. Seu abdome é plano, flácido, com vesícula\npalpável, aumentada de tamanho, indolor à palpação. Seu hemograma é normal, mas apresenta\ndosagem de bilirrubinas totais aumentadas (12,5mg/dl) às custas de bilirrubina direta (10,8mg/dl)\nalém de elevação da fosfatase alcalina e gama-GT. Sobre o caso acima, assinale a alternativa\nINCORRETA:","options":{"A":"Em caso de neoplasias periampulares, a ultrassonografia endoscópica apresenta papel\nirrelevante na avaliação da ressecabilidade do tumor.","B":"O primeiro exame de imagem indicado para o caso é a ultrassonografia abdominal para exclusão\nde colelitíase e avaliação de sinais de obstrução\nda via biliar principal.","C":"A presença do sinal de Courvoisier descrito acima sugere fortemente o diagnóstico de obstrução\ntumoral da via biliar extra-hepática,\nestando indicada a tomografia para investigação.","D":"Adenocarcinoma de cabeça de pâncreas, colangiocarcinoma de colédoco e tumores de papila\nduodenal fazem parte do diagnóstico diferencial para o caso."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-286720","number":"286720","sourceNumber":"286720","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente do sexo feminino, 38 anos, dá entrada no pronto atendimento com quadro de\ndor tipo cólica em hipocôndrio direito,\nbastante intensa, associada a vômitos, há 8 horas, sendo\ninternada para analgesia e investigação diagnóstica. Refere episódios prévios de menor\nintensidade nos últimos meses, associados à alimentação rica em gordura. Evoluiu com melhora do\nquadro doloroso e dos vômitos, porém iniciou icterícia no segundo dia de internação hospitalar. Não\napresentou febre. Neste momento, seu abdome é plano, flácido, indolor à palpação. Assinale a\nalternativa CORRETA:","options":{"A":"Apesar da ressonância magnética estar indicada para a definição etiológica do caso, a CPRE\nprovavelmente teria papel tanto diagnóstico como terapêutico.","B":"Esperamos observar elevados níveis séricos de transaminases e bilirrubina não conjugada no\nperfil laboratorial desta paciente.","C":"O quadro doloroso inicial complicado pela icterícia indica drenagem cirúrgica das vias biliares\nem\ncaráter de urgência pelo risco de colangite supurativa aguda.","D":"A evolução com icterícia contraindica a abordagem laparoscópica no tratamento desta paciente."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-286729","number":"286729","sourceNumber":"286729","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente do sexo feminino, 55 anos, obesa, diabética, refere quadro de dor tipo cólica\nem hipocôndrio direito que irradiou para todo o\nandar superior do abdome e dorso, tornando-se\ncontínua e intensa, há cerca de 12 horas, associada a náuseas e vômitos. Nega febre, diarreia e\nsintomas urinários. Ao exame físico, apresenta-se com fácies de dor, em bom estado geral, LOTE,\nafebril, FC: 72 bpm, FR: 24 irpm, anictérica e P.A.: 120 x 80 mmHg. Débito urinário satisfatório.\nSeu\nabdome é algo distendido, bastante doloroso à palpação do andar superior, sem sinais de irritação\nperitoneal. Hematócrito: 40%. Leucograma: 12.000. Amilase sérica: 1.800 g/dl.\n\nAssinale a alternativa CORRETA:","options":{"A":"Devemos ser cautelosos quanto à hidratação desta paciente, pois volumes superiores a 2.000 ml\nde Ringer Lactato nas primeiras 24 horas estão associados a evolução desfavorável do quadro.","B":"À admissão, a ultrassonografia seria dispensável por não evidenciar de forma precisa o grau de\nacometimento local pancreático, estando indicada a tomografia computadorizada.","C":"Os dados acima não nos permitem avaliar e classificar adequadamente a gravidade do caso,\nsendo necessária a observação clínica de falência de órgãos e sistemas por 48h.","D":"Uma vez que esta paciente apresenta fatores de risco para evolução desfavorável do quadro,\nestá indicada a antibioticoterapia com\nCiprofloxacino e Metronidazol."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-252231","number":"252231","sourceNumber":"252231","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"O câncer de pâncreas é a quarta causa mais comum de morte relacionada ao câncer\nentre homens e mulheres nos Estados Unidos\n(EUA). A sua incidência aumentou de 1999 a 2008,\npossivelmente por causa do aumento da prevalência de obesidade, idade da população e outros\nfatores desconhecidos. Qual a opção CORRETA sobre o rastreio dos tumores pancreáticos?","options":{"A":"Pacientes diabéticos, com diagnóstico acima de 50 anos, devem ser seguidos anualmente.","B":"Não há recomendação de rastreio para pacientes assintomáticos.","C":"Solicitação anual de biomarcador (CA-19-9) a partir dos 50 anos.","D":"Rastreio anual para pacientes com Síndrome de Lynch."},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-252241","number":"252241","sourceNumber":"252241","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Na formação dos cálculos biliares, existe a desestabilização de algum dos\ncomponentes da bile. Qual destas substâncias NÃO está envolvida?","options":{"A":"Colesterol.","B":"Sais biliares.","C":"Grelina.","D":"Lecitina."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-252242","number":"252242","sourceNumber":"252242","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Qual tumor descrito por Verner e Morrison em uma síndrome caracterizada por diarreia\nliquida, hipocalemia e tumor em pâncreas?","options":{"A":"Insulinoma","B":"Somatostatinoma","C":"Glucagonoma","D":"Vipoma"},"answer":"D","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-208376","number":"208376","sourceNumber":"208376","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Entre os achados a seguir, qual NÃO é sugestivo de coledocolitíase?","options":{"A":"Hipocolia fecal.","B":"Icterícia.","C":"Prurido.","D":"Vesícula biliar palpável não dolorosa."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-208395","number":"208395","sourceNumber":"208395","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente do sexo feminino, 44 anos, diabética, deu entrada no pronto-socorro com\nquadro de dor intensa, de início súbito, em\ntodo o andar superior do abdome associada à discreta\nicterícia e vômitos. À admissão, observou-se hiperamilasemia de 2.500 g/dl. A paciente evoluiu\ndesfavoravelmente e após 48h da admissão encontra-se taquicárdica, taquipneica, hipotensa,\nhipocorada, oligúrica, queixando piora da dor, distensão abdominal e manutenção dos vômitos,\nsendo encaminhada à UTI. Após 10 dias, a paciente mantém quadro arrastado sem melhora\nsatisfatória, queixando-se de dor em epigástrio. Realizou tomografia computadorizada de abdome\nque revelou necrose de 50% do pâncreas e volumosa coleção peripancreática. Há 24h apresenta\nnova piora de estado geral, com início de febre e leucocitose (20.000 neutrófilos com 8% de\nbastões), além de taquicardia, taquipneia e hipotensão. Assinale a alternativa CORRETA:","options":{"A":"Os elevados níveis da amilasemia já nos permitiram verificar a gravidade do caso, indicando\ntransferência para a UTI desde a admissão.","B":"O próximo passo na conduta desta paciente é a punção da coleção guiada por TC para coleta\nde material e confirmação do processo\ninfeccioso.","C":"Os dados acima nos permitem concluir que a paciente evoluiu com infecção da coleção\nnecrótica, devendo ser submetida a desbridamento cirúrgico urgente.","D":"O tratamento de escolha para esta paciente é a antibioticoterapia de largo espectro, devendo ser\niniciada empiricamente e reavaliada após 72h de acordo com a melhora clínica."},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-208464","number":"208464","sourceNumber":"208464","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente do sexo masculino, 65 anos, diabético, é transferido do interior do Estado,\ncom história de dor tipo cólica em Hipocôndrio\nDireito (HD), irradiada para o dorso, associada a\nvômitos, após alimentação rica em gordura. Esteve internado por 6 dias, sem resposta ao\ntratamento clínico, evoluindo com febre alta e leucocitose. É admitido em Regular Estado Geral,\nanictérico, taquicárdico, pálido +/4 e desidratado, eupneico e normotenso. Palpa-se plastrão em HD\ne a Ultrassonografia revelou cálculos na vesícula, com infiltração de gás na sua parede. Sobre a\navaliação e conduta desta paciente, assinale a alternativa INCORRETA:","options":{"A":"Já havia indicação de abordagem cirúrgica urgente desde o segundo dia de internação sem\nmelhora clínica","B":"Esperamos observar leucocitose, elevação de transaminases e bilirrubinas normais na avaliação\nlaboratorial deste paciente","C":"Caso não seja tratado adequadamente, o caso pode evoluir com perfuração da vesícula e\nperitonite","D":"O paciente está evoluindo com quadro séptico de origem biliar, estando indicada o início de\nantibióticos de largo espectro, transferência para a UTI e reavaliação clínica após 48h"},"answer":"D","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-208431","number":"208431","sourceNumber":"208431","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente do sexo masculino, 55 anos, foi submetido a colectomia direita há 1 ano para\ntratamento de adenocarcinoma de cólon ascendente. Durante seu acompanhamento, o cirurgião\nobservou elevação das titulações de CEA e solicitou ultrassonografia que evidenciou 3 nódulos\nsólidos em segmentos V e VI do fígado. Assinale a alternativa INCORRETA:","options":{"A":"História de alcoolismo, doenças hepáticas e sintomatologia neurológica, assim como a\ninvestigação de ascite, dosagens de bilirrubina, albumina e TAP estão indicados para o caso.","B":"Os dados acima nos permitem concluir que não há curabilidade possível para o caso, restando o\ntratamento cirúrgico paliativo como melhor opção terapêutica.","C":"A tomografia com contraste venoso e a ressonância magnética com estudo dinâmico com\ncontraste hepatobiliar são os exames de imagem\npré-operatórios de escolha para a avaliação da\nressecabilidade das lesões hepáticas.","D":"O paciente deve se beneficiar com a associação de quimioterapia adjuvante após a ressecção\ndas lesões hepáticas."},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-176019","number":"176019","sourceNumber":"176019","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Para definição de prognóstico da pancreatite aguda, utilizamos os critérios de Ranson.\nSão critérios avaliados nas primeiras 24h,\nEXCETO:","options":{"A":"PaO2 > 55 mmHg.","B":"Idade > 55 anos.","C":"Glicose > 200 mg/dl.","D":"DHL > 350 UI/L."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-176052","number":"176052","sourceNumber":"176052","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente do sexo masculino, 38 anos, dá entrada no pronto atendimento com quadro\nde dor intensa em hipocôndrio direito,\nrapidamente progressiva, que migrou para todo o abdome\nsuperior e irradia para o dorso, associada a náuseas e vômitos. Refere crises anteriores de cólicas\nem hipocôndrio direito após alimentação rica em gordura, porém de menor intensidade. Evolução\nde 12 horas. Ao exame físico, encontra-se em REG, lúcido e orientado, com fácies de dor,\nanictérico, taquicárdico, taquipneico, hipotenso e oligúrico. Leucograma = 16.000; amilase = 1.450\nmg/dl. Seu abdome é tenso, bastante doloroso à palpação em andar superior, sem irritação\nperitoneal. Assinale a alternativa INCORRETA:","options":{"A":"Já que a paciente apresenta possível disfunção de órgãos à sua admissão, provavelmente será\nclassificada como quadro moderadamente grave, dependendo da sua resposta à terapia nas\npróximas 48h.","B":"A hidratação com solução salina isotônica é parte importante do tratamento inicial deste paciente\ne o volume total de infusão pode chegar até\na 12 litros em 24 horas.","C":"Já que a ultrassonografia não é método adequado para avaliação do retroperitôneo, há\nindicação de tomografia computadorizada para confirmação diagnóstica e etiológica.","D":"Não é recomendado o uso de antibióticos para este paciente neste momento, reservando-os\npara o caso de evolução desfavorável com\nevidência de necrose retroperitoneal infectada."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-151988","number":"151988","sourceNumber":"151988","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente do sexo feminino, diabética, obesa, 40 anos, deu entrada no pronto socorro\napresentando quadro de dor contínua, de\ninício súbito e rapidamente progressiva, intensa, em\nandar superior do abdome, irradiada para o dorso, associada a náuseas e vômitos, com evolução\nde 12h. Encontrava-se em REG, com fascies de dor, normocorada, anictérica, taquicárdica, algo\ndispneica e normotensa. Seu abdome é tenso, bastante doloroso à palpação em andar superior,\nsem irritação peritoneal. Em seus exames iniciais, apresentou leucograma 14.000, glicemia:\n288mg/dl, amilase: 2.300mg/dl, radiografia de tórax e ultrassom de abdome sem alterações. A\npaciente foi internada e mantida sob tratamento clínico. Após 48h, evoluiu com piora da dor\nabdominal, sinais de choque hipovolêmico, acidose metabólica, aumento das escórias nitrogenadas\ne taquidispneia importante, sendo transferida para a UTI. Após cerca de 10 dias de evolução,\npalpava-se massa de limites imprecisos em epigástrio, dolorosa à palpação. Assinale a alternativa\nCORRETA:","options":{"A":"Os dados acima nos permitem afirmar que a paciente deveria ter sido internada na UTI desde a\nadmissão já que a hiperamilasemia denotava quadro grave.","B":"Investigação de história de consumo de álcool e dosagem dos níveis de triglicerídeos séricos\npoderiam ter sido considerados na investigação etiológica do caso.","C":"Dosagens de fosfatase alcalina, desidrogenase lática e TGO estariam indicados na admissão\ndesta paciente para avaliação de sua potencial\nevolução para quadro grave.","D":"A classificação de Baltazar não pode ser empregada na avaliação desta paciente por tratar-se\nde patologia de evolução grave."},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-151916","number":"151916","sourceNumber":"151916","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente do sexo masculino, 58 anos, vem à consulta queixando-se de quadro de\nicterícia progressiva há cerca de 1 mês,\nassociada à plenitude pós-prandial, principalmente após\ningesta de alimentos sólidos, desconforto abdominal e perda de peso não quantificada. Nega crises\nde dor abdominal aguda. Ao exame físico, apresentava-se emagrecido, desidratado, ictérico +++/4,\nhemodinamicamente estável. Seu abdome é plano, flácido, indolor à palpação, com vesícula biliar\npalpável. Traz consigo exames laboratoriais que evidenciaram leucograma de 5.600; hematócrito\nde 30%; hemoglobina de 10 g/dl; TGO e TGP discretamente elevadas; bilirrubina total de 12 mg/dl;\nbilirrubina conjugada de 10,5 mg/dl; bilirrubina não conjugada de 1,5 mg/dl; e dosagem de CA =\n\n19-9: 225 mg/dl. Sobre o caso acima, assinale a alternativa CORRETA:","options":{"A":"A técnica cirúrgica de escolha depende do diagnóstico histopatológico, estando indicada a\npunção aspirativa por agulha fina guiada por TC.","B":"A TC helicoidal com cortes finos é o exame de imagem de escolha para diagnóstico, porém não\navalia satisfatoriamente o grau de ressecabilidade da lesão.","C":"Caso haja envolvimento importante dos vasos mesentéricos superiores pela lesão, a\nanastomose biliodigestiva é opção de tratamento para o caso.","D":"A ultrassonografia endoscópica é opção adequada para avaliação local da lesão e envolvimento\nde estruturas adjacentes."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-139096","number":"139096","sourceNumber":"139096","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"As diretrizes atuais da American Cancer Society classificam a triagem para a população\nde risco médio de desenvolvimento do câncer\ncolorretal: assintomática, sem histórico familiar de\ncarcinoma colorretal, nenhuma síndrome familiar a partir de:","options":{"A":"35 anos.","B":"40 anos.","C":"50 anos.","D":"60 anos."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-129718","number":"129718","sourceNumber":"129718","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Dentro das etiologias da obstrução mecânica do intestino delgado, qual das abaixo é\nresponsável por até 75% dos casos?","options":{"A":"Aderências intra-abdominais relacionadas à cirurgia abdominal anterior.","B":"Corpos estranhos.","C":"Doença de Crohn.","D":"Tumores."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-129744","number":"129744","sourceNumber":"129744","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"A diverticulite colônica da fase aguda pode complicar com fístulas entre o cólon e os\nórgãos adjacentes. A mais frequente complicação desta natureza é manifestada pelas:","options":{"A":"Fístulas colovaginais.","B":"Fístulas coloentéricas.","C":"Fístulas colocutâneas.","D":"Fístulas colovesicais."},"answer":"D","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-129762","number":"129762","sourceNumber":"129762","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente 65 anos, masculino, evoluiu há 24 horas com dor em quadrante inferior\nesquerdo, afebril e apresenta sensibilidade\nlocal. Nega Diabetes Mellitus, doenças retrovirais e/ou\nuso de imunossupressores. O exame de imagem (Tomografia Computadorizada do abdome e\npelve) revela acúmulo de tecido mole pericólico (borramento da gordura), espessamento da parede\ncolônica sem flegmão. Concluiu tratar-se de diverticulite aguda. Qual a melhor conduta?","options":{"A":"Internação e antibioticoterapia de largo espectro parenterais, dieta de baixos resíduos.","B":"Iniciar ambulatorialmente terapia antibiótica de lardo espectro via oral e dieta de baixos\nresíduos.","C":"Internação, antibioticoterapia de largo espectro parenterais, dieta de baixos resíduos e punção\nguiada por tomografia.","D":"Internação, antibioticoterapia de largo espectro parenterais, dieta de baixos resíduos e\nprogramação cirúrgica com a sigmoidectomia e\nanastomose com anastomose primária colorretal."},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-129771","number":"129771","sourceNumber":"129771","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Os pólipos colorretais são quaisquer projeções da superfície da mucosa intestinal\nmesmo a despeito de sua natureza. São considerados pólipos neoplásicos:","options":{"A":"Juvenil ? Peutz-Jeghers ? Crohkite-Canada.","B":"Pseudopólipos ? pólipo linfoide benigno.","C":"Adenoma tubular ? adenoma viloso ? adenoma tubuloviloso.","D":"Hiperplásicos."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-103801","number":"103801","sourceNumber":"103801","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Distenção colônica sem fator obstrutivo que simula abdomen agudo cirúrgico, que é\ntratada com procinéticos ou mesmo descompressão através de colonoscopia.","options":{"A":"Megacolon Tóxico.","B":"Síndrome de Ogilvie.","C":"Colite Pseudomembranosa.","D":"Íleo Paralítico."},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-107631","number":"107631","sourceNumber":"107631","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente do sexo masculino, 34 anos, procedente do Interior do Estado, apresentando\nquadro de dor tipo cólica difusa no abdome\nque localizou na fossa ilíaca direita há cerca de 5 dias,\nsendo tratado pela infecção urinária com sulfametoxazol e trimetropim oral e sintomáticos pelo\nmédico do Posto de Saúde local. Evoluiu de forma insatisfatória com piora do quadro doloroso,\nqueda do estado geral, distensão abdominal, febre alta e vômitos, sendo transferido para Manaus.\nÀ admissão apresentava-se em regular estado geral, torporoso, pálido ++/4, taquicárdico,\ntaquipneico, anictérico e hipotenso. Refere não urinar há cerca de 12 horas. Seu abdome é\ndistendido, difusamente doloroso à palpação, mais intensamente em fossa ilíaca direita com\nirritação peritoneal difusa. Sobre a abordagem deste paciente, assinale a alternativa INCORRETA:","options":{"A":"Leucocitose expressiva, níveis hidroaéreos difusos e acidose metabólica são alterações\nprováveis na avaliação inicial.","B":"A avaliação da pressão venosa central deste paciente, que deve estar baixa, é parâmetro útil\npara a reposição hídrica e possível indicação de aminas vasoativas.","C":"Devido ao grave choque séptico instalado, há indicação de intervenção cirúrgica imediata no\nmomento da admissão deste paciente.","D":"Há indicação clara de antibioticoterapia de largo espectro com cobertura principalmente para\nbactérias gram-negativas e anaeróbias, porém sem\nindicação para o uso de antifúngicos sistêmicos\nno momento."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-107826","number":"107826","sourceNumber":"107826","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente do sexo masculino, 28 anos, deu entrada no pronto atendimento\napresentando quadro de dor abdominal tipo\ncólica, difusa, progressiva há cerca de 5 dias,\nassociado à parada de eliminação de gases e fezes. Nega febre. Refere náuseas e vômitos\namarelados, de odor fétido. Encontra-se em regular estado geral, taquicárdico, discretamente\nhipotenso, dispneico e desidratado. Refere não urinar há cerca de 8 horas. Seu abdome é bastante\ndistendido, difusamente doloroso à palpação, sem irritação peritoneal. Ruídos hidroaéreos em\nestalido metálico. O toque retal evidenciou massa estenosante há cerca de 10 cm acima do rebordo\nanal. Referente à avaliação e proposta terapêutica deste paciente, assinale a alternativa\nINCORRETA:","options":{"A":"Apesar de não haver irritação peritoneal, podemos afirmar que há indicação de tratamento\ncirúrgico paliativo urgente.","B":"Acidose metabólica, pneumoperitôneo e elevação de escórias nitrogenadas são achados\nesperados na avaliação complementar do caso\nacima.","C":"Os dados acima não nos permitem afirmar se há possibilidade de tratamento curativo definitivo\npara este paciente.","D":"Tanto a colostomia em alça quanto a colostomia terminal são opções para o tratamento cirúrgico\ninicial do paciente acima."},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-107863","number":"107863","sourceNumber":"107863","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente do sexo feminino, 18 anos, deu entrada no pronto atendimento queixando dor\ntipo cólica que iniciou no epigástrio e migrou para a fossa ilíaca direita e hipogástrio há cerca\nde 24\nhoras, associada a astenia e náuseas. Nega febre, vômitos, diarreia, leucorréia e sintomas\nurinários. Última menstruação há 2 semanas. Seu abdome é plano, simétrico, doloroso à palpação\nprofunda em fossa ilíaca direita com sinais de Rovsing e Blumberg positivos, sem plastrão palpável.\nLeucograma: 6.500, hematócrito 38% e hemoglobina 12mg/dl. EAS com 6 hemácias e 8 piócitos\npor campo. Radiografias de tórax e abdome sem alterações. A ultrassonografia evidenciou discreta\nquantidade de líquido livre na fossa ilíaca direita, sem demais alterações. Assinale a alternativa\nCORRETA:","options":{"A":"Já que a ultrassonografia não fechou o diagnóstico do paciente, há indicação de tomografia para\no caso.","B":"Já que não há febre e leucocitose, há indicação de alta hospitalar com prescrição de antibiótico\noral para tratamento de infecção urinária.","C":"Não havia indicação de nenhum dos exames complementares realizados para a indicação de\ntratamento cirúrgico.","D":"Os dados acima nos permitem afirmar que trata-se de apendicite aguda retrocecal em fase\nperfurativa, com indicação de apendicectomia e antibioticoterapia por, no mínimo, 7 dias."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-107870","number":"107870","sourceNumber":"107870","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente do sexo masculino, 58 anos, deu entrada no pronto atendimento queixando\ndor tipo cólica periumbilical que migrou\npara fossa ilíaca esquerda há cerca de 12 horas, associada\na tenesmo. Nega febre, vômitos e sintomas urinários. Refere constipação crônica, chegando a\npassar mais de 7 dias sem defecar. Seu estado geral é bom, normocorado, eupneico, afebril e\nnormotenso. Seu abdome é algo distendido, flácido, doloroso à palpação em fossa ilíaca esquerda\ncom discreta irritação peritoneal. Ruídos hidroaéreos diminuídos. Toque retal sem alterações.\n\nHemograma EAS e radiografias sem alterações. Assinale a alternativa CORRETA:","options":{"A":"Por tratar-se de provável sub-oclusão de cólon distal, o próximo passo da investigação é a\ncolonoscopia.","B":"A tomografia computadorizada é dispensável na decisão da conduta deste paciente.","C":"A conduta inicial deve ser clínica, com internação hospitalar, prescrição de antibióticos com\ncobertura para bactérias gram negativas e\nanaeróbios, avaliação complementar e observação por\n48 horas.","D":"O melhor tratamento cirúrgico para o paciente acima neste momento, caso indicado, seria a\nhemicolectomia esquerda com anastomose colorretal término-terminal."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-103813","number":"103813","sourceNumber":"103813","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"O padrão-ouro na realização de imagens para avaliação de crianças com dor abdominal\ne suspeita de apendicite é:","options":{"A":"Radiografia simples.","B":"Ultrassonografia.","C":"Ressonância magnética.","D":"Tomografia computadorizada."},"answer":"D","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-81997","number":"81997","sourceNumber":"81997","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Mulher, 20 anos, com diarreia líquida há 03 meses, com restos alimentares, quatro\nvezes ao dia, sem outros achados nas fezes.\nHá 01 mês vem apresentando dor na fossa ilíaca\ndireita e parestesia nas mãos. Perdeu 10 kg (atualmente com 65 kg) desde o início do quadro.\nParasitológicos de fezes repetidamente negativos. Sobre o caso, marque a alternativa verdadeira:","options":{"A":"O trânsito e morfologia de delgado é o mais indicado para concluir o diagnóstico, já que ele\navalia todo o jejuno e íleo.","B":"Doença celíaca é o diagnóstico mais provável e a endoscopia digestiva alta com biópsia de\nsegunda porção do duodeno, o padrão-ouro.","C":"Os sintomas devem ser devidos à doença ileal, sendo a colonoscopia o melhor exame para\nconcluir o caso.","D":"Deve ser internada para investigar neoplasia.","E":"Pela ausência de contato anterior com bacilo de Koch, a tuberculose está afastada."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-87390","number":"87390","sourceNumber":"87390","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Analise o seguinte quadro de associações: A - Colangite aguda; B - Coledocolitíase; C -\nVesícula em porcelana; D - Vesícula escleroatrófica; E - Hemobilia. ( ) CPRE; ( ) Múltiplas\ncolecistites recidivadas; ( ) Trauma abdominal; ( ) Diagnóstico no RX de abdome; ( )\nAntibioticoterapia e drenagem urgente de vias biliares. Qual alternativa abaixo contempla a ordem\ncorreta das letras na associação proposta acima?","options":{"A":"B D E C A.","B":"B C A E D.","C":"A D E B C.","D":"E A D B C.","E":"B E A C D."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-87468","number":"87468","sourceNumber":"87468","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Qual das alternativas a seguir é considerada patognomônica de apendicite aguda?","options":{"A":"Nível hidroaéreo em fossa ilíaca direita à radiografia de abdome em ortostase.","B":"Dor em fossa ilíaca direita, sem história de diarreia, associada à leucocitose.","C":"Fecalito em fossa ilíaca direita à radiografia de abdome em decúbito.","D":"Achado de apêndice retrocecal à ultrassonografia.","E":"NDA."},"answer":"D","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-81050","number":"81050","sourceNumber":"81050","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente do sexo feminino, 48 anos, procedente de Autazes, refere quadro de dor\nepigástrica e mesogástrica, tipo\nqueimação, de início súbito e bastante intensa, que migrou para\ntodo o abdome em poucas horas. Refere quadro crônico de epigastralgia em queimação de menor\nintesidade, com evolução de 2 anos, que controlava com chás caseiros. Foi avaliada pelo médico\nlocal que supeitou de apendicite e a encaminhou para atendimento de urgência em Manaus. Ao ser\natendida no Pronto-Socorro João Lúcio, após 10 horas do início do quadro, apresentava-se imóvel\nna maca, com respiração rápida e superficial, referindo bastante dor abdominal. Seu abdome é\nplano, difusamente doloroso à palpação superficial, com descompressão brusca dolorosa nos\nquatro quadrantes. Assinale a alternativa correta:","options":{"A":"A radiografia de tórax fecha o diagnóstico sindrômico e confirma tratamento cirúrgico sem\ndiagnóstico etiológico exato no caso acima.","B":"Por tratar-se de apendicite perfurada, o esquema antibiótico de escolha para o caso é\nCeftriaxona e Metronidazol.","C":"O hemograma e a ultrassonografia de abdome são essenciais para a conduta do caso acima.","D":"A ausência de febre e vômitos sugere tratar-se de abdome agudo inflamatório de tratamento\nclínico.","E":"Por tratar-se de dor intensa de início súbito, o diagnóstico mais provável é a trombose\nmesentérica, estando indicada arteriografia de urgência."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-81057","number":"81057","sourceNumber":"81057","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente de sexo feminino, 25 anos, refere dor abdominal tipo cólica, iniciada em\nmesogástrio, que migrou para fossa ilíaca\ndireita, associada a náuseas e 1 episódio de febre baixa,\nhá 24 horas. Seu abdome é plano, flácido, doloroso à palpação profunda em ponto de McBurney.\n\nSinal de Blumberg positivo. Qual o próximo passo na conduta desta paciente?","options":{"A":"Hemograma, exame de urina e radiografias de abdome.","B":"Ultrassonografia.","C":"Laparoscopia.","D":"Tomografia de abdome.","E":"Internação, antibióticos e observação por 24 horas."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-81065","number":"81065","sourceNumber":"81065","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente do sexo feminino, 62 anos, apresenta quadro de dor abdominal tipo cólica, de\nmoderada intesidade, em fossa ilíaca esquerda, associada a náuseas e febre baixa, há 24 horas.\nRefere constipação crônica e episódios anteriores de menor intensidade. Nega história de\nsangramento à defecação. Seu abdome é plano, flácido, doloroso à palpação profunda em fossa\nilíaca esquerda. Descompressão brusca positiva em fossa ilíaca esquerda. Não há massas ou\nplastrão palpável. Assinale a alternativa correta:","options":{"A":"A colonoscopia é o exame padrão-ouro para diagnosticar o caso acima.","B":"Já que há sinal de irritação peritoneal, a única modalidade de tratamento é cirúrgica.","C":"Já que não há história de hemorragia digestiva baixa, podemos afirmar que a constipação não\nfaz parte da gênese da patologia da paciente acima.","D":"Por tratar-se de quadro meramente inflamatório, não há indicação de antibioticoterapia no caso\nacima.","E":"A tomografia de abdome pode dar o diagnóstico e direcionar a escolha entre tratamento clínico\nou cirúrgico."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-60840","number":"60840","sourceNumber":"60840","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Um homem de 68 anos, com múltiplas cirurgias abdominais apresenta-se com dor\nabdominal em cólica, de moderada intensidade há três dias, náuseas e vômitos. Ao exame físico,\nas mucosas estão secas e ele está taquicárdico (118 bpm): O abdome está distendido, globoso,\nmas sem sinais de irritação peritoneal. Suspeita-se de oclusão intestinal por bridas. Neste caso, o\nexame complementar e a conduta terapêutica mais adequada são, respectivamente:","options":{"A":"USG e antibioticoterapia.","B":"TC de abdome e laparotomia.","C":"Trânsito de delgado e hidratação.","D":"RX simples de abdome e observação.","E":"Rotina de abdome agudo e colocação de SNG."},"answer":"E","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-60845","number":"60845","sourceNumber":"60845","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Em relação à apendicite aguda, é INCORRETO afirmar que:","options":{"A":"Complicações pós-operatórias não são raras","B":"É a causa mais frequente de cirurgia, no escolar","C":"A dor abdominal, inicialmente, é periumbilical","D":"Febre acima de 38 graus, caracteriza o quadro desde o início","E":"Vômitos, ainda que não intensos, são manifestações frequentes"},"answer":"D","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-60850","number":"60850","sourceNumber":"60850","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"A positividade do Sinal de Bassler traduz:","options":{"A":"Apendicite crônica.","B":"Úlcera gástrica perfurada.","C":"Colangite supurativa aguda.","D":"Obstrução do intestino delgado.","E":"Hemorragia intra-abdominal maciça."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-61504","number":"61504","sourceNumber":"61504","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"O gene APC, diretamente envolvido com o aparecimento do câncer do cólon, participa\ndo controle do ciclo celular:","options":{"A":"Inibindo a apoptose.","B":"Estimulando o TGF.","C":"Diminuindo a expressão do Wnt.","D":"Estimulando a produção de receptor de fator de crescimento (erb B2).","E":"Regulando a concentração intracitoplasmática de ß-catenina."},"answer":"E","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-61519","number":"61519","sourceNumber":"61519","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Sobre o câncer colorretal é CORRETO afirmar:","options":{"A":"As síndromes hereditárias incluem a polipose adenomatosa familiar, a síndrome de tumor\ncolorretal hereditário não polipoide e as síndromes com pólipos hamartomatosos (p. ex.:\nPeutz-Jeghers) sendo responsáveis por menos de 5% dos casos de câncer de cólon.","B":"A história familiar é um fator de risco importante, mesmo na forma esporádica. A presença de um\nparente de primeiro grau aumenta em 5 a 10 vezes o risco, particularmente se em idade jovem.","C":"Os pacientes no estádio III, após o tratamento cirúrgico oncológico, não apresentam benefício\ncom o tratamento quimioterápico adjuvante.","D":"A propabilidade de cura nos pacientes com adenocarcinoma de cólon, nos estádios ) e I é de\n50% com a cirurgia.","E":"Não há associação entre o câncer colorretal e a doença inflamatória intestinal."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-61552","number":"61552","sourceNumber":"61552","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente de 20 anos, sexo feminino vai a um pronto atendimento com queixa de dor\nabdominal, que no início era na região epigástrica, depois na região umbilical e agora no quadrante\ninferior direito. Associada à anorexia, náuseas e, vômitos e febre (37ºC). Nega atraso menstrual e\nleucorreia. Ao exame físico: abdome com RHA diminuídos, doloroso à palpação superficial e\nprofunda, espasmo muscular e descompressão brusca dolorosa no quadrante inferior direito. O\nhemograma com leucocitose (15.5000 células/mm³) com desvio para a esquerda, sem outras\nalterações laboratoriais. Diante deste quadro, qual a hipótese diagnóstica principal, conduta\npropedêutica e terapêutica? (VER IMAGEM)","options":{"A":"DIPA, toque vaginal, antibioticoterapia.","B":"Intussuscepção, toque retal e ressecção intestinal.","C":"Diverticulite de Meckel, estudo radiológico e diverticulectomia.","D":"Apendicite aguda, ultrassonografia e apendicectomia.","E":"Doença de Crohn, estudo radiológico contrastado e sulfassalazina."},"answer":"D","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":["question_bank/media/medcurso/medcurso-gastrologia-gas-3/61552.png"],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-60831","number":"60831","sourceNumber":"60831","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"A síndrome de Peutz-Jeghers é caracterizada por:","options":{"A":"Pólipos hamartomatosos do trato intestinal e hiperpigmentação da mucosa bucal, dos lábios e\ndedos.","B":"Pólipos adenomatosos e tumores do sistema nervoso central e osteomas de mandíbula.","C":"Pólipos inflamatórios e tumores do sistema nervoso central.","D":"Pólipos inflamatórios do estômago ao reto.","E":"Pólipos adenomatosos e diarreia."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-46660","number":"46660","sourceNumber":"46660","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"São causas de obstrução intestinal funcional, EXCETO:","options":{"A":"Porfiria","B":"Uremia","C":"Hipotireoidismo","D":"Bezoar","E":"Pancreatite"},"answer":"D","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-49811","number":"49811","sourceNumber":"49811","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Em um paciente com apendicite aguda, a palpação da fossa ilíaca esquerda pode\ncausar dor na fossa ilíaca direita. Este é o\nsinal de:","options":{"A":"Rovsing.","B":"Douglas.","C":"McBurney.","D":"Blumberg.","E":"Lennander."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-46663","number":"46663","sourceNumber":"46663","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Em relação à apendicite aguda, assinale a alternativa CORRETA:","options":{"A":"Vômitos frequentes que se iniciam antes da dor estão presentes na grande maioria dos casos.","B":"Febre alta e calafrios nas primeiras 24 horas estão presentes na grande maioria dos casos.","C":"Anorexia está presente na grande maioria dos casos.","D":"Blumberg (+) no quadrante inferior direito do abdome está ausente na grande maioria dos casos.","E":"O sinal de Lenander presente torna este diagnóstico bastante improvável."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-34126","number":"34126","sourceNumber":"34126","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"O ileobiliar ocorre devido fístula entre:","options":{"A":"Vesícula e Colédoco.","B":"Vesícula e Cólon Ascendente.","C":"Colédoco e Cólon Transverso.","D":"Vesícula e Duodeno.","E":"Colédoco e Cólon Ascendente."},"answer":"D","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-34130","number":"34130","sourceNumber":"34130","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"A anomalia congênita mais encontrada em intestino delgado:","options":{"A":"Tumor carcinoide.","B":"Ileite regional.","C":"Divertículo de Meckel.","D":"Hamartomas.","E":"Pneumatose."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-294469","number":"294469","sourceNumber":"294469","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente, sexo feminino, 34 anos de idade, procura o pronto-socorro com queixa de dor\nem abdome superior há 12 horas. Refere náuseas, vômitos, hiporexia e piora da dor abdominal\napós alimentação. Relata, também, quadros prévios de dor abdominal após libação alimentar. Ao\nexame físico, bom estado geral, corada, temperatura axilar: 38,2°C, FC: 92 bpm, PA: 122 x 78\nmmHg, FR: 18 imp; ausculta cardíaca e respiratória sem alterações; abdome globoso à custa de\npanículo adiposo, flácido e com dor de forte intensidade à palpação de hipocôndrio direito. Diante\ndesse caso clínico, Indique a principal suspeita diagnóstica para o quadro clínico da paciente.","options":{"A":"Pancreatite aguda.","B":"Colecistite aguda.","C":"Hepatite aguda.","D":"Úlcera péptica gástrica."},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-294470","number":"294470","sourceNumber":"294470","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente, sexo feminino, 34 anos de idade, procura o pronto-socorro com queixa de dor\nem abdome superior há 12 horas. Refere náuseas, vômitos, hiporexia e piora da dor abdominal\napós alimentação. Relata, também, quadros prévios de dor abdominal após libação alimentar. Ao\nexame físico, bom estado geral, corada, temperatura axilar: 38,2°C, FC: 92 bpm, PA: 122 x 78\nmmHg, FR: 18 imp; ausculta cardíaca e respiratória sem alterações; abdome globoso à custa de\npanículo adiposo, flácido e com dor de forte intensidade à palpação de hipocôndrio direito. Diante\ndesse caso clínico, Indique o principal achado na ultrassonografia de abdome superior, realizada\npara auxiliar na confirmação do diagnóstico.","options":{"A":"Edema pancreático com presença de líquido peripancreático.","B":"Hepatomegalia com líquido pericapsular.","C":"Cálculo impactado no infundíbulo da vesícula biliar.","D":"Espessamento parietal gástrico e líquido livre perigástrico."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-294471","number":"294471","sourceNumber":"294471","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente, sexo feminino, 34 anos de idade, procura o pronto-socorro com queixa de dor\nem abdome superior há 12 horas. Refere náuseas, vômitos, hiporexia e piora da dor abdominal\napós alimentação. Relata, também, quadros prévios de dor abdominal após libação alimentar. Ao\nexame físico, bom estado geral, corada, temperatura axilar: 38,2°C, FC: 92 bpm, PA: 122 x 78\nmmHg, FR: 18 imp; ausculta cardíaca e respiratória sem alterações; abdome globoso à custa de\npanículo adiposo, flácido e com dor de forte intensidade à palpação de hipocôndrio direito. Diante\ndesse caso clínico, Indique a conduta terapêutica adequada para essa paciente.","options":{"A":"Usar inibidor de bomba de próton e tratar H. pylori, se presente.","B":"Fazer antibiótico e colecistectomia.","C":"Manter observação e tratamento sintomático.","D":"Internar em UTI e prescrever nutrição parental e antibiótico."},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-62884","number":"62884","sourceNumber":"62884","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente, sexo masculino, 63 anos de idade, sem comorbidades maiores, performance\nstatus: 0 (ECOG), teve diagnóstico de\nadenocarcinoma de cólon direito há um ano e meio,\nsubmetido, na ocasião, à colectomia direita e linfadenectomia à D2 I. Tratava-se de uma neoplasia\ngrau II de Broders, Borrmann III, invadia até a serosa e acometia quatro dos 35 linfonodos\ndissecados. Realizou quimioterapia adjuvante com esquema FOLFOX. Na ocasião, os exames de\nimagem mostravam ausência de doença M1. Perdeu o segmento e, em nova consulta, foi solicitado\numa nova tomografia axial computadorizada de abdome, que evidenciou lesão de 16 cm\nenvolvendo os segmentos 5, 6, 7 e 8 e outra, de 3 cm no segmento 3. Submetido à biópsia\npercutânea, guiada por radiologia intervencionista, que mostrou tratar-se de metástase colorretal.\n\nSubmeteu-se a um PET-TC, que não evidenciou doença extra-hepática. A quimioterapia realizada\ninicialmente (esquema FOLFOX) envolveu as drogas:","options":{"A":"5-fluouracil, leucovorin e oxaliplatina.","B":"5-fluouracil, leucovorin e irinotecan.","C":"capecitabina, leucovorin e oxaliplatina.","D":"capecitabina, leucovorin e irinotecan.","E":"capecitabina, leucovorin e fluouracil."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-62827","number":"62827","sourceNumber":"62827","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente, sexo masculino, 63 anos de idade, sem comorbidades maiores, performance\nstatus: 0 (ECOG), teve diagnóstico de\nadenocarcinoma de cólon direito há um ano e meio,\nsubmetido, na ocasião, à colectomia direita e linfadenectomia a D2 I. Tratava-se de uma neoplasia\ngrau II de Broders, Bormann III, invadia até a serosa e acometia quatro dos 35 linfonodos\ndissecados. Realizou quimioterapia adjuvante com esquema FOLFOX. Na ocasião, os exames de\nimagem mostravam ausência de doença M1. Perdeu o segmento e, em nova consulta, foi solicitado\numa nova tomografia axial computadorizada de abdome, que evidenciou lesão de 16 cm\nenvolvendo os segmentos 5, 6, 7 e 8 e outra, de 3 cm no segmento 3. Submetido à biópsia\npercutânea, guiada por radiologia intervencionista, que mostrou tratar-se de metástase colorretal.\n\nSubmeteu-se a um PET-TC, que não evidenciou doença extra-hepática. Em relação a esse caso\nclínico, é correto afirmar:","options":{"A":"O paciente foi incorretamente estadiado quanto ao status nodal.","B":"A neoplasia colônica era indiferenciada.","C":"O tumor intestinal era polipoide.","D":"A artéria cólica média foi ligada junto a sua origem no tronco celíaco.","E":"Trata-se de metástase hepática metacrônica, com melhor prognóstico do que se fosse\nsincrônica."},"answer":"E","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-62832","number":"62832","sourceNumber":"62832","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente, sexo masculino, 63 anos de idade, sem comorbidades maiores, performance\nstatus: 0 (ECOG), teve diagnóstico de\nadenocarcinoma de cólon direito há um ano e meio,\nsubmetido, na ocasião, a colectomia direita e linfadenectomia à D2 I. Tratava-se de uma neoplasia\ngrau II de Broders, Bormann III, invadia até a serosa e acometia quatro dos 35 linfonodos\ndissecados. Realizou quimioterapia adjuvante com esquema FOLFOX. Na ocasião, os exames de\nimagem mostravam ausência de doença M1. Perdeu o segmento e, em nova consulta, foi solicitado\numa nova tomografia axial computadorizada de abdome, que evidenciou lesão de 16 cm\nenvolvendo os segmentos 5, 6, 7 e 8 e outra, de 3 cm no segmento 3. Submetido à biópsia\npercutânea, guiada por radiologia intervencionista, que mostrou tratar-se de metástase colorretal.\n\nSubmeteu-se a um PET-TC, que não evidenciou doença extra-hepática. A melhor estratégia de\ntratamento para a doença atual é:","options":{"A":"trissegmentectomia direita + ressecção do segmento 3.","B":"quimioterapia neoadjuvante.","C":"quimioterapia paliativa.","D":"quimioterapia de conversão.","E":"quimioterapia hepática neoadjuvante."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-62838","number":"62838","sourceNumber":"62838","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente, sexo masculino, 63 anos de idade, sem comorbidades maiores, performance\nstatus: 0 (ECOG), teve diagnóstico de\nadenocarcinoma de cólon direito há um ano e meio,\nsubmetido, na ocasião, a colectomia direita e linfadenectomia à D2 I. Tratava-se de uma neoplasia\ngrau II de Broders, Borrmann III, invadia até a serosa e acometia quatro dos 35 linfonodos\ndissecados. Realizou quimioterapia adjuvante com esquema FOLFOX. Na ocasião, os exames de\nimagem mostravam ausência de doença M1. Perdeu o segmento e, em nova consulta, foi solicitado\numa nova tomografia axial computadorizada de abdome, que evidenciou lesão de 16 cm\nenvolvendo os segmentos 5, 6, 7 e 8 e outra, de 3 cm no segmento 3. Submetido à biópsia\npercutânea, guiada por radiologia intervencionista, que mostrou tratar-se de metástase colorretal.\n\nSubmeteu-se a um PET-TC, que não evidenciou doença extra-hepática. A importância clínica da\nmutação K-RAS (status do gene K-RAS) nas neoplasias colorretais é:","options":{"A":"permitir o uso de droga alvo (cetuximabe).","B":"permitir uso de capecitabina oral.","C":"identificar aumento da chance de metástase óssea.","D":"determinar o aumento de risco da neoplasia entre membros da família.","E":"permitir o uso de quimioterapia oral."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-49435","number":"49435","sourceNumber":"49435","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente, 18 anos de idade, sexo masculino, cursa com dor mesoepigástrica que\nmigrou para fossa ilíaca direita há mais ou menos 12 horas, de forte intensidade, associada a\nnáuseas e a vômitos. Ao exame físico, notavam-se os sinais de Rovsing e Blumberg positivos.\nAfebril. Leucograma: 12300, 2% principal bastões. A principal suspeita diagnóstica é:","options":{"A":"apendicite aguda.","B":"colecistite aguda.","C":"diverticulite aguda.","D":"prostatife.","E":"orquiepididimite."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-49442","number":"49442","sourceNumber":"49442","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente, 18 anos de idade, sexo masculino, cursa com dor mesoepigástrica que\nmigrou para fossa ilíaca direita há mais ou\nmenos 12 horas, de forte intensidade, associada a\nnáuseas e a vômitos. Ao exame físico, notavam-se os sinais de Rovsing e Blumberg positivos.\nAfebril. Leucograma: 12300, 2% principal bastões. São diágnósticos diferenciais plausíveis do caso\nem questão, exceto:","options":{"A":"linfadenite mesentérica.","B":"intussuscepção ileocecal.","C":"diverticulite de Meckel.","D":"doença de Crohn.","E":"laceração de Maillory-Weiss."},"answer":"E","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-343361","number":"343361","sourceNumber":"343361","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Mulher, 49 anos, procura atendimento médico com dor abdominal em cólicas há 9 dias,\nintermitentes, que cessavam com escopolamina. Há 2 dias apresentou piora da dor e icterícia\nassociada à febre alta e vômitos. No momento em regular estado geral, desidratada, taquicárdica,\ntaquipneica, confusa, febril, ictérica. Tem dor intensa à palpação de abdome superior, sem sinais de\nirritação peritoneal. Hemograma com leucocitose importante, amilase normal, com discreto\naumento provas de lesão hepatocelular. Realizou ecografia de abdome que evidenciou: vesícula\nbiliar com parede de 2 mm, com cálculos em seu interior, múltiplos, todos com tamanho menor que\n10 mm e ducto colédoco com 16 mm, sem visualização de sua porção distal, prejudicado por\ninterposição gasosa. Qual o provável diagnóstico e conduta adequada?","options":{"A":"Pancreatite aguda biliar ? Pancreatectomia corpocaudal.","B":"Pancreatite aguda biliar ? Dieta zero, hidratação endovenosa e antibioticoprofilaxia.","C":"Colecistite aguda Tokyo 3 - derivação externa guiada por imagem.","D":"Colangite aguda - drenagem da via biliar e antibioticoterapia."},"answer":"D","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-343364","number":"343364","sourceNumber":"343364","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Jovem, masculino, 32 anos, é internado por episódios de vômitos de início há 24 horas,\nassociado a dor abdominal refratária à analgésicos simples. Nega febre. Nega trauma recente.\n\nNega sintomas urinários. Refere anorexia. Ao exame físico: regular estado geral, desidratado\n\n+++/4, corado, anictérico, afebril, taquicárdico. Ausculta pulmonar normal. Abdome com cicatriz\nprévia de laparotomia mediana por trauma (há\n3 anos), distendido, ruídos abdominais muito\nreduzidos, doloroso em epigástrio e todo andar superior, mas sem sinais de peritonite. Realizou\nradiografia (abaixo) e foi submetido a ultrassonografia que visualizou vesícula biliar com parede de\n3 mm, com cálculos em seu interior, múltiplos, todos com tamanho menor que 5 mm, e ducto\ncolédoco com 4 mm. O pâncreas não foi visualizado por interposição gasosa. A principal hipótese\ndiagnóstica e o tratamento mais adequado é:","options":{"A":"Pancreatite aguda biliar - jejum, analgesia e hidratação, e posteriormente colecistectomia.","B":"Colecistite aguda - colecistectomia.","C":"Colecistite aguda - colangiopancreatografia retrógrada endoscópica.","D":"Bridas - cirurgia de Hartmann."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":["question_bank/media/medcurso/medcurso-gastrologia-gas-3/343364.png"],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-314293","number":"314293","sourceNumber":"314293","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Os cálculos biliares podem ser formados, predominantemente, de colesterol ou\npigmentados. A alternativa que contém fatores de risco relacionados à litíase biliar é","options":{"A":"uso prolongado de corticosteroide, anemia ferropriva e dislipidemia.","B":"obesidade, talassemia, nutrição parenteral prolongada e artrite reumatoide.","C":"dislipidemia, retocolite ulcerativa idiopática e uso analgésicos não esteroides.","D":"anemia falciforme, perda ponderal rápida, sexo feminino e uso contraceptivo oral.","E":"antecedente de cirurgia bariátrica, alimentação rica em gordura e insuficiência renal crônica."},"answer":"D","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-314296","number":"314296","sourceNumber":"314296","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Mulher, 46 anos, apresenta quadro de dor em abdômen superior há cinco dias,\nassociada a coluria, acolia fecal e\nescleras ictéricas. Refere episódios prévios de dor em abdômen\nsuperior, mais localizada em hipocôndrio direito. Ao exame, apresenta dados vitais normais, afebril,\nescleras ictéricas, corada e abdome globoso, flácido. Leve dor à palpação de abdômen superior,\nsem sinais de irritação peritoneal, sem massas palpáveis. Ultrassonografia de abdômen com\nvesicula biliar de paredes finas, contendo cálculos em seu interior, dilatação vias biliares com\ncolédoco de 1,9cm, pâncreas não visualizado por interposição gasosa. Leucograma 8.000/mm3,\nsem desvio. Função renal normal, amilase e lipase normais. Gama GT - 355, fosfatase alcalina 420,\nbilirrubina total 12,0mg/dl, com bilirrubina direta 9,0mg/dl. Considerando esse caso clínico, o\ndiagnóstico é e o tratamento inicial é . A alternativa que\npreenche, correta e sequencialmente, as lacunas do trecho acima é","options":{"A":"Colelitíase / Colecistectomia videolaparoscópica","B":"Colecistite aguda / Colecistectomia videolaparoscópica","C":"Coledocolitíase / Punção e drenagem da vesícula biliar","D":"Coledocolitíase / Colangiopancreatografia retrograda endoscópica (CPRE)","E":"Colangite aguda / Colangiopancreatografia retrograda endoscópica (CPRE)"},"answer":"D","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-281881","number":"281881","sourceNumber":"281881","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Essa condição é causada por erosão de um pseudocisto pancreático na artéria\nesplênica. Manifesta-se por meio de dor abdominal e\nhematoquezia. A angiografia é diagnóstica e\npossibilita a embolização, que frequentemente é terapêutica. Trata-se de:","options":{"A":"Hemaosuccus Pancreaticus.","B":"Hemobilia.","C":"Pancreatite aguda.","D":"Íleo biliar."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-249999","number":"249999","sourceNumber":"249999","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente feminina, obesa, multípara, 46 anos, após alimentação copiosa apresentou\ndor abdominal tipo cólica, há 8 horas, sem\nmelhora com uso de anti-espasmódico. Nega febre.\nProcurou o pronto-socorro onde foi medicada com alívio parcial dos sintomas. Ao exame físico\napresentava-se em bom estado geral, hidratada, corada, anictérica. Sem alterações\ncardiopulmonares. Abdome com ruídos presente, dor a palpação de hipocôndrio direito, com pausa\ninspiratória à palpação profunda desta região. Submeteu-se a ecografia de abdome que evidenciou\nimagem hiperecoica impactada em infundíbulo vesicular, com sombra acústica posterior, de 40 mm,\ncom espessura da parede vesicular de 8 mm. O sinal semiológico relatado no caso acima é descrito\ncomo:","options":{"A":"Sinal de Jobert.","B":"Sinal de Mussy.","C":"Sinal de Murphy.","D":"Sinal de Dumphy."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-181160","number":"181160","sourceNumber":"181160","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Um exame físico bem conduzido é fundamental para o desenvolvimento de um\ndiagnóstico diferencial acurado de abdome agudo. Com relação aos sinais do exame físico\nabdominal, assinale a alternativa com associação INCORRETA:","options":{"A":"Sinal de Rovsing ? Elevação e extensão da perna contra resistência cria dor.","B":"Sinal de Courvoisier ? vesícula biliar palpável na presença de icterícia.","C":"Sinal do Candelabro ? dor extrema abdominal e pélvica inferior com o movimento do colo do\nútero.","D":"Sinal de Aaron ? dor no epigástrio com persistente pressão aplicada no ponto de McBurney."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-139754","number":"139754","sourceNumber":"139754","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Cattel é a abertura da:","options":{"A":"Goteira parietocólica esquerda.","B":"Bolsa omental maior.","C":"Goteira parietocólica direita.","D":"Bolsa omental menor."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-350863","number":"350863","sourceNumber":"350863","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Homem de 30 anos, praticante de exercícios físicos, apresenta dor abdominal súbita e\nintensa em hipocôndrio direito. Realizou tomografia abdominal com contraste que demonstrou lesão\nhepática arredondada circunscrita com realce na fase arterial associada à área heterogênea\nadjacente sugestiva de hematoma contido. A lesão tem cerca de 3 cm, incluindo área líquida\nadjacente, corresponde a 5 cm no total em segmento VI. O paciente está estável há 24 horas, sem\nqueda de hemoglobina e apresenta melhora da dor quando é administrado analgésico. Familiares\ninformam que o paciente faz uso de anabolizantes. Qual a melhor conduta nesse caso?","options":{"A":"Suspender anabolizantes e repetir tomografia após 3 meses.","B":"Biopsia percutânea, com agulha, guiada por ultrassom.","C":"Embolização arterial hepática.","D":"Hepatectomia segmentar."},"answer":"D","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-350861","number":"350861","sourceNumber":"350861","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Uma paciente de 34 anos, sem comorbidades, é admitida na emergência com dor\nimportante em hipocôndrio D. A dor teve\ninício há 4 dias, logo após um churrasco comemorativo. A\npaciente refere ainda náuseas no início dos sintomas e atualmente sente-se febril. A dor é bastante\nforte com rigidez abdominal em região subcostal direita. Foi iniciado tratamento com dieta zero,\nantibióticos, hidratação e analgésicos, porém a paciente não apresentou melhora importante,\ninclusive persistia a febre. A colecistectomia videolaparoscópica foi indicada. Durante a cirurgia,\nobservou-se extenso bloqueio de epiplon sobre a vesícula e desta com a parede abdominal e\nduodeno. O pedículo biliar está comprimido pela vesícula distendida e duodeno, não estando claro\na identificação da artéria hepática, ducto cístico e colédoco. Qual estratégia o cirurgião deve\nadotar\nnesse momento?","options":{"A":"Abortar o procedimento e manter a terapia clínica com antibióticos e dieta zero.","B":"Converter para técnica aberta para realizar dissecção e ligadura do pedículo biliar.","C":"Realizar colecistectomia parcial, retirada dos cálculos e drenagem do leito da vesícula.","D":"Realizar colecistostomia videolaparoscópica com colecistectomia eletiva após 6 semanas."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-350896","number":"350896","sourceNumber":"350896","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Mulher de 35 anos apresenta dor abdominal em andar superior, com irradiação para\ndorso, acompanhada de vômitos incoercíveis, há 2\ndias. Exame físico: PA 120x80mmHg FC 76bpm\nFR 18irpm SpO? 96% em ar ambiente Glasgow 15 ACP: RCR 2T BNF SS / MVU, sem sopros ABD:\ndefesa em região superior do abdome por dor. Sem edema de membros inferiores Exames\nlaboratoriais: Hb 12,5g/dL Leucócitos 8.700/mm³ com diferencial normal Plaquetas 428.000/mm³ ,\nCr 0,7mg/dL, Ureia 20mg/dL, Amilase 500UI/L, Lipase 600UI/L. Qual a conduta nesse caso?","options":{"A":"Indicar cirurgia de urgência.","B":"Iniciar nutrição parenteral precocemente.","C":"Administrar antibioticoterapia endovenosa.","D":"Prescrever hidratação venosa, dieta zero e analgesia."},"answer":"D","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-350878","number":"350878","sourceNumber":"350878","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Adolescente, sexo feminino, 14 anos, obesa, histórico de litíase biliar, é trazida à\nemergência com vômitos e dor abdominal forte que levam à posição com quadris e joelhos\nflexionados. O início foi súbito há 8 horas e a dor é constante. Exame físico: posição antálgica,\ndiscreta distensão abdominal e dor à palpação de todo o andar superior do abdômen. Foram\nrealizados exames laboratoriais. Considerando a hipótese diagnóstica mais provável, qual das\nseguintes alternativas representa o exame laboratorial mais importante para confirmação\ndiagnóstica?","options":{"A":"Lipase.","B":"Hemograma.","C":"Sumário de urina.","D":"Fosfatase alcalina."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-321284","number":"321284","sourceNumber":"321284","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Jovem de 17 anos foi submetido a apendicectomia por videolaparoscopia há 20 dias,\npor apendicite complicada e perfurada. Ele retorna para revisão pós-operatória com queixa de\nindisposição e febre. Nos últimos 3 dias, a febre mensurada foi alta e com calafrios. Ao exame, o\nabdome estava flácido com dor a punho percussão do gradil hepático direito. Segue tomografia\nsolicitada. Qual a melhor conduta para esse caso?","options":{"A":"Drenagem percutânea e antibióticos venosos.","B":"Hepatectomia e sequestrectomia por videolaparoscopia.","C":"Antibiótico e antiparasitário oral, por tempo prolongado.","D":"Punção e coleta de material para pesquisa de células neoplásicas."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-321295","number":"321295","sourceNumber":"321295","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Homem de 43 anos apresenta quadro de adinamia e amarelidão de esclera e pele.\nRefere fezes claras e urina escura há\naproximadamente 10 dias. Qual dos seguintes exames é o\nmais determinante na investigação da origem dessa icterícia?","options":{"A":"Ultrassonografia abdominal.","B":"Tomografia abdominal com contraste.","C":"Colangiografia por ressonância nuclear magnética.","D":"Bilirrubina total, direta e indireta; TGO, TGP e enzimas canaliculares."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-292789","number":"292789","sourceNumber":"292789","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Durante uma consulta, um paciente assintomático, de 32 anos, apresenta um ultrassom\nabdominal revelando um cálculo da vesícula biliar de 3 cm. Qual deve ser a conduta do cirurgião?","options":{"A":"Solicitar tomografia para avaliar vesícula em porcelana ou vegetação intravesicular, e assim,\ndecidir quanto a necessidade de colecistectomia.","B":"Programar a cirurgia, já que esta apresenta poucos riscos, ao contrário do alto risco de\ndesenvolvimento de câncer a que esse paciente está exposto.","C":"Descrever ao paciente os riscos potenciais da colecistectomia, bem como da preservação da\nvesícula com o cálculo, e ouvir a opinião do paciente quanto à conduta cirúrgica.","D":"Sugerir ao paciente que por se tratar de um cálculo assintomático em paciente jovem, ele deve\naguardar apresentar os primeiros sintomas, antes de ser submetido à colecistectomia."},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-292795","number":"292795","sourceNumber":"292795","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Homem de 56 anos portador de hepatopatia crônica devido ao consumo diário de\nbebidas alcoólicas é acompanhado no ambulatório de gastroenterologia por ascite recorrente. O\npaciente apresenta sintomas relacionados a ?má digestão? e em certas ocasiões apresenta dor\nabdominal e vômitos. Ultrassonografia abdominal de rotina revela cálculos na vesícula biliar de\naproximadamente 0,5 a 1 cm e fígado de aspecto cirrótico. O gastroenterologista encaminha o\npaciente para avaliação do cirurgião. Qual deve ser a conduta em relação ao cálculo da vesícula\nbiliar?","options":{"A":"Classificar o paciente para transplante e então indicar a colecistectomia.","B":"Observar o desenvolvimento de uma colecistite, para indicar a cirurgia.","C":"Indicar a colecistectomia aberta, para melhor controle de hemorragia.","D":"Indicar a colecistectomia por videolaparoscopia, para prevenir hérnias."},"answer":"D","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-292806","number":"292806","sourceNumber":"292806","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Uma paciente de 47 anos é investigada por \"desmaios\". Ela refere pouca tolerância ao\njejum e sente necessidade de alimentar-se com frequência de alimentos doces. Na avaliação, foi\ndetectada somente insulina alta e um nódulo no pâncreas de 1 cm, vista a tomografia. Demais\nexames sem alterações. Durante laparotomia, identifica-se um nódulo avermelhado na superfície\npancreática de 1 cm à esquerda dos vasos mesentéricos sem relação com o ducto pancreático\nprincipal. Qual deve ser a estratégia cirúrgica?","options":{"A":"Enucleação do nódulo.","B":"Pancreatectomia central.","C":"Duodenopancreatectomia.","D":"Pancreatectomia corpo-caudal."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-292828","number":"292828","sourceNumber":"292828","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Mulher de 42 anos teve alta hospitalar há 5 semanas, após internamento por\npancreatite aguda grave. Estava bem, clinicamente,\nquando voltou a apresentar dor abdominal,\nnáuseas e vômitos, além de elevação das enzimas pancreáticas. Qual a complicação mais\nprovável, nesse momento?","options":{"A":"Pseudocisto pancreático.","B":"Coleções necróticas agudas.","C":"Trombose de veia esplênica.","D":"Abcessos peripancreáticos agudos."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-259692","number":"259692","sourceNumber":"259692","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente do sexo masculino de 54 anos, acompanhado em ambulatório por hepatopatia\nalcoólica é internado com quadro de dor\nem hipocôndrio direito, há dois dias, febre (38ºC) e sinal de\nMurphy. Exame: orientado e cooperativo, EGB, dor à palpação do HD, FC 100 bpm. Sem\nantecedentes cirúrgicos ou outras comorbidades. Exames: Hb = 10,3 g/dl; leucócitos 16.000/mm³;\nplaquetas 134.000/mm³; INR = 1,3; TGO = 88 U/L; TGP = 46 U/L. Bilirrubinas, fosfatase alcalina e\ngama-GT normais; albumina = 3,1 g/dl. US abdominal: vesícula biliar de paredes espessadas (6\nmm); colelitíase; sinal de Murphy sonográfico e sinais de hepatopatia crônica, além de ascite leve.\n\nQual a conduta mais apropriada?","options":{"A":"Colecistectomia aberta.","B":"Colecistostomia por punção.","C":"Antibioticoterapia e dieta zero.","D":"Colecistectomia laparoscópica."},"answer":"D","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-259697","number":"259697","sourceNumber":"259697","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Uma paciente de 48 anos está internada em UTI há 2 semanas por pancreatite aguda\npós-CPRE. O quadro clínico era estável, nas últimas 48 horas houve diminuição da diurese,\nfrequência cardíaca persistentemente elevada, febre recorrente e hipotensão com necessidade de\ndrogas vasoativas. A mudança terapêutica será estabelecida principalmente baseada em qual dos\nseguintes exames?","options":{"A":"Lactato sérico e gasometria.","B":"Hemograma e proteína C-reativa.","C":"Tomografia abdominal com contraste.","D":"Hemocultura e sensibilidade bacteriana."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-259708","number":"259708","sourceNumber":"259708","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Mulher de 34 anos, 22 semanas de gestação por fertilização in vitro, apresenta dor\nabdominal em hipocôndrio direito de forte intensidade com defesa à palpação há 8 horas. Realiza\nultrassonografia que demonstra vesícula biliar de paredes espessadas contendo imagem com\nsombra acústica impactada no infundíbulo vesicular. Todos estão bastante apreensivos. Qual a\nmelhor conduta nessa situação?","options":{"A":"Indicar colecistectomia convencional sob anestesia peridural.","B":"Indicar colecistectomia videolaparoscópica sob anestesia geral.","C":"Iniciar tratamento clínico para colecistectomia eletiva após o parto.","D":"Iniciar tratamento clínico para colecistectomia eletiva em 6 semanas."},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-259719","number":"259719","sourceNumber":"259719","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Mulher, 39 anos, com dor epigástrica aguda, intensa 9/10, acompanhada de náuseas e\nvômitos e com irradiação para o dorso é avaliado no pronto-atendimento. Ao exame, PA 90 x 60\nmmHg, T: 37oC, FR 22 irpm, pulso 105 bpm, taquipneica, hipoidratada, ansiosa, ictérica +2/4. IMC\n32 kg/m². Ausculta pulmonar: estertores em bases bilaterais. Abdome: rígido e doloroso a palpação,\nruídos hidroaéreos reduzidos, presença de equimoses periumbilicais. Pulsos finos e débeis. Tempo\nde enchimento capilar > 3 segundos. Exames laboratoriais: Hb 15 g/dL Ht 50% 17500\nleucocitos/mm³, Ur 83 mg/dL Cr: 1,5 mg/dL, TGO 55 U/L (VR < 50 U/L), TGP 62 U/L (VR < 68 U/L)\nGlicemia 350 mg/dL gasometria arterial pH 7,25 pCO? 30 mmHg pO? 90 mmHg HCO? 20 mmHg\nAnion Gap 18 mEq/L saturação O? 92%. LEGENDA: PA: pressão arterial; T: temperatura; FR:\nfrequência respiratória; irpm: incursões respiratórias por minuto; bpm: batimentos por minuto; IMC:\níndice de massa corporal; TEC: tempo de enchimento capilar; Hb: hemoglobina; Ht: hematócrito;\nUr: ureia; Cr: creatinina. Qual o diagnóstico mais provável e manejo inicial mais adequado?","options":{"A":"Apendicite aguda; hidratação, laparotomia e antibioticoterapia.","B":"Cetoacidose diabética; hidratação intravenosa e insulinoterapia.","C":"Ruptura de gravidez ectópica; hidratação intravenosa e laparotomia.","D":"Pancreatite aguda; hidratação intravenosa e suspensão da dieta oral."},"answer":"D","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-234005","number":"234005","sourceNumber":"234005","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Anto?nio Carlos, me?dico da atenc?a?o prima?ria, realiza visita domiciliar ao Sr. Jose?\nMaria, de 60 anos, que e? portador de neoplasia de pa?ncreas inopera?vel, em vige?ncia de\nquimioterapia, utilizando metadona 30mg por dia e mantendo EVN 8 de 10. Na u?ltima semana,\nesteve por duas vezes na UPA para controle da dor e das na?useas intensas e passou a ficar todo\no tempo acamado, incapaz e totalmente dependente para todas as atividades. A ingesta de\nalimentos encontra-se reduzida. Esta? alerta, sem conscie?ncia da gravidade de sua situac?a?o,\nem profundo sofrimento psi?quico e espiritual. Tem boa estrutura familiar, rede de apoio e\ncondic?o?es socioecono?micas esta?veis, de baixa vulnerabilidade. LEGENDA: EVN: escala visual\nnume?rica de dor. Qual a proposta mais apropriada para se discutir com o paciente e familiares,\nneste caso?","options":{"A":"Manter o enfoque na cura, mas orientar possibilidade de cuidados paliativos.","B":"Internar para controle dos sintomas, novos exames e reestadiamento da doenc?a.","C":"Reagendar consulta com o oncologista para intensificar esquema de quimioterapia.","D":"Manter em domici?lio com equipe interdisciplinar exclusivamente em cuidado paliativo."},"answer":"D","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-199740","number":"199740","sourceNumber":"199740","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Um paciente acompanhado na APS teve um diagnóstico de icterícia obstrutiva por\ncarcinoma periampular. Ele fez uma biópsia por endoscopia que mostrou um \"adenocarcinoma\nmoderadamente diferenciado do tipo pancreatobiliar\" e retornou ao médico de sua confiança para\nsaber mais sobre esse resultado. O médico resolveu fazer uma busca por literatura relevante e\nencontrou uma meta-análise a respeito, comparando os desfechos de pacientes a partir do tipo\nhistológico desses tumores. No artigo, havia o seguinte quadro. Com base no quadro apresentado,\no que o médico pode comunicar ao paciente?","options":{"A":"O tipo histológico apresentado pelo paciente se correlaciona com pior sobrevida em 5 anos.","B":"O número de estudos e casos é insuficiente para se inferir sobre prognóstico x tipo histológico.","C":"Os tumores do tipo histológico pancreatobiliar têm volumes menores do que os do tipo intestinal.","D":"Os tumores do tipo pancreatobiliar têm características anátomo-patológicas associadas a maior\nagressividade."},"answer":"D","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":["question_bank/media/medcurso/medcurso-gastrologia-gas-3/199740.png"],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-172968","number":"172968","sourceNumber":"172968","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Mulher de 55 anos, sem comorbidades, procura consultório médico com história de que\nfoi submetida a uma colecistectomia videolaparoscópica eletiva por pólipo na vesícula biliar. A\nanálise histopatológica da peça cirúrgica revelou um adenocarcinoma moderadamente diferenciado\nem pólipo adenomatoso da vesícula com a infiltração da lesão restrita à mucosa (pT1). Os exames\nde estadiamento não demonstraram evidências de doença metastática ou locorregional. Qual a\nmelhor recomendação para o caso?","options":{"A":"Quimioterapia adjuvante.","B":"Radioterapia no leito hepático da vesícula.","C":"Acompanhamento clínico com exames periódicos.","D":"Ressecção de leito da vesícula e linfadenectomia regional."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-150845","number":"150845","sourceNumber":"150845","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente de 60 anos, ex-etilista pesado (parou há 10 anos) e portador de hepatopatia\ncrônica. Durante acompanhamento clínico\nperiódico, apresentou elevação do marcador\nalfafetoproteína. Realizou tomografia de abdome que revelou 2 nódulos heterogêneos em lobo\ndireito do fígado medindo 3 cm e 2 cm com captação do contraste na fase arterial. Durante\navaliação da função hepática, foi classificado como Child-Pugh B. Qual a melhor conduta para o\ncaso?","options":{"A":"Hepatectomia direita.","B":"Biópsia da lesão hepática.","C":"Transplante hepático ortotópico.","D":"Ablação das lesões por radiofrequência."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-150802","number":"150802","sourceNumber":"150802","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Mulher de 65 anos apresenta-se com história de dor em andar superior do abdome de 2\nmeses de evolução. Refere que nos últimos 20 dias passou a apresentar icterícia de caráter\nprogressivo. Nega febre. Durante o exame físico, além da icterícia, encontra-se uma vesícula\npalpável e indolor. A TC de abdome trifásica demonstra vesícula biliar distendida, dilatação das\nvias\nbiliares e do ducto de Wirsung com afilamento abrupto. Qual o diagnóstico mais provável?","options":{"A":"Coledocolitíase.","B":"Pancreatite crônica.","C":"Neoplasia do pâncreas.","D":"Neoplasia da vesícula biliar."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-150822","number":"150822","sourceNumber":"150822","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Mulher de 43 anos apresentou quadro de dor em hipocôndrio direito associado à\nicterícia e febre com calafrios, sendo\ninternada para tratamento clínico e antibioticoterapia. Evoluiu\nsem melhora clínica após 48 horas, sendo indicado colangiopancreatografia endoscópica\nretrógrada, após constatação ecográfica de colelitíase e coledocolitíase. O procedimento\nendoscópico não teve sucesso e a paciente estável hemodinamicamente foi submetida a\nprocedimento cirúrgico 24 horas depois. A colangiografia transoperatória foi realizada e está\napresentada a seguir. (VER IMAGEM) Qual das seguintes será a melhor conduta para essa\npaciente?","options":{"A":"Converter para a técnica aberta para a realização de esfincterotomia transduodenal.","B":"Efetuar exploração de vias biliares convencional com coledocojejunostomia em y de Roux.","C":"Irrigação transcística com salina, administração de glucagon para relaxamento do esfíncter de\nOddi.","D":"Concluir a colecistectomia videolaparoscópica e programar nova CPRE em um prazo máximo de\n48 horas."},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":["question_bank/media/medcurso/medcurso-gastrologia-gas-3/150822.png"],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-150848","number":"150848","sourceNumber":"150848","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Mulher, 32 anos, está internada na enfermaria há 12 dias com diagnóstico de\npancreatite aguda. A ultrassonografia\nabdominal mostrou a presença de cálculos na vesícula biliar,\nsem evidência de espessamento de paredes da vesícula e sem dilatação de vias biliares. A\ntomografia de abdome identificou necrose de extensão equivalente a 40% do tecido pancreático e\npresença de uma coleção líquida intrapancreática. Vem evoluindo estável, com leucocitose desde a\nadmissão. Encontra-se afebril, com Escala de Coma de Glasgow 15, sem drogas vasoativas e em\nventilação espontânea. Sobre a prescrição de antibiótico nesse caso, ela deve ser:","options":{"A":"profilática, baseada na extensão da necrose.","B":"empírica, baseada na presença de leucocitose.","C":"terapêutica, baseada na etiologia da pancreatite.","D":"direcionada, baseada na bacterioscopia da punção da necrose."},"answer":"D","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-126954","number":"126954","sourceNumber":"126954","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Menina, 10 meses de idade, bem nutrida, é atendida no setor de emergência por choro\nintenso há 6 horas. Face a episódios de movimento das pernas de encontro ao abdome,\n\npercebe-se padrão de cólicas abdominais, com intensidade progressiva e a intervalos cada vez\nmenores. Mãe relata ainda vômitos há 2\nhoras. Ao exame, criança encontra-se alerta,\npermanecendo calma nos intervalos de dor e não apresenta alterações hemodinâmicas ou indícios\nclínicos de choque séptico. Abdome se encontra distendido, sem sinais de peritonite. No toque\nretal: ampola vazia, com muco e sangue. Ultrassonografia de abdome revela alça intestinal com\nmulticamadas visíveis (aparência de um ?alvo?). Hemograma normal. Considerando a hipótese\ndiagnóstica mais provável para essa criança, a melhor conduta terapêutica, entre as opções abaixo,\né:","options":{"A":"Distorção da lesão isquêmica por acesso videolaparoscópico.","B":"Enema usando contraste baritado ou ar guiado por fluoroscopia.","C":"Ressecção da lesão intestinal e confecção de ostomias por laparotomia exploradora.","D":"Ressecção da lesão intestinal seguida de anastomose primária por acesso videoassistido."},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-126977","number":"126977","sourceNumber":"126977","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Homem de 68 anos, encaminhado da zona rural, com história de dor abdominal de\ninício súbito há 2 dias, com piora importante\nnas últimas 6 horas e o aparecimento de náuseas e\nvômitos. Exame físico: consciente, orientado, hipotenso, desidratado, taquicárdico com ritmo\nirregular, taquipneico, abdome bastante distendido porém flácido, apesar de referir dor intensa à\npalpação profunda, RHA ausente. Toque retal: ausência de fezes na ampola com raios de sangue\nna luva. Exames laboratoriais: leucócitos = 18.000/mm³; amilase = 300 UI; lipase = 100 UI; lactato =\n5 mmol/L; pH = 7,1. Qual o diagnóstico mais provável e sua conduta?","options":{"A":"Pancreatite aguda, solicitar TC de abdome para confirmar o diagnóstico e avaliar as\ncomplicações.","B":"Isquemia mesentérica, encaminhar para o centro cirúrgico para cirurgia de emergência devido à\ngravidade do quadro.","C":"Pancreatite aguda, estabilizar o paciente corrigindo a acidose e encaminhá-lo para o centro\ncirúrgico para cirurgia de urgência.","D":"Isquemia mesentérica, estabilizar o paciente corrigindo a acidose e encaminhá-lo para o centro\ncirúrgico para cirurgia de urgência."},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-126991","number":"126991","sourceNumber":"126991","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Em consulta de triagem para encaminhar os pacientes para o médico especialista, você\natende um senhor de 70 anos, com icterícia progressiva há 3 meses, sem outras queixas. Ele não\nrealizou nenhum exame complementar. Na triagem, você só pode pedir um exame. Qual exame\nvocê pediria, pensando em qual diagnóstico mais provável, e para quem o encaminharia?","options":{"A":"Enzimas hepáticas, hepatite colestática ? encaminhar para o hepatologista.","B":"Ultrassom abdominal, icterícia obstrutiva por coledocolitíase ? encaminhar para CPRE.","C":"Ultrassom abdominal, icterícia obstrutiva por neoplasia ? encaminhar para o cirurgião.","D":"Bilirrubina total e frações, icterícia obstrutiva por neoplasia ? encaminhar para o cirurgião."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-127004","number":"127004","sourceNumber":"127004","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente com 47 anos, masculino, foi diagnosticado clinicamente com diverticulite\naguda em uma emergência, há 10 dias, e\niniciou tratamento com restrição alimentar e antibióticos\norais, ambulatorialmente. Há uma semana, teve piora do quadro, apresentando 2 picos febris de\n38,7°C e intensificação da dor em fossa ilíaca esquerda, sendo hospitalizado e iniciada\nantibioticoterapia parenteral. Na admissão, fez Tomografia Computadorizada (TC) do abdome que\nevidenciou abscesso perimesocólico com 5 cm, na topografia do sigmoide, sem líquido livre na\ncavidade ou evidências de pneumoperitônio. Hoje é mantido em internação hospitalar, com 1 pico\nfebril diário, dificuldade de realimentação oral e dor profunda em FIE sem sinais de aumento da dor\nà descompressão brusca. Na TC de controle, há persistência de abscesso com diâmetro de 4 cm.\nCom base nas informações acima, qual das alternativas abaixo representa a conduta mais indicada\nno caso?","options":{"A":"Indicar drenagem laparoscópica do abscesso.","B":"Indicar drenagem percutânea guiada por TC.","C":"Manter a conduta atual e repetir a TC com 14 dias.","D":"Manter a conduta clínica e trocar o esquema antibiótico."},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-126945","number":"126945","sourceNumber":"126945","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Mulher de 75 anos tem diagnóstico de adenocarcinoma de cólon (intestino grosso) com\nmetástase peritoneal e deverá submeter-se à quimioterapia. O serviço de oncologia considera a\npossibilidade de administrar, de forma associada, bevacizumabe, uma droga que age sobre o Fator\nde Crescimento Endotelial Vascular (VEGF). Qual o principal mecanismo de ação dessa\ndroga sobre a biologia celular do câncer dessa paciente?","options":{"A":"Aumento da permeabilidade vascular tumoral de modo seletivo aos quimioterápicos.","B":"\"Normalização\" dos vasos tumorais com aumento da ação dos quimioterápicos.","C":"Lesão direta da membrana basal dos vasos tumorais com apoptose tumoral.","D":"Efeito antitumoral direto em sinergismo com os quimioterápicos."},"answer":"D","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-102143","number":"102143","sourceNumber":"102143","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente masculino, 35 anos, assintomático, foi orientado por proctologista a\nsubmeter-se a uma videocolonoscopia, visto\nque sua mãe e irmão mais velho haviam falecido de\n\ncâncer de cólon. A mãe faleceu com 48 anos de idade e o irmão aos 33 anos. À videocolonoscopia\nrevelaram-se duas lesões ulceradas, ambas no\ncólon ascendente. A maior, com aproximadamente\n3 cm de diâmetro, e a menor com 1,5 cm. Foram feitas biópsias de ambas as lesões com\nhistopatológico demonstrando adenocarcinoma moderadamente diferenciado. Realizou\nestadiamento com tomografia abdominal, pélvica e de tórax sem anormalidades. O antígeno\ncarcinoembriogênico foi de 2,5 µg/L. Diante do achado, assinale a síndrome genética na qual o\npaciente se enquadra e o tratamento mais adequado:","options":{"A":"Lynch I e proctocolectomia com ileostomia definitiva.","B":"Lynch II e colectomia subtotal com ileorreto anastomose.","C":"Lynch I e colectomia subtotal com ileotransverso anastomose.","D":"Síndrome de Muir (associada a mutações dos genes MLH1 e MSH2) e proctocolectomia com\nbolsa ileal."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-102174","number":"102174","sourceNumber":"102174","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente de 50 anos, sexo feminino, procura atendimento de urgência por dor\nabdominal. Refere que estava assintomática até\n12 horas antes, quando passou a apresentar\ndesconforto leve em quadrante abdominal superior direito, que progrediu, ao longo de 4 horas, para\ndor de grande intensidade. Refere alguns episódios de vômitos nesse período. Ao exame físico,\napresentava temperatura de 38ºC, pressão arterial de 130 x 90 mmHg; anictérica; ausculta\ncardiopulmonar normal; abdome flácido, dolorido e com parada de movimentos respiratórios à\npalpação profunda de hipocôndrio direito. Qual dos exames abaixo representa a condição clínica\napresentada pela paciente?","options":{"A":"(VER IMAGEM).","B":"(VER IMAGEM).","C":"(VER IMAGEM).","D":"(VER IMAGEM)."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":["question_bank/media/medcurso/medcurso-gastrologia-gas-3/102174.png"],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-102118","number":"102118","sourceNumber":"102118","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente do sexo masculino, 50 anos, hígido, PA = 120x75 mmHg, sem fatores de risco\ncardiovascular na história clínica, vem à Unidade de Saúde pedindo para realizar um checkup. Que\nexames laboratoriais o médico de família deverá solicitar, para rastreamento, no paciente em\nquestão?","options":{"A":"PSA Total e Pesquisa de sangue oculto nas fezes.","B":"Glicemia de jejum, PSA Total e Pesquisa de sangue oculto nas fezes.","C":"Dosagem de lipídios séricos e Pesquisa de sangue oculto nas fezes.","D":"Dosagem de lipídios séricos, PSA total e Pesquisa de sangue oculto nas fezes."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-65752","number":"65752","sourceNumber":"65752","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente de 80 anos, com queixa de dor epigástrica há 6 meses, há cerca de 3 dias\ncomeçou a apresentar vômitos, inicialmente pós-prandiais e atualmente com conteúdo claro, não\nbilioso em vários episódios e sem melhora com tratamento medicamentoso. O exame de raio X de\nabdome apresenta imensa distensão gástrica com pobreza de imagens de gases no restante da\ncavidade abdominal. Considerando os distúrbios hidroeletrolíticos e acidobásicos mais frequentes\nnessa situação, qual das seguintes propostas de reposição hidroeletrolítica é mais aplicável?","options":{"A":"Ringer Simples seguida de NaCl 19,1%.","B":"Ringer Lactato seguido de salina isotônica.","C":"Salina hipotônica seguida de Ringer Lactato.","D":"Salina isotônica seguida de solução com KCl.","E":"Salina hipertônica seguida de Ringer Lactato."},"answer":"D","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-65756","number":"65756","sourceNumber":"65756","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Homem de 50 anos apresenta hematoquezia há 3 meses. Ao exame: anêmico ++/4+,\ntoque retal mostra uma lesão ulcerada de\nbordos elevadas a cerca de 0,5 cm do esfíncter anal, fixa,\nenvolvendo 60% da circunferência da luz retal, com 4 cm de extensão. Qual a melhor opção\nterapêutica para esta afecção?","options":{"A":"Amputação abdominoperineal.","B":"Excisão local para estadiamento.","C":"Radioquimioterapia neoadjuvante.","D":"Microcirurgia endoscópica transanal.","E":"Ressecção anterior do reto com anastomose coloanal."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-65761","number":"65761","sourceNumber":"65761","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Homem de 55 anos, portador de fibrilação atrial crônica em uso de varfarina (suspenso\nhá 30 dias), relata dor abdominal intensa,\ndistensão e náuseas, iniciadas há 24 horas. Ao exame:\nfáscies de dor, abdome bastante distendido, doloroso difusamente, sem defesa peritoneal, RHA (-).\nFC: pulso irregular, hipotenso. Exames: leucograma: 35.000 leuc./mm³ com desvio para\nmetamielócitos e ausência de eosinófilos na contagem. Granulações tóxicas estavam presentes em\n30% dos neutrófilos; acidose metabólica à gasometria. Qual a melhor conduta?","options":{"A":"Solicitação de parecer do cirurgião vascular.","B":"Encaminhamento para laparotomia exploradora.","C":"Monitorização e tratamento da arritmia cardíaca em UTI.","D":"Estabilização hemodinâmica e administração de antibióticos de largo espectro.","E":"Dosagem de enzimas pancreáticas, dieta zero, sondagem nasogástrica e nutrição parenteral\ntotal."},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-51140","number":"51140","sourceNumber":"51140","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"O câncer colorretal é uma doença cujo rastreamento (?screening?) é justificável\nconsiderando tratar-se de doença grave,\nrelativamente comum, de crescimento lento e, em geral,\nse origina de lesões pré-neoplásicas. Em qual das opções abaixo a indicação de colonoscopia para\nrastreamento (\"screening\") de câncer colorretal é indicada?","options":{"A":"Paciente de 55 anos com anemia sem causa aparente.","B":"Paciente de 60 anos com lesão tumoral palpável ao toque retal.","C":"Paciente de 40 anos com 2 parentes em primeiro grau com câncer colorretal.","D":"Paciente de 65 anos com alteração de hábito intestinal e fezes mucossanguinolentas."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-51193","number":"51193","sourceNumber":"51193","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Uma família apresenta uma alta prevalência de câncer. Deseja-se estudar o perfil\ngenético de seus membros para 30 mil genes e\nverificar uma possível maior frequência de múltiplas\nmutações. Qual o método genético mais eficiente para realizar este estudo?","options":{"A":"Reação de polimerase em cadeia.","B":"Hibridização in situ.","C":"\"Microarray\".","D":"Western blot."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-51198","number":"51198","sourceNumber":"51198","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Um paciente submeteu-se à colonoscopia para screening de câncer cujo achado foi de\num único pólipo pediculado. O laudo\nhistopatológico evidenciou adenoma tubular com margens\nlivres, apresentando foco de adenocarcinoma confinado à submucosa, sem invasão linfática ou\nvascular. No presente caso, qual a conduta recomendada?","options":{"A":"Vigilância.","B":"Colectomia.","C":"Radioterapia.","D":"Quimioterapia."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-141619","number":"141619","sourceNumber":"141619","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Com relação ao quadro clínico de obstrução intestinal aguda, é correto afirmar:","options":{"A":"Faixas de aderência ou hérnias internas secundárias a uma operação abdominal realizada no\npassado e hérnias externas respondem por\ncerca de 75% dos casos.","B":"A incidência de obstrução intestinal pós-operatória é maior nos pacientes submetidos a\noperações laparoscópicas do que nos procedimentos abertos.","C":"A obstrução intestinal mecânica caracteriza-se por dor em pontadas na região média do\nabdome, que tende a ser menos grave quanto mais alta for a obstrução.","D":"Leucograma normal exclui a presença de estrangulamento."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-141589","number":"141589","sourceNumber":"141589","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Com relação a Apendicite Aguda, é correto afirmar:","options":{"A":"Trata-se da emergência cirúrgica abdominal mais comum, afetando principalmente\nindivíduos na segunda e terceira décadas de\nvida, sendo no entanto bastante comum em\nidosos, entre os quais tem menor mortalidade do que na população geral","B":"Quando o processo evolui rapidamente, os órgãos adjacentes como íleo terminal, ceco e\nomento podem bloquear a área apendicular, formando um abscesso localizado, enquanto a\nprogressão lenta da deterioração vascular, pode causar perfuração com acesso livre à cavidade\nperitoneal.","C":"A sequência clássica de sintomas com dor inicialmente periumbilical, que posteriormente\nmigra para o quadrante inferior direito do\nabdômen associados a anorexia, é encontrada em\nmenos da metade dos pacientes.","D":"Tratamento conservador com uso apenas de antibióticos em casos em que não há perfuração\nleva a resolução do quadro em menos de 50% dos\ncasos, associado a altas taxas de recidivas."},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-45396","number":"45396","sourceNumber":"45396","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Pacientes com quadro clínico característico de obstrução intestinal alta podem\napresentar:","options":{"A":"alcalose metabólica hiperclorêmica e hipocalêmica.","B":"acidose metabólica hipoclorêmica e hipocalêmica.","C":"acidose metabólica hiperclorêmica e hipocalêmica.","D":"alcalose metabólica hipoclorêmica e hipocalêmica.","E":"alcalose metabólica hipoclorêmica e hipercalêmica."},"answer":"D","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-37375","number":"37375","sourceNumber":"37375","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"FCD, 54 anos, masculino foi admitido na emergência com quadro de dor abdominal de\ninício gradual e de padrão inespecífico nas regiões mesogástrica e fossa ilíaca esquerda há cerca\nde 24 horas com piora da intensidade nas últimas 6 horas. Achados de exame físico: Temp =\n37,7°C, FC = 108 bpm e com descompressão brusca positiva na fossa ilíaca esquerda. Com\nrelação à investigação complementar desse paciente, qual dos seguintes exames está mais\nindicado para elucidação diagnóstica desse paciente?","options":{"A":"Enema opaco.","B":"Colonoscopia.","C":"Retossigmoidoscopia flexível.","D":"Retossigmoidoscopia rígida.","E":"Tomografia computadorizada do abdome."},"answer":"E","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-37379","number":"37379","sourceNumber":"37379","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"F.A.C., masculino, 64 anos, se apresenta a uma consulta médica na atenção primária à\nsaúde com história de alteração de hábito\nintestinal há 8 meses, presença de sangue e muco nas\nfezes e tenesmo retal. O exame físico mostra que o paciente é eutrófico, sem aparente palidez\ncutaneomucosa e sem massas palpáveis ao exame abdominal e ao toque retal. Com relação ao\ncaso descrito acima, qual a melhor conduta a ser seguida?","options":{"A":"Solicitar exames de rotina incluindo hemograma e sangue oculto nas fezes. Se alterações,\nprosseguir a investigação no retorno em dois meses.","B":"Preencher ficha APAC (Autorização de Procedimentos de Alto Custo) e solicitar tomografia\ncomputadorizada.","C":"Solicitar enema opaco com duplo contraste.","D":"Solicitar exame de endoscopia digestiva baixa.","E":"Solicitar dosagem de CEA (Antígeno Carcinoembrionário) para diagnóstico."},"answer":"D","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-37416","number":"37416","sourceNumber":"37416","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Adolescente de 16 anos, sexo feminino, com queixa de dor abdominal periumbilical que\nlocaliza-se na fossa ilíaca direita. Apresenta sensibilidade à palpação no mesmo local, febre e\nvômitos, há 12 horas. Informou que tem vida\n\nsexual ativa há dois anos, não fazendo uso de métodos anticoncepcionais. O leucograma\napresentava leucocitose. O diagnóstico mais provável é:","options":{"A":"Apendicite aguda.","B":"Gravidez ectópica.","C":"Proctite.","D":"Doença inflamatória pélvica.","E":"Nenhuma das alternativas anteriores."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-365561","number":"365561","sourceNumber":"365561","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Um paciente de 68 anos de idade, portador de HAS e diabetes mellitus (DM)\ninsulinodependente de difícil controle,\nprocurou uma unidade de pronto atendimento com queixa de\ndor de forte intensidade no hipocôndrio direito há 48 horas. Associa-se ao quadro náusea e um\nepisódio de vômito, além de febre (38°C). Fez uso de analgésicos, com pouca melhora dos\nsintomas. Como medidas iniciais, realizou exames laboratoriais e tomografia computadorizada de\nabdome. Acerca desse caso clínico, com base nas imagens apresentadas, a principal hipótese\ndiagnóstica é","options":{"A":"colecistite aguda.","B":"abscesso hepático.","C":"colecistite enfisematosa.","D":"coledocolitíase."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":["question_bank/media/medcurso/medcurso-gastrologia-gas-3/365561.png"],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-365632","number":"365632","sourceNumber":"365632","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Um paciente de 68 anos de idade, portador de HAS e diabetes mellitus (DM)\ninsulinodependente de difícil controle,\nprocurou uma unidade de pronto atendimento com queixa de\ndor de forte intensidade no hipocôndrio direito há 48 horas. Associa-se ao quadro náusea e um\nepisódio de vômito, além de febre (38°C). Fez uso de analgésicos, com pouca melhora dos\nsintomas. Como medidas iniciais, realizou exames laboratoriais e tomografia computadorizada de\nabdome. No que tange ao caso clínico apresentado, qual o principal organismo envolvido no\ndesenvolvimento dessa patologia?","options":{"A":"Escherichia coli","B":"Proteus mirabilis","C":"Klebsiella pneumoniae","D":"Clostridium welchii"},"answer":"D","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":["question_bank/media/medcurso/medcurso-gastrologia-gas-3/365632.png"],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-365627","number":"365627","sourceNumber":"365627","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Uma paciente de 45 anos de idade procurou o pronto-socorro com queixa de cólicas\nabdominais localizadas principalmente no hipocôndrio direito, há oito dias, acompanhada de\nhiporexia e perda de 1 kg nesse período. Referiu, ainda, fezes mais claras, coloração escura da\nurina e olhos amarelados. Nega febre. Relatou que tem antecedentes de colecistectomia por\nvideolaparoscopia há sete meses. Ao exame físico, encontra-se corada, ictérica 2+/4+ com abdome\ngloboso e dor à palpação do hipocôndrio direito, com sinal de Murphy negativo. A hipótese\ndiagnóstica e a conduta são, respectivamente,","options":{"A":"cálculo primário do colédoco e tratamento clínico com prescrição de ácido ursodesoxicólico.","B":"cálculo residual do colédoco e CPRE para retirada do cálculo.","C":"câncer de papila, bem como CPRE e cirurgia de derivação pancreatojejunal.","D":"câncer de vesícula não diagnosticado no anatomopatológico e realização de hepatectomia."},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-365623","number":"365623","sourceNumber":"365623","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Uma paciente de 45 anos de idade apresentou dor abdominal recorrente no quadrante\nsuperior direito e foi diagnosticada com\ncolelitíase após a realização de ultrassonografia abdominal,\nque identificou múltiplos cálculos na vesícula biliar. Durante a avaliação pré-operatória, os sinais\nvitais mostraram-se estáveis, com PA = 130 mmHg x 85 mmHg, FC = 75 bpm, FR = 18 irpm,\ntemperatura = 37º C e SatO2 = 98% em a.a. Ao exame físico, não se verificaram alterações\nsignificativas além de dor à palpação no quadrante superior direito. Acerca desse caso clínico,\nquanto à abordagem mais apropriada para essa paciente, assinale a alternativa correta.","options":{"A":"Adotar uma abordagem conservadora, monitorando a paciente para possíveis complicações.","B":"Instituir antibioticoterapia pré-operatória.","C":"Realizar colangiopancreatografia retrógrada endoscópica (CPRE) antes da cirurgia.","D":"Realizar colecistectomia eletiva."},"answer":"D","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-365618","number":"365618","sourceNumber":"365618","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Um paciente de 58 anos de idade deu entrada no pronto-socorro com queixa de dor\nabdominal intensa, localizada no quadrante superior direito, com irradiação para o dorso. O\npaciente relatou o início súbito da dor há aproximadamente 12 horas, associada a náuseas e\nvômitos frequentes. O histórico médico do paciente revela recente colelitíase diagnosticada. Na\nadmissão, os sinais vitais apresentam PA = 130 mmHg x 80 mmHg, FC = 110 bpm, FR = 18 irpm,\ntemperatura = 38,5 °C. Ao exame físico, observaram-se abdome com sensibilidade à palpação\nprofunda no quadrante superior direito, sinal de Murphy positivo. Realizou exames laboratoriais com\nresultado de amilase sérica e lipase elevadas. Os exames de imagem demonstraram, na\nultrassonografia abdominal, evidência de colelitíase e dilatação da via biliar comum. Na tomografia\ncomputadorizada abdominal, houve a confirmação de pancreatite aguda biliar. Com base nesse\ncaso clínico, assinale a alternativa que indica o próximo passo no manejo desse paciente com\npancreatite aguda biliar confirmada.","options":{"A":"Administração de antibióticos de amplo espectro.","B":"Colangiopancreatografia retrógrada endoscópica (CPRE)","C":"Início imediato de dieta enteral.","D":"Cirurgia de colecistectomia laparoscópica emergencial."},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-349728","number":"349728","sourceNumber":"349728","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Um paciente com obstrução e infecção das vias biliares apresenta a chamada tríade de\nCharcot, a qual é caracterizada por:","options":{"A":"icterícia, hipotensão e confusão mental.","B":"dor em hipocôndrio direito, icterícia e hipotensão.","C":"febre, hipotensão e icterícia.","D":"icterícia, dor em hipocôndrio direito e febre.","E":"febre, icterícia e confusão mental."},"answer":"D","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-349751","number":"349751","sourceNumber":"349751","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Um paciente de 45 anos teve uma pancreatite aguda e, após 6 semanas, passou a\nnotar dor abdominal persistente, saciedade\nprecoce, náusea e perda de peso. Ao procurar o\nserviço médico, foram verificados níveis elevados das enzimas pancreáticas e uma lesão cística de\naproximadamente 8 cm em cauda do pâncreas, em contato com a parede gástrica. Qual é o\nprovável diagnóstico e a conduta mais adequada nesse caso?","options":{"A":"Trata-se provavelmente de necrose pancreática que deve ser tratada com antibióticos de amplo\nespectro como o meropenem.","B":"Trata-se provavelmente de um pseudocisto pancreático que deve ser tratado com antibióticos de\namplo espectro como o meropenem.","C":"Trata-se provavelmente de pseudocisto pancreático e pode-se tentar uma drenagem\nendoscópica transgástrica.","D":"Trata-se provavelmente de necrose pancreática que deve ser tratada de maneira expectante,\ncom indicação de intervenção cirúrgica se o paciente\napresentar febre.","E":"Trata-se provavelmente de pseudocisto pancreático que deve ser tratado com abordagem\ncirúrgica por laparotomia."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-322136","number":"322136","sourceNumber":"322136","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Assinale a alternativa que NÃO corresponde a uma indicação usual de intervenção por\nCPRE (Colangiopancreatografia Retrógrada Endoscópica).","options":{"A":"Coledocolitíase.","B":"Colangite.","C":"Estenose de colédoco distal e dilatação proximal.","D":"Pancreatite biliar com cálculo impactado na via biliar.","E":"Colelitíase."},"answer":"E","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-322140","number":"322140","sourceNumber":"322140","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Durante uma cirurgia de abordagem para ressecção da cabeça do pâncreas, qual das\nestruturas vasculares a seguir está presente nessa região e é de suma importância para o paciente,\ndevendo-se, por isso, realizar o máximo de esforço para que seja preservada?","options":{"A":"Artéria mesentérica inferior.","B":"Artéria gastroduodenal.","C":"Artéria pancreatoduodenal posterior.","D":"Artéria mesentérica superior.","E":"Artéria pancreatoduodenal superior."},"answer":"D","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-305277","number":"305277","sourceNumber":"305277","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Um paciente com sintomas de sudorese, agitação, confusão mental, com níveis baixos\nde glicose e alívio após administração de\nglicose foi diagnosticado com um tumor gastrointestinal e\ntem indicação de tratamento cirúrgico. Quais são, respectivamente, o nome desse conjunto de\nsinais de sintomas e o do provável tumor desse paciente?","options":{"A":"Tríade de Charcot / Gastrinoma.","B":"Síndrome de Verner-Morrison / VIPoma.","C":"Síndrome de Verner-Morrison / Glucagonoma.","D":"Tríade de Virchow / GIST.","E":"Tríade de Whipple / Insulinoma."},"answer":"E","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-274355","number":"274355","sourceNumber":"274355","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"A condição que se apresenta como massa heterogênea hepática, benigna, mais\ncomum em mulheres e que tem\ncaracteristicamente um aumento da incidência com o uso crônico\nde contraceptivo oral denomina-se:","options":{"A":"Linfangioma hepático.","B":"Adenocarcinoma hepático.","C":"Hemangioma hepático.","D":"Adenoma hepático.","E":"Abscesso hepático."},"answer":"D","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-265562","number":"265562","sourceNumber":"265562","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Um paciente de 65 anos de idade, PS1, com histórico de perda de peso, anemia e\nemagrecimento, associados a alterações recentes do hábito intestinal, foi submetido a uma\ncolonoscopia, sendo diagnosticada uma tumoração no sigmoide de 3 cm, a cerca de 30 cm da\nmargem anal, com diagnóstico anatomopatológico compatível com adenocarcinoma de cólon\nmoderadamente diferenciado. O estadiamento clínico inicial não apresentou evidências de\nmetástases a distância. Acerca desse caso clínico e com base nos conhecimentos médicos\ncorrelatos, julgue o item a seguir. Os principais fatores de risco para o desenvolvimento do câncer\ncolorretal são idade superior a 50 anos, obesidade, dieta pobre em fibras alimentares, doença\ninflamatória intestinal e histórico familiar de neoplasia de cólon.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-265564","number":"265564","sourceNumber":"265564","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Um paciente de 65 anos de idade, PS1, com histórico de perda de peso, anemia e\nemagrecimento, associados a alterações recentes do hábito intestinal, foi submetido a uma\ncolonoscopia, sendo diagnosticada uma tumoração no sigmoide de 3 cm, a cerca de 30 cm da\nmargem anal, com diagnóstico anatomopatológico compatível com adenocarcinoma de cólon\nmoderadamente diferenciado. O estadiamento clínico inicial não apresentou evidências de\nmetástases a distância. Acerca desse caso clínico e com base nos conhecimentos médicos\ncorrelatos, julgue o item a seguir. A cirurgia para esse paciente deve ser uma retossigmoidectomia\ncom linfadenectomia regional, com ligadura dos vasos na origem e anastomose primária.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-265565","number":"265565","sourceNumber":"265565","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Um paciente de 65 anos de idade, PS1, com histórico de perda de peso, anemia e\nemagrecimento, associados a alterações recentes do hábito intestinal, foi submetido a uma\ncolonoscopia, sendo diagnosticada uma tumoração no sigmoide de 3 cm, a cerca de 30 cm da\nmargem anal, com diagnóstico anatomopatológico compatível com adenocarcinoma de cólon\nmoderadamente diferenciado. O estadiamento clínico inicial não apresentou evidências de\nmetástases a distância. Acerca desse caso clínico e com base nos conhecimentos médicos\ncorrelatos, julgue o item a seguir. Se, durante o seguimento ambulatorial desse paciente, ele vier a\napresentar metástases hepáticas passíveis de tratamento cirúrgico, ele deve ser encaminhado para\na ressecção, pois o adenocarcinoma de cólon é das poucas neoplasias sólidas do trato\ngastrointestinal que se beneficiam, em termos de sobrevida global, de ressecções de focos de\ndoença metastática.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-239257","number":"239257","sourceNumber":"239257","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Uma mulher de 43 anos de idade, IMC = 32 kg/m², diabética tipo 2, vai ao\n\npronto-socorro referindo estar com \"hepatite\". Apresenta queixa de epigastralgia e dor em cólica em\nhipocôndrio direito, iniciadas há três dias, inicialmente com melhora parcial após uso de\nanalgésicos comuns. Relata alguns episódios prévios nos últimos meses, em que não buscou\natendimento médico. Há um dia, a dor piorou e ela notou que os olhos estavam mais amarelos e a\nurina mais escura, o que motivou a procura pela consulta. Ao exame físico, apresenta-se em bom\nestado geral, afebril, FR = 26 irpm, FC = 98 bpm, SpO2 = 99%, abdome flácido, doloroso à\npalpação de hipocôndrio direito e sinal de Murphy negativo. Considerando esse caso clínico e com\nbase nos conhecimentos médicos correlatos, julgue o item a seguir. Hepatite aguda e colecistite\naguda são as principais hipóteses diagnósticas.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-239258","number":"239258","sourceNumber":"239258","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Uma mulher de 43 anos de idade, IMC = 32 kg/m², diabética tipo 2, vai ao\n\npronto-socorro referindo estar com \"hepatite\". Apresenta queixa de epigastralgia e dor em cólica em\nhipocôndrio direito, iniciadas há três dias, inicialmente com melhora parcial após uso de\nanalgésicos comuns. Relata alguns episódios prévios nos últimos meses, em que não buscou\natendimento médico. Há um dia, a dor piorou e ela notou que os olhos estavam mais amarelos e a\nurina mais escura, o que motivou a procura pela consulta. Ao exame físico, apresenta-se em bom\nestado geral, afebril, FR = 26 irpm, FC = 98 bpm, SpO2 = 99%, abdome flácido, doloroso à\npalpação de hipocôndrio direito e sinal de Murphy negativo. Considerando esse caso clínico e com\nbase nos conhecimentos médicos correlatos, julgue o item a seguir. A colangiopancreatografia\nretrógrada endoscópica pode ser utilizada como parte do tratamento da paciente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-239259","number":"239259","sourceNumber":"239259","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Uma mulher de 43 anos de idade, IMC = 32 kg/m², diabética tipo 2, vai ao\n\npronto-socorro referindo estar com \"hepatite\". Apresenta queixa de epigastralgia e dor em cólica em\nhipocôndrio direito, iniciadas há três dias, inicialmente com melhora parcial após uso de\nanalgésicos comuns. Relata alguns episódios prévios nos últimos meses, em que não buscou\natendimento médico. Há um dia, a dor piorou e ela notou que os olhos estavam mais amarelos e a\nurina mais escura, o que motivou a procura pela consulta. Ao exame físico, apresenta-se em bom\nestado geral, afebril, FR = 26 irpm, FC = 98 bpm, SpO2 = 99%, abdome flácido, doloroso à\npalpação de hipocôndrio direito e sinal de Murphy negativo. Considerando esse caso clínico e com\nbase nos conhecimentos médicos correlatos, julgue o item a seguir. A colecistectomia está indicada\npara essa paciente, e a via laparoscópica não é a preferencial por tratar-se de paciente diabética e\nobesa.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-255678","number":"255678","sourceNumber":"255678","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Um paciente de 55 anos de idade apresentou quadro de febre, mal-estar e dor\nabdominal difusa. Durante a investigação, foi diagnosticado abscesso hepático com ruptura\nintra-abdominal. A respeito desse caso clínico e tendo em vista os conhecimentos médicos\n\ncorrelatos, julgue o item a seguir. Piperacilina com tazobactam é uma alternativa para o tratamento\nempírico.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-250125","number":"250125","sourceNumber":"250125","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Uma paciente de 44 anos de idade queixa-se de dor abdominal, principalmente em\nhipocôndrio direito, que se iniciou há dois dias. Relata febre de 38 ºC, associada ao quadro, além\nde náuseas. Ao exame, encontrava-se em bom estado geral, desidratada +/4+, anictérica, com\nabdome plano, flácido, doloroso à palpação em hipocôndrio direito e com defesa em hipocôndrio\ndireito. Realizou hemograma, que mostrou 14.500 leucócitos (normal até 10.000), bilirrubinas totais\nde 0,7 (normal até 1) e amilase de 137 (normal até 110). Fez ultrassom, que mostrou vesícula\naumentada de volume, com múltiplos cálculos de até 1,2 cm em seu interior e com paredes\ndelaminadas e com espessura de 6 mm. Com base nesse caso hipotético e nos conceitos médicos\na ele associados, julgue o item a seguir. O diagnóstico mais provável para a paciente é o de\npancreatite aguda e a tomografia computadorizada está indicada.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-250126","number":"250126","sourceNumber":"250126","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Uma paciente de 44 anos de idade queixa-se de dor abdominal, principalmente em\nhipocôndrio direito, que se iniciou há dois dias. Relata febre de 38 ºC, associada ao quadro, além\nde náuseas. Ao exame, encontrava-se em bom estado geral, desidratada +/4+, anictérica, com\nabdome plano, flácido, doloroso à palpação em hipocôndrio direito e com defesa em hipocôndrio\ndireito. Realizou hemograma, que mostrou 14.500 leucócitos (normal até 10.000), bilirrubinas totais\nde 0,7 (normal até 1) e amilase de 137 (normal até 110). Fez ultrassom, que mostrou vesícula\naumentada de volume, com múltiplos cálculos de até 1,2 cm em seu interior e com paredes\ndelaminadas e com espessura de 6 mm. Com base nesse caso hipotético e nos conceitos médicos\na ele associados, julgue o item a seguir. Tratamento com antibióticos e observação constituem a\nconduta mais indicada no momento, devendo a paciente ser submetida à colecistectomia em um\nsegundo tempo.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-250127","number":"250127","sourceNumber":"250127","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Uma paciente de 44 anos de idade queixa-se de dor abdominal, principalmente em\nhipocôndrio direito, que se iniciou há dois dias. Relata febre de 38 ºC, associada ao quadro, além\nde náuseas. Ao exame, encontrava-se em bom estado geral, desidratada +/4+, anictérica, com\nabdome plano, flácido, doloroso à palpação em hipocôndrio direito e com defesa em hipocôndrio\ndireito. Realizou hemograma, que mostrou 14.500 leucócitos (normal até 10.000), bilirrubinas totais\nde 0,7 (normal até 1) e amilase de 137 (normal até 110). Fez ultrassom, que mostrou vesícula\naumentada de volume, com múltiplos cálculos de até 1,2 cm em seu interior e com paredes\ndelaminadas e com espessura de 6 mm. Com base nesse caso hipotético e nos conceitos médicos\na ele associados, julgue o item a seguir. Em comparação com o tratamento pela técnica aberta, a\ncolecistectomia videolaparoscópica para tratamento da doença litiásica tem vantagens.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-250128","number":"250128","sourceNumber":"250128","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Uma paciente de 44 anos de idade queixa-se de dor abdominal, principalmente em\nhipocôndrio direito, que se iniciou há dois dias. Relata febre de 38 ºC, associada ao quadro, além\nde náuseas. Ao exame, encontrava-se em bom estado geral, desidratada +/4+, anictérica, com\nabdome plano, flácido, doloroso à palpação em hipocôndrio direito e com defesa em hipocôndrio\ndireito. Realizou hemograma, que mostrou 14.500 leucócitos (normal até 10.000), bilirrubinas totais\nde 0,7 (normal até 1) e amilase de 137 (normal até 110). Fez ultrassom, que mostrou vesícula\naumentada de volume, com múltiplos cálculos de até 1,2 cm em seu interior e com paredes\ndelaminadas e com espessura de 6 mm. Com base nesse caso hipotético e nos conceitos médicos\na ele associados, julgue o item a seguir. A colangiopancreatografia retrógrada endoscópica está\nbem indicada para promover a drenagem da via biliar e o alívio dos sintomas.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-250129","number":"250129","sourceNumber":"250129","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Uma paciente de 44 anos de idade queixa-se de dor abdominal, principalmente em\nhipocôndrio direito, que se iniciou há dois dias. Relata febre de 38 ºC, associada ao quadro, além\nde náuseas. Ao exame, encontrava-se em bom estado geral, desidratada +/4+, anictérica, com\nabdome plano, flácido, doloroso à palpação em hipocôndrio direito e com defesa em hipocôndrio\ndireito. Realizou hemograma, que mostrou 14.500 leucócitos (normal até 10.000), bilirrubinas totais\nde 0,7 (normal até 1) e amilase de 137 (normal até 110). Fez ultrassom, que mostrou vesícula\naumentada de volume, com múltiplos cálculos de até 1,2 cm em seu interior e com paredes\ndelaminadas e com espessura de 6 mm. Com base nesse caso hipotético e nos conceitos médicos\na ele associados, julgue o item a seguir. Na suspeita de coledocolitíase e na dúvida anatômica das\nvias biliares, a realização de colangiografia intraoperatória durante a colecistectomia está\nindicada.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-196620","number":"196620","sourceNumber":"196620","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Certo paciente de 65 anos de idade, etilista pesado, vem apresentando intensa dor\nabdominal, associada a náuseas e vômitos há oito horas, após nova ingesta alcoólica. É o terceiro\nepisódio abdominal no mesmo mês. Em vista disso, são realizados exames laboratoriais que\nindicam transaminases hepáticas normais, bilirrubinas normais e lipase cinco vezes maior que o\nlimite superior da normalidade. Com base nesse caso clínico e nos conhecimentos médicos\ncorrelatos, julgue o item a seguir. Trata-se de pancreatite aguda biliar.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-196625","number":"196625","sourceNumber":"196625","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Certo paciente de 65 anos de idade, etilista pesado, vem apresentando intensa dor\nabdominal, associada a náuseas e vômitos há oito horas, após nova ingesta alcoólica. É o terceiro\nepisódio abdominal no mesmo mês. Em vista disso, são realizados exames laboratoriais que\nindicam transaminases hepáticas normais, bilirrubinas normais e lipase cinco vezes maior que o\nlimite superior da normalidade. Com base nesse caso clínico e nos conhecimentos médicos\ncorrelatos, julgue o item a seguir. A técnica cirúrgica de Puestow pode ser usada para\ndescompressão do ducto pancreático.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-196627","number":"196627","sourceNumber":"196627","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Certo paciente de 65 anos de idade, etilista pesado, vem apresentando intensa dor\nabdominal, associada a náuseas e vômitos há oito horas, após nova ingesta alcoólica. É o terceiro\nepisódio abdominal no mesmo mês. Em vista disso, são realizados exames laboratoriais que\nindicam transaminases hepáticas normais, bilirrubinas normais e lipase cinco vezes maior que o\nlimite superior da normalidade. Com base nesse caso clínico e nos conhecimentos médicos\ncorrelatos, julgue o item a seguir. A cirurgia de Whipple pode ser empregada para o tratamento da\ndor, com bons resultados, e tem taxa de morbidade baixa.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-196635","number":"196635","sourceNumber":"196635","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Certo paciente de 65 anos de idade, etilista pesado, vem apresentando intensa dor\nabdominal, associada a náuseas e vômitos há oito horas, após nova ingesta alcoólica. É o terceiro\nepisódio abdominal no mesmo mês. Em vista disso, são realizados exames laboratoriais que\nindicam transaminases hepáticas normais, bilirrubinas normais e lipase cinco vezes maior que o\nlimite superior da normalidade. Com base nesse caso clínico e nos conhecimentos médicos\ncorrelatos, julgue o item a seguir. O paciente deve ser orientado para a cessação do alcoolismo.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-154331","number":"154331","sourceNumber":"154331","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente com hiporexia e perda ponderal, astenia, diarreia e vertigem comparece para\navaliação médica. Ao exame, observa-se paciente ictérico. Ele refere dorsalgia progressiva nos\núltimos anos, e nega antecedentes pessoais patológicos. Trouxe resultados de exames de rotina,\ntodos inalterados, exceto pela glicemia de jejum de 200 mg/dl. A respeito do caso exposto, e\nconsiderando os tumores pancreáticos, é CORRETO afirmar que o (a):","options":{"A":"Principal tumor pancreático é o neuroendócrino, e o tipo histológico mais comum é o infiltrante.","B":"Localização mais frequente é a cauda do pâncreas (70% dos casos).","C":"Sexo feminino é fator de risco e tem relação inquestionável com o uso de anticoncepcionais\nhormonais orais ? o tumor é mais comum entre\naqueles acima de 30 anos de idade, que fazem uso\nde anticoncepcionais por mais de cinco anos.","D":"Câncer de pâncreas é o tumor gastrointestinal mais agressivo e apenas 5% dos pacientes com\nesse quadro sobrevivem após cinco anos.","E":"Maioria é sintomática na respectiva fase inicial."},"answer":"D","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-154337","number":"154337","sourceNumber":"154337","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente, 50 anos de idade, vai ao hospital logo pela manhã, chamando pelo respectivo\nmédico, pois iniciou quadro de icterícia e dor abdominal tipo cólica há alguns dias, com piora até o\nmomento. Ao ser admitido, ele foi submetido a ultrassonografia, que resultou no seguinte laudo:\nausente distensão de vesícula biliar, presença de imagem sugestiva de cálculo em região de\ninfundíbulo. Posteriormente, o paciente foi submetido a procedimento cirúrgico, em que se\nconstatou a presença de invasão de dois terços do ducto hepático comum pelo cálculo relatado no\nultrassom. Em relação ao diagnóstico apresentado nesse caso, a classificação no momento da\ncirurgia é do tipo:","options":{"A":"IV.","B":"V.","C":"IIb.","D":"IIa.","E":"III."},"answer":"E","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-135020","number":"135020","sourceNumber":"135020","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Com relação ao tratamento do paciente com câncer, julgue o próximo item. Situação\nhipotética: Um paciente de cinquenta anos\nde idade, sem história familiar de neoplasia colorretal,\ndurante rastreamento de câncer colorretal, foi submetido à mucosectomia devido à identificação de\ndois pólipos adenomastosos tubulares com displasia de baixo grau, sendo um de 4 mm e outro de\n5 mm. Assertiva: Nesse caso, deve-se submeter o paciente à realização de controle\nvideocolonoscópico em três anos. Caso não seja identificada a presença de pólipos nesse controle,\no novo segmento deverá ocorrer após dez anos.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-131813","number":"131813","sourceNumber":"131813","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente masculino de 60 anos de idade, sem comorbidades, deu entrada no\npronto-socorro com quadro de parada de eliminação de gazes e fezes, vômitos fecaloides e\ndistensão abdominal há três dias. Ao exame físico, apresentava-se em REG, desidratado,\n\ndescorado, e taquicárdico. O abdome se apresentava distendido, com ruídos de luta, com sinais de\nirritação peritoneal. O hemograma era de 20.000 leucócitos, com desvio à esquerda de 12%, e os\nraios X mostravam distensão com stop no sigmoide e sinal de Ridler. A respeito desse caso\nhipotético, assinale a alternativa que indica o diagnóstico mais provável.","options":{"A":"Neoplasia de sigmoide obstrutiva complicada com perfuração em cavidade peritoneal.","B":"Bridas.","C":"Íleo biliar.","D":"Apendicite complicada.","E":"Hérnia inguinal com sofrimento de alça e perfuração."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-131821","number":"131821","sourceNumber":"131821","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente masculino de 60 anos de idade, sem comorbidades, deu entrada no\npronto-socorro com quadro de parada de eliminação de gases e fezes, vômitos fecaloides e\ndistensão abdominal há três dias. Ao exame físico, apresentava-se em REG, desidratado,\n\ndescorado e taquicárdico. O abdome se apresentava distendido, com ruídos de luta, com sinais de\nirritação peritoneal. O hemograma era de 20.000 leucócitos, com desvio à esquerda de 12%, e os\nraios X mostravam distensão com stop no sigmoide e sinal de Riddler. Nessa situação hipotética, a\nconduta mais adequada é a seguinte:","options":{"A":"Somente analgesia, pois o paciente idoso com peritonite é considerado de mau prognóstico.","B":"Hidratação + reposição hidroeletrolítica, antibioticoterapia largo espectro e observação.","C":"Hidratação + reposição hidroeletrolítica + passagem de sonda nasogástrica aberta e\nobservação.","D":"Hidratação + reposição hidroeletrolítica, antibioticoterapia largo espectro + laparotomia.","E":"Passagem de stent por colonoscopia."},"answer":"D","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-131830","number":"131830","sourceNumber":"131830","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente masculino de 60 anos de idade, sem comorbidades, deu entrada no\npronto-socorro com quadro de parada de eliminação de gazes e fezes, vômitos fecaloides e\ndistensão abdominal há três dias. Ao exame físico, apresentava-se em REG, desidratado,\n\ndescorado, e taquicárdico. O abdome se apresentava distendido, com ruídos de luta, com sinais de\nirritação peritoneal. O hemograma era de 20.000 leucócitos, com desvio à esquerda de 12%, e os\nraios X mostravam distensão com stop no sigmoide e sinal de Ridler. Considerando que o achado\ncirúrgico foi de peritonite fecal franca devido à perfuração no ceco por um tumor obstrutivo de\nsigmoide, assinale a alternativa que indica a conduta cirúrgica mais adequada no caso hipotético\napresentado.","options":{"A":"Cirurgia de Hartmann.","B":"Cecostomia no local da perfuração.","C":"Ileostomia + sutura da perfuração no ceco.","D":"Colectomia subtotal com ileosigmoidoanastomose mecânica.","E":"Colectomia total com ileostomia e sepultamento do coto retal."},"answer":"E","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-131850","number":"131850","sourceNumber":"131850","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente masculino de 60 anos de idade, sem comorbidades, deu entrada no\npronto-socorro com quadro de parada de eliminação de gazes e fezes, vômitos fecaloides e\ndistensão abdominal há três dias. Ao exame físico, apresentava-se em REG, desidratado,\n\ndescorado, e taquicárdico. O abdome se apresentava distendido, com ruídos de luta, com sinais de\nirritação peritoneal. O hemograma era de 20.000 leucócitos, com desvio à esquerda de 12%, e os\nraios X mostravam distensão com stop no sigmoide e sinal de Ridler. Considere que o paciente do\ncaso hipotético tenha evoluído bem no pós-operatório, seu estadiamento anatomocirúrgico TNM foi\nT3N0M0, mas, ao realizar tomografia computadorizada de abdome de estadiamento, observou-se\numa lesão de 2 cm em lobo esquerdo e cujo PET-Scan mostrou captação de contraste e antígeno\ncarcinoembrionário (CEA) de 15 (normal até 5 para não fumantes). Com base nessa situação,\nassinale a alternattiva que indica a melhor conduta no caso clínico apresentado.","options":{"A":"Apenas seguimento.","B":"Quimioterapia neoadjuvante com Folfox ou Folfiri associado a biológicos + ablação por\nradiofrequência via laparoscópica.","C":"Ressecção imediata aberta da lesão com margem de 1 cm.","D":"Quimioembolização com lipiodol + doxorrubicina.","E":"Quimioterapia exclusiva com 5-fluoracil."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-131827","number":"131827","sourceNumber":"131827","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Considere hipoteticamente que certo paciente de 67 anos da idade, hígido, com boa\nperformance status, procurou o serviço de cirurgia com disfagia e emagrecimento. Na endoscopia\ndigestiva alta, observou-se lesão polipoide de 3 cm limitada a 20% da luz esofágica a 37 cm da\narcada dentária superior. Os exames de imagem indicaram lesão limitada ao esôfago sem\ndisseminação a distância, assim como PET-Scan, e a ecoendoscopia classificou como T4N1M0.\nCom base no exposto assinale a alternativa que indica a conduta mais apropriada nesse caso\nclínico.","options":{"A":"Quimioterapia exclusiva com cisplatina.","B":"Esofagectomia por toracotomia - Ivor-Lewis.","C":"Ressecção endoscópica por ecoendoscopia.","D":"Radioterapia e quimioterapia exclusivas.","E":"Esofagectomia subtotal transhiatal com gastric pull-up."},"answer":"D","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-131806","number":"131806","sourceNumber":"131806","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Com relação ao tumor desmoide, assinale a alternativa correta.","options":{"A":"Não tem relação com a polipose adenomatosa familiar (FAP).","B":"É um tumor maligno e metastatizante.","C":"É afecção de idosos.","D":"Pode ocorrer em até 30% dos casos de FAP.","E":"Após ressecção cirúrgica, apresenta baixos índices de recorrência, em torno de 5%."},"answer":"D","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-131822","number":"131822","sourceNumber":"131822","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Quanto ao tratamento cirúrgico do câncer colorretal, assinale a alternativa CORRETA:","options":{"A":"Os casos de tumores com fístula duodenocólica não devem ser operados, haja vista que invasão\nde duodeno é contraindicação cirúrgica.","B":"A via laparoscópica é contraindicada nos casos com metástases hepáticas.","C":"Tumores do ceco são mais apropriadamente tratados com hemicolectomia direita.","D":"Nos tumores de retossigmoide com invasão do útero, deve-se realizar ressecção multivisceral\ndenominada exenteração pélvica anterior.","E":"A ooforectomia profilática é sempre recomendada."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-134974","number":"134974","sourceNumber":"134974","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Com relação à pesquisa clínica do câncer de intestino, julgue o item que se segue. A\npesquisa de sangue oculto nas fezes é dispensável para análise sobre lesões neoplásicas de\norigem colorretal.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-108156","number":"108156","sourceNumber":"108156","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Com relação ao tubo digestivo, às suas glândulas anexas e às patologias que\nacometem esses sistemas, julgue o item\nsubsequente. O divertículo de Meckel pode ser acometido\npor uma úlcera péptica.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-105555","number":"105555","sourceNumber":"105555","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Um homem de 75 anos de idade foi atendido no posto de saúde com história de dor\nabdominal tipo cólica de leve a moderada intensidade há cerca de um mês. Referiu que\napresentava hematoquezia há cerca de três meses e que, há duas semanas, notou tumor na fossa\nilíaca esquerda de +/- 10 cm de diâmetro. Negou febre e referiu astenia e perda de cerca de 10%\nde seu peso habitual nos últimos dois meses. Negou antecedentes familiares de neoplasias,\ndiabetes e doenças cardiológicas. Com base nesse caso hipotético, no que se refere ao\ndiagnóstico, assinale a alternativa correta.","options":{"A":"A doença diverticular, com formação de plastrão, é o diagnóstico mais provável.","B":"Antes de qualquer exame de imagem, é fundamental a realização de pesquisa de sangue oculto\nnas fezes.","C":"A referência de hematoquezia reforça fortemente a hipótese de diverticulite.","D":"O clister opaco com duplo contraste será fundamental no caso de suspeita de diverticulite.","E":"Para descartar o diagnóstico diferencial com diverticulite, o exame de maior acuidade é a\ntomografia computadorizada."},"answer":"E","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-105536","number":"105536","sourceNumber":"105536","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Um homem de 75 anos de idade foi atendido no posto de saúde com história de dor\nabdominal tipo cólica de leve a moderada intensidade há cerca de um mês. Referiu que\napresentava hematoquezia há cerca de três meses e que, há duas semanas, notou tumor na fossa\nilíaca esquerda de +/- 10 cm de diâmetro. Negou febre e referiu astenia e perda de cerca de 10%\nde seu peso habitual nos últimos dois meses. Negou antecedentes familiares de neoplasias,\ndiabetes e doenças cardiológicas. Considerando esse caso e a hipótese diagnóstica de câncer no\ncólon, assinale a alternativa CORRETA:","options":{"A":"Essa hipótese está enfraquecida, pois, ao contrário do caso descrito, na maior parte dos\npacientes com câncer colorretal o componente genético está presente.","B":"A colonoscopia com biópsia é o melhor exame para o diagnóstico.","C":"A dosagem de Antígeno Carcinoembrionário (CEA) é excelente no rastreamento dessas lesões.","D":"O diagnóstico diferencial com câncer de próstata impõe-se, no presente caso, considerando-se a\nfaixa etária do paciente.","E":"Caso se confirme o diagnóstico de câncer no cólon sigmoide, a terapia neoadjuvante (radio e\nquimioterapia) deverá ser indicada."},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-88694","number":"88694","sourceNumber":"88694","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Atualmente existem inúmeros pacientes em filas de espera para tratamentos definitivos.\nConsiderando que o tempo pode agravar as condições clínicas desses pacientes, julgue o item a\nseguir. Para o portador de megacólon chagásico, o início do tratamento é irrelevante, visto que a\nincidência de volvo de sigmoide é desprezível.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-88713","number":"88713","sourceNumber":"88713","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Atualmente existem inúmeros pacientes em filas de espera para tratamentos definitivos.\nConsiderando que o tempo pode agravar as condições clínicas desses pacientes, julgue o item a\nseguir. Após o sucesso do tratamento clínico de apendicite aguda classificada como\npseudotumoral, o paciente pode esperar de seis a dez semanas pela apendicectomia eletiva, se for\nindicada.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-88660","number":"88660","sourceNumber":"88660","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"A propósito das doenças oncológicas, julgue o próximo item. O câncer colorretal tem\nmaior incidência em pessoas que se alimentam de gorduras saturadas e de alimentos com baixo\nteor de cálcio.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-79648","number":"79648","sourceNumber":"79648","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Para um paciente estável, que realizará uma cirurgia de apendicite aguda, assinale a\nalternativa que apresenta o(s) exame(s) que poderia(m) ser dispensado(s).","options":{"A":"TSH, T3 e T4.","B":"Hb e Ht.","C":"PCR.","D":"Tipagem sanguínea.","E":"Contagem de plaquetas."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-64748","number":"64748","sourceNumber":"64748","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Um homem, 59 anos de idade, submetido à hemicolectomia direita há 6 anos devido a\nadenocarcinoma do cólon, retoma à consulta para ver os resultados do clister opaco de rotina\nrealizado há 21 dias. A radiografia revela um pólipo pedunculado de 1,5 cm na flexura esplênica e\nmúltiplos divertículos. Desse modo, assinale a alternativa que apresenta o procedimento mais\nadequado para este caso.","options":{"A":"Avisar o paciente que é provável que este único pólipo não seja um problema, portanto, não será\nnecessário realizar outros exames ou tornar outras condutas.","B":"Realizar uma laparotomia exploradora para excisar o pólipo e para assegurar que não existem\nmetástases.","C":"Realizar colonoscopia com polipectomia.","D":"Realizar colonoscopia com biópsia é a próxima medida a ser tomada, com ressecção segmentar\nse forem encontrados elementos vilosos.","E":"Repetir o clister opaco em 3 meses, e proceder a excisão do pólipo caso haja alteração do\ntamanho deste."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-64649","number":"64649","sourceNumber":"64649","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Um paciente, 60 anos de idade, queixa-se de dor abdominal tipo cólica, intensidade\nmoderada, há 3 (três) dias, iniciada em\ntopografia de mesogástrio e irradiando posteriormente para\ntodo o abdome. Além disso, menciona vômitos e episódio isolado de diarreia. No seguimento,\nevoluiu com parada de eliminação de fezes e flatos. Ao exame físico: REG, anictérico, acianótico,\nafebril; FC = 95 bpm, FR = 20 irpm, PA = 130 x 90 mmHg, T = 36,5ºC. (O exame abdominal\nevidenciou aumento de ruídos hidroaéreos, timpanismo e dor difusa à palpação com\ndescompressão brusca negativa). O toque retal não evidenciou alterações. O paciente afirma uma\nrealização progressa (3 anos) de ulcerorrafia, devido à úlcera gástrica perfurada. Sendo assim,\nassinale a alternativa que apresenta o diagnóstico sindrômico em questão.","options":{"A":"Abdome Agudo Obstrutivo.","B":"Abdome Agudo Inflamatório.","C":"Abdome Agudo Vascular.","D":"Abdome Agudo Perfurativo.","E":"Abdome Agudo Hemorrágico."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-64734","number":"64734","sourceNumber":"64734","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Uma senhora sexagenária, com hábito intestinal cronicamente obstipado, iniciou quadro\nde dor abdominal, de caráter contínuo, em\nregião de hipogástrio e fossa ilíaca esquerda. Ao exame\nfísico, observa-se febre baixa (37,9 °C), distensão abdominal e palpação profunda dolorosa em\ntodo o andar inferior do abdome, principalmente em quadrante inferior esquerdo. Sendo assim,\nassinale a alternativa que indica o diagnóstico mais provável para este caso.","options":{"A":"Diverticulite aguda.","B":"Síndrome do intestino irritável.","C":"Apendicite.","D":"Retocolite ulcerativa.","E":"Neoplasia de Reto."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-49141","number":"49141","sourceNumber":"49141","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Julgue o próximo item, acerca do apêndice cecal, que é sede de diversas afecções\nbenignas e malignas. As infecções do sítio\nda ferida operatória são as complicações mais comuns\napós apendicectomias realizadas por laparotomia.","options":{"A":"Certo.","B":"Errado."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-45750","number":"45750","sourceNumber":"45750","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Um homem de setenta anos de idade procura a unidade de emergência com queixa de\ndor abdominal em fossa ilíaca esquerda e febre\nfaz cerca de oito horas. Ao exame físico, há grande\ndistensão abdominal e defesa voluntária da musculatura abdominal inferior, e palpa-se um plastrão\nnessa região. Caso a hipótese seja de diverticulite aguda, assinale a alternativa correta:","options":{"A":"A avaliação por exame de ressonância nuclear magnética é contraindicada pelo risco de\ndesbloqueio de um eventual tamponamento de perfuração.","B":"A retossigmoidoscopia flexível é mandatória para a avaliação do grau de comprometimento do\nsigmoide.","C":"A tomografia computadorizada de abdome é preferível em relação ao exame ultrassonográfico\ndo abdome para avaliação nesse momento,\nespecialmente por conta da distensão abdominal\nreferida.","D":"Há indicação de ressecção do segmento intestinal acometido, em caráter de urgência, caso seja\ndetectada qualquer coleção líquida localizada na região pélvica.","E":"O clister opaco, com contraste hidrossolúvel, é o exame inicial de escolha, pois fornecerá\ninformações precisas quanto à localização do segmento inflamado."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-45753","number":"45753","sourceNumber":"45753","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Um homem de setenta anos de idade procura a unidade de emergência com queixa de\ndor abdominal em fossa ilíaca esquerda e febre\nfaz cerca de oito horas. Ao exame físico, há grande\ndistensão abdominal e defesa voluntária de musculatura abdominal inferior, e palpa-se um plastão\nnessa região. Acerca da doença diverticular e da diverticulose, assinale a alternativa correta:","options":{"A":"Evidências epidemiológicas demonstram que as características raciais, e não as dietéticas de\ningestão de baixa quantidade de fibras, são os principais responsáveis pela gênese dos\ndivertículos.","B":"Os divertículos localizam-se mais comumente entre as tênias antimesentéricas.","C":"Apesar de os divertículos serem mais frequentes no sigmoide, a maior parte dos casos de\ndiverticulite aguda acontece no cólon direito.","D":"Os divertículos são herniações da mucosa através do cólon nos locais de penetração da parede\nmuscular pelas arteríolas.","E":"O aspecto endoscópico dos divertículos mimetiza aquele encontrado nos casos de\nadenocarcinomas desse segmento intestinal."},"answer":"E","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-37946","number":"37946","sourceNumber":"37946","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Com referência ao caso de uma paciente de 22 anos de idade, que será submetida à\ncirurgia devido a quadro clínico de apendicite aguda diagnosticada há 12 horas, julgue o item: O\nsinal de Rovsing, evidenciado como dor no quadrante inferior direito do abdome, quando se aplica\npressão sobre o quadrante inferior esquerdo, deve ser pesquisado e pode ser constatado na\npaciente em tela.","options":{"A":"Certo.","B":"Errado."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-37947","number":"37947","sourceNumber":"37947","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Com referência ao caso de uma paciente de 22 anos de idade, que será submetida à\ncirurgia devido a quadro clínico de apendicite aguda diagnosticada há 12 horas, julgue o item: A\nartéria apendicular, que é ramo da artéria ileocólica, deverá ser ligada durante a operação.","options":{"A":"Certo.","B":"Errado."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-32164","number":"32164","sourceNumber":"32164","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Na avaliação por imagem do abdome agudo, as radiografias simples continuam\ndesempenhando um importante papel na obtenção de imagem de pacientes com dor abdominal\naguda. A(s) radiografia(s) de rotina para abdome agudo é(são):","options":{"A":"Radiografia de tórax deitado.","B":"Radiografia de bacia.","C":"Radiografia de tórax em pé e radiografias de abdome em pé e deitado.","D":"Radiografias de abdome, somente.","E":"Radiografia de tórax de perfil."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-334866","number":"334866","sourceNumber":"334866","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"O manejo da colecistite aguda tem passado por mudanças nas últimas décadas.\nAtualmente, são utilizadas as Diretrizes de\nTokyo para critérios de diagnóstico e classificação da\ngravidade da colecistite aguda e da colangite aguda. Considerando essas diretrizes, assinale a\nalternativa correta.","options":{"A":"Mesmo em casos precoces e não graves. é óbvio que as bactérias desempenham um papel\nsignificativo na patologia encontrada.","B":"O tratamento cirúrgico deve ser feito, impreterivelmente, dentro das 72 horas após o\ndiagnóstico.","C":"Nesses casos, a conduta é padrão, independentemente da gravidade do caso e do paciente.","D":"Idealmente, a cirurgia deve ser realizada por cirurgião experiente em laparoscopia.","E":"A terapia antimicrobiana para pacientes com colecistite aguda de grau I e II deve ser mantida por\nsete dias."},"answer":"D","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-334868","number":"334868","sourceNumber":"334868","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"A pancreatite aguda é uma condição inflamatória do pâncreas, caracterizada por dor\nabdominal e níveis elevados de enzimas pancreáticas no sangue. A pancreatite aguda é uma\ncausa frequente de hospitalização, com mortalidade geral de aproximadamente 5%. Várias\ncondições estão associadas à pancreatite aguda, entre as quais é correto citar","options":{"A":"álcool, cálculo na via biliar e hipercolesterolemia.","B":"álcool, cálculo na via biliar e trauma pancreático.","C":"álcool, medicamentosa e hipercolesterolemia.","D":"cálculo na via biliar, medicamentosa e hipercalemia.","E":"cálculo na via biliar, trauma pancreático e hipercalemia."},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-334879","number":"334879","sourceNumber":"334879","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Uma paciente de 40 anos de idade, sem o diagnóstico de doenças prévias, procurou\nassistência no pronto-socorro por apresentar dor em cólica, localizada em hipocôndrio direito, com\nirradiação para a escápula direita 30 minutos após ter participado de uma feijoada da empresa em\nque trabalha. O sintoma associa-se a náuseas e vômitos. O exame físico mostrou a paciente com\nfácies de dor e com IMC igual a 40 kg/m². Nesse caso, a causa mais provável da dor é","options":{"A":"infarto agudo do miocárdio.","B":"úlcera péptica perfurada.","C":"pneumonia.","D":"cólica biliar.","E":"nefrolitíase."},"answer":"D","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-343436","number":"343436","sourceNumber":"343436","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Dados os critérios prognósticos na Pancreatite Aguda, está INCORRETO:","options":{"A":"Aumento do hematócrito, após 48h, pois irá avaliar o valor real, já que na admissão pode estar\n\n?mascarado?.","B":"Glicemia, que, se elevada, pode indicar um processo inicial de insuficiência pancreática.","C":"Idade, que, quanto mais avançada, mais o indivíduo se torna suscetível às complicações graves.","D":"AST (Aspartato Aminotransferase), que, se elevado, indica lesão orgânica, principalmente\nhepática."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-301270","number":"301270","sourceNumber":"301270","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Uma paciente de 37 anos de idade apresenta dor abdominal de forte intensidade em\nregião epigástrica, em hipocôndrio direito e dorso há um dia, acompanhada de náuseas e vômitos.\nNega episódios anteriores. Ao exame, encontrava-se desidratada ++/4+, com pulso de 112 bpm e\nPA = 130 mmHg X 80 mmHg. Verificaram-se abdome globoso, flácido, pouco doloroso à palpação\nem epigástrio e Murphy negativo, com descompressão brusca negativa. Os exames iniciais\nmostram Hb = 14,7 g/dL, leucócitos 14.760/mm³, e creatinina = 1,6 mg/dL, amilase = 870 UI e\nbilirrubinas totais = 2,3 mg/dL. Considerando esse caso clínico, julgue os itens de 26 a 30. A\nhidratação é a medida mais eficaz para essa paciente nas primeiras 48 horas.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-301271","number":"301271","sourceNumber":"301271","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Uma paciente de 37 anos de idade apresenta dor abdominal de forte intensidade em\nregião epigástrica, em hipocôndrio direito e dorso há um dia, acompanhada de náuseas e vômitos.\nNega episódios anteriores. Ao exame, encontrava-se desidratada ++/4+, com pulso de 112 bpm e\nPA = 130 mmHg X 80 mmHg. Verificaram-se abdome globoso, flácido, pouco doloroso à palpação\nem epigástrio e Murphy negativo, com descompressão brusca negativa. Os exames iniciais\nmostram Hb = 14,7 g/dL, leucócitos 14.760/mm³, e creatinina = 1,6 mg/dL, amilase = 870 UI e\nbilirrubinas totais = 2,3 mg/dL. Considerando esse caso clínico, julgue os itens de 26 a 30. O\nemprego de antibióticos de amplo espectro está bem indicado nesse caso.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-301272","number":"301272","sourceNumber":"301272","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Uma paciente de 37 anos de idade apresenta dor abdominal de forte intensidade em\nregião epigástrica, em hipocôndrio direito e dorso há um dia, acompanhada de náuseas e vômitos.\nNega episódios anteriores. Ao exame, encontrava-se desidratada ++/4+, com pulso de 112 bpm e\nPA = 130 mmHg X 80 mmHg. Verificaram-se abdome globoso, flácido, pouco doloroso à palpação\nem epigástrio e Murphy negativo, com descompressão brusca negativa. Os exames iniciais\nmostram Hb = 14,7 g/dL, leucócitos 14.760/mm³, e creatinina = 1,6 mg/dL, amilase = 870 UI e\nbilirrubinas totais = 2,3 mg/dL. Considerando esse caso clínico, julgue os itens de 26 a 30. Nesse\ncaso, a colangiografia retrógrada endoscópica é um exame fundamental para ser realizado nas\nprimeiras 24 horas.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-301273","number":"301273","sourceNumber":"301273","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Uma paciente de 37 anos de idade apresenta dor abdominal de forte intensidade em\nregião epigástrica, em hipocôndrio direito e dorso há um dia, acompanhada de náuseas e vômitos.\nNega episódios anteriores. Ao exame, encontrava-se desidratada ++/4+, com pulso de 112 bpm e\nPA = 130 mmHg X 80 mmHg. Verificaram-se abdome globoso, flácido, pouco doloroso à palpação\nem epigástrio e Murphy negativo, com descompressão brusca negativa. Os exames iniciais\nmostram Hb = 14,7 g/dL, leucócitos 14.760/mm³, e creatinina = 1,6 mg/dL, amilase = 870 UI e\nbilirrubinas totais = 2,3 mg/dL. Considerando esse caso clínico, julgue os itens de 26 a 30. O\nultrassom é um exame obrigatório para essa paciente e que trará informações importantes para a\ncondução do caso.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-301279","number":"301279","sourceNumber":"301279","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Uma paciente de 44 anos de idade, com diabetes tipo 2, relata dores abdominais há\ncerca de seis meses, principalmente em\nhipocôndrio direito e flanco direito. Realizou ultrassom de\nabdome, o qual mostrou múltiplos cálculos na vesícula biliar, que se encontrava com paredes finas\ne sem dilatação de vias biliares. Apresentava bilirrubina total de 0,7 mg/dL, AST = 35 UI (normal\naté\n40), ALT = 64 (normal até 40 UI), fosfatase alcalina = 342 UI (normal até 250) e Gama GT = 743 UI\n(normal até 110). Com base nesse caso clínico hipotético, julgue o item. O acompanhamento clínico\ne a monitorização dos sintomas representam uma alternativa adequada e segura para conduzir\nesse caso.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-301280","number":"301280","sourceNumber":"301280","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Uma paciente de 44 anos de idade, com diabetes tipo 2, relata dores abdominais há\ncerca de seis meses, principalmente em\nhipocôndrio direito e flanco direito. Realizou ultrassom de\nabdome, o qual mostrou múltiplos cálculos na vesícula biliar, que se encontrava com paredes finas\ne sem dilatação de vias biliares. Apresentava bilirrubina total de 0,7 mg/dL, AST = 35 UI (normal\naté\n40), ALT = 64 (normal até 40 UI), fosfatase alcalina = 342 UI (normal até 250) e Gama GT = 743 UI\n(normal até 110). Com base nesse caso clínico hipotético, julgue o item. A realização de\ncolangiografia intra-operatória é uma conduta adequada na pesquisa de coledocolitiase associada.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-301282","number":"301282","sourceNumber":"301282","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Uma paciente de 44 anos de idade, com diabetes tipo 2, relata dores abdominais há\ncerca de seis meses, principalmente em\nhipocôndrio direito e flanco direito. Realizou ultrassom de\nabdome, o qual mostrou múltiplos cálculos na vesícula biliar, que se encontrava com paredes finas\ne sem dilatação de vias biliares. Apresentava bilirrubina total de 0,7 mg/dL, AST = 35 UI (normal\naté\n40), ALT = 64 (normal até 40 UI), fosfatase alcalina = 342 UI (normal até 250) e Gama GT = 743 UI\n(normal até 110). Com base nesse caso clínico hipotético, julgue o item. A laparoscópica é a via de\nacesso de eleição, caso seja escolhido pelo tratamento cirúrgico.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-268881","number":"268881","sourceNumber":"268881","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Uma paciente de 45 anos de idade procura atendimento após ter realizado uma\ntomografia com contraste de abdome total, com\nachado de nódulo com realce periférico durante\nfase arterial e impregnação centrípeta pelo meio de contraste na fase tardia. Com base nesse caso\nclínico, nos conhecimentos relativos aos tumores hepáticos benignos e nos assuntos correlatos,\nassinale a alternativa incorreta.","options":{"A":"Esse tumor hepático benigno trata-se de um adenoma hepático.","B":"A utilização de anticoncepcional combinado oral deve ser suspendida imediatamente, caso se\ndiagnostique um hemangioma hepático.","C":"A ruptura espontânea de um hemangioma é extremamente rara, não se justificando a realização\nde cirurgia pelo risco de sangramento.","D":"O hemangioma é o segundo tumor benigno hepático mais comum.","E":"O hemangioma hepático tem potencial de malignização superior ao do adenoma hepático."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-268882","number":"268882","sourceNumber":"268882","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Um paciente de 55 anos de idade, ex-alcoolista, cirrótico, portador do vírus da hepatite\nB, inicia com dor em quadrante superior direito\ne apresenta perda ponderal de 15 kg em três\nmeses. Considerando os carcinomas hepatocelulares e os conhecimentos médicos correlatos,\nassinale a alternativa correta.","options":{"A":"Mais de 50% dos pacientes cirróticos desenvolverão risco para carcinoma hepatocelulares.","B":"Esse é o tumor de fígado mais comum.","C":"A cirrose por esteato-hepatite não alcoólica (NASH) não está relacionada com o carcinoma\nhepatocelular.","D":"O diagnóstico pode ser estabelecido radiologicamente. Na fase arterial, contrasta de maneira\nmais intensa do que o parênquima hepático ao seu redor; já na fase venosa e tardia, contrasta\nmenos que o parênquima.","E":"A ultrassonografia não é um método de escolha para monitoramento de nódulos no fígado."},"answer":"D","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-291467","number":"291467","sourceNumber":"291467","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente de 60 anos de idade, masculino, procura hospital de atenção secundária com\nhistória de \"olhos amarelados\" há cerca de 4 semanas. Refere \"desconforto\" discreto em epigástrio\ne hipocôndrio direito. Nega febre. Ao exame físico, paciente emagrecido, ictérico 4+/4+, eupneico,\nnormocorado. Abdome plano, flácido, depressível, com vesícula biliar palpável, indolor, sinal de\nMurphy negativo. Com base nessas informações, qual hipótese diagnóstica para o caso clínico\ndescrito?","options":{"A":"Pancreatite aguda.","B":"Colangite.","C":"Abscesso hepático.","D":"Neoplasia de cabeça de pâncreas."},"answer":"D","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-266418","number":"266418","sourceNumber":"266418","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Uma mulher de 55 anos de idade realizou um ultrassom de abdome de rotina, solicitado\npelo seu ginecologista em consulta anual. O\nultrassom evidenciou lesão cística de\naproximadamente 4 cm, contendo septações, em cauda pancreática. A mulher não apresenta\nqueixas abdominais nem antecedentes importantes. Com relação ao caso clínico precedente e às\nlesões císticas pancreáticas, julgue o próximo item. Entre as lesões císticas do pâncreas, há\npredomínio de lesões benignas.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-263349","number":"263349","sourceNumber":"263349","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Uma mulher com 36 anos de idade, obesa e multípara, é admitida no pronto-socorro\ncom quadro de febre alta com calafrios, dor\nno hipocôndrio direito e icterícia. Ela tem histórico de\ndor abdominal recorrente no hipocôndrio direito, geralmente associada à ingestão de alimentação\ngordurosa. Ao chegar a essa unidade hospitalar, encontra-se torporosa, febril (39,6°C), com PA =\n90 x 60 mmHg, reagindo com fácies de dor à compressão do hipocôndrio direito, mas com sinal de\nMurphy ausente. Os exames laboratoriais da paciente revelam leucócitos = 22.000/mm³ (valor de\nreferência: 6.000 a 10.000/mm³), com 17% de bastões e 3% de metamielócitos e bilirrubina direta =\n4,8 mg/dl (valor de referência: até 0,3 mg/dl), fosfatase alcalina = 420 UI/L (valor de referência:\n70 a\n192 UI/L) e gama-glutamil transferase = 302 UI/L (valor de referência 70 a 192 UI/L). A\nultrassonografia abdominal da paciente mostra a presença de dilatação das vias biliares\n\nextra-hepáticas, e a vesícula biliar com algumas imagens hiperdensas e com sombra acústica\nposterior. Diante desse quadro clínico, qual é o diagnóstico CORRETO?","options":{"A":"Colangite aguda com pêntade de Reynolds.","B":"Colangite aguda com tríade de Charcot.","C":"Colecistite crônica alitiásica.","D":"Colecistite aguda litiásica."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-266419","number":"266419","sourceNumber":"266419","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Uma mulher de 55 anos de idade realizou um ultrassom de abdome de rotina, solicitado\npelo seu ginecologista em consulta anual. O\nultrassom evidenciou lesão cística de\naproximadamente 4 cm, contendo septações, em cauda pancreática. A mulher não apresenta\nqueixas abdominais nem antecedentes importantes. Com relação ao caso clínico precedente e às\nlesões císticas pancreáticas, julgue o próximo item. Para a paciente do caso relatado, há indicação\nde seguimento da lesão por ultrassom, pela alta sensibilidade, ou tomografia computadorizada de\nabdome.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-266420","number":"266420","sourceNumber":"266420","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Uma mulher de 55 anos de idade realizou um ultrassom de abdome de rotina, solicitado\npelo seu ginecologista em consulta anual. O\nultrassom evidenciou lesão cística de\naproximadamente 4 cm, contendo septações, em cauda pancreática. A mulher não apresenta\nqueixas abdominais nem antecedentes importantes. Com relação ao caso clínico precedente e às\nlesões císticas pancreáticas, julgue o próximo item. A neoplasia mucinosa papilar intraductal pode\nacometer o ducto pancreático principal e(ou) os ductos secundários, sendo o risco de malignização\nmaior quando ela acomete o ducto principal.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-266421","number":"266421","sourceNumber":"266421","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Uma mulher de 55 anos de idade realizou um ultrassom de abdome de rotina, solicitado\npelo seu ginecologista em consulta anual. O\nultrassom evidenciou lesão cística de\naproximadamente 4 cm, contendo septações, em cauda pancreática. A mulher não apresenta\nqueixas abdominais nem antecedentes importantes. Com relação ao caso clínico precedente e às\nlesões císticas pancreáticas, julgue o próximo item. As lesões císticas mucinosas têm pouco risco\nde malignização e, em regra, não é necessário operá-las.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-266422","number":"266422","sourceNumber":"266422","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Uma paciente do sexo feminino, com 37 anos de idade, procurou a emergência\nhospitalar por apresentar dor em hipocôndrio\ndireito havia 2 dias, com melhora parcial ao uso de\nanalgésicos, porém sem remissão completa, associada a náuseas sem vômitos. A paciente referiu\ndiagnóstico prévio de colelitíase assintomática. No exame físico, apresentou icterícia de esclera e\npele, além de dor à palpação profunda em hipocôndrio direito. Com relação a esse caso clínico e às\ndoenças das vias biliares, julgue o item subsequente. O resultado da dosagem das bilirrubinas\ndireta e indireta direciona a investigação para etiologia obstrutiva da via biliar ou outras causas\nclínicas de icterícia.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-266425","number":"266425","sourceNumber":"266425","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Uma paciente do sexo feminino, com 37 anos de idade, procurou a emergência\nhospitalar por apresentar dor em hipocôndrio\ndireito havia 2 dias, com melhora parcial ao uso de\nanalgésicos, porém sem remissão completa, associada a náuseas sem vômitos. A paciente referiu\ndiagnóstico prévio de colelitíase assintomática. No exame físico, apresentou icterícia de esclera e\npele, além de dor à palpação profunda em hipocôndrio direito. Com relação a esse caso clínico e às\ndoenças das vias biliares, julgue o item subsequente. Uma das causas de icterícia em pacientes\ncom histórico de litíase biliar é a síndrome de Mirizzi.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-266426","number":"266426","sourceNumber":"266426","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Uma paciente do sexo feminino, com 37 anos de idade, procurou a emergência\nhospitalar por apresentar dor em hipocôndrio\ndireito havia 2 dias, com melhora parcial ao uso de\nanalgésicos, porém sem remissão completa, associada a náuseas sem vômitos. A paciente referiu\ndiagnóstico prévio de colelitíase assintomática. No exame físico, apresentou icterícia de esclera e\npele, além de dor à palpação profunda em hipocôndrio direito. Com relação a esse caso clínico e às\ndoenças das vias biliares, julgue o item subsequente. O tratamento ideal da colecistite aguda\nlitiásica deve ser iniciado, em até 72 horas, com antibioticoterapia seguida de colecistectomia.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-273332","number":"273332","sourceNumber":"273332","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Em relação à Pancreatite Aguda (PA), é correto afirmar:","options":{"A":"O grau de elevação das enzimas pancreáticas relaciona-se com gravidade da doença.","B":"A amilase é superior à lipase para diagnóstico da PA por apresentar vida média mais longa.","C":"O sinal de Cullen é a coloração azulada periumbilical e está associado à gravidade da PA.","D":"Em 80% das vezes a doença tem curso grave e necrosante."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-291482","number":"291482","sourceNumber":"291482","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Uma mulher de 61 anos de idade, acompanhada pela filha, foi atendida em ambulatório\nde hospital secundário referindo ter apresentado\ndor no hipocôndrio direito e vômito por 3 dias, há\n30 dias. Relatava fazer uso de metformina 500 mg, 2 vezes por dia e atenolol 50 mg por dia.\n\nTrouxe ultrassonografia que descrevia a vesícula biliar com paredes discretamente espessadas e\npresença de colelitíase. Os exames laboratoriais evidenciaram glicemia de 120 mg/dL (referência:\n75 a 99), creatinina 0,99 mg/dL (referência: 0,6 a 1,1), leucócitos 6 200/mm³ (referência: 3 500 a\n10\n500), não apresentava alteração na contagem diferencial dos leucócitos. Ao exame físico, o\nabdome estava flácido, não relatava dor à palpação, PA = 140/80 mmHg, temperatura axilar = 36,5\nºC. Com base nos dados apresentados, qual alternativa apresenta a orientação correta à paciente e\na filha sobre a conduta a ser seguida?","options":{"A":"Indicar tratamento operatório se apresentar dor novamente.","B":"Tratar as doenças clínicas e realizar controle com ultrassonografia anual.","C":"Encaminhar ao pronto-socorro para tratamento operatório.","D":"Compensar melhor a glicemia e indicar tratamento operatório eletivo."},"answer":"D","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-266443","number":"266443","sourceNumber":"266443","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Uma paciente do sexo feminino, de 40 anos de idade, procurou a emergência médica\npor apresentar dor abdominal em andar superior\nde abdome, de forte intensidade, em barra,\ninédita, iniciada havia cerca de uma hora, associada a vômitos. Ela referiu ingesta prévia de comida\ngordurosa e negou etilismo e tabagismo. A paciente tem sobrepeso e dislipidemia não tratada. Os\nexames laboratoriais evidenciaram hiperamilasemia, e a ecografia de abdome superior indicou\ncolelitíase e coledocolitíase. No que se refere a esse caso clínico hipotético, julgue o próximo\nitem.\nA dislipidemia decorrente da hipercolesterolemia pode causar pancreatite.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-266444","number":"266444","sourceNumber":"266444","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Uma paciente do sexo feminino, de 40 anos de idade, procurou a emergência médica\npor apresentar dor abdominal em andar superior\nde abdome, de forte intensidade, em barra,\ninédita, iniciada havia cerca de uma hora, associada a vômitos. Ela referiu ingesta prévia de comida\ngordurosa e negou etilismo e tabagismo. A paciente tem sobrepeso e dislipidemia não tratada. Os\nexames laboratoriais evidenciaram hiperamilasemia, e a ecografia de abdome superior indicou\ncolelitíase e coledocolitíase. No que se refere a esse caso clínico hipotético, julgue o próximo\nitem.\nNos casos de coledolitíase e pancreatite, indica-se colecistectomia imediata, sem necessidade de\nexploração de vias biliares.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-266445","number":"266445","sourceNumber":"266445","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Uma paciente do sexo feminino, de 40 anos de idade, procurou a emergência médica\npor apresentar dor abdominal em andar superior\nde abdome, de forte intensidade, em barra,\ninédita, iniciada havia cerca de uma hora, associada a vômitos. Ela referiu ingesta prévia de comida\ngordurosa e negou etilismo e tabagismo. A paciente tem sobrepeso e dislipidemia não tratada. Os\nexames laboratoriais evidenciaram hiperamilasemia, e a ecografia de abdome superior indicou\ncolelitíase e coledocolitíase. No que se refere a esse caso clínico hipotético, julgue o próximo\nitem.\nAmilase sérica em níveis dez vezes maiores que o normal é critério de mau prognóstico nos casos\nde pancreatite aguda.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-266446","number":"266446","sourceNumber":"266446","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Uma paciente do sexo feminino, de 40 anos de idade, procurou a emergência médica\npor apresentar dor abdominal em andar superior\nde abdome, de forte intensidade, em barra,\ninédita, iniciada havia cerca de uma hora, associada a vômitos. Ela referiu ingesta prévia de comida\ngordurosa e negou etilismo e tabagismo. A paciente tem sobrepeso e dislipidemia não tratada. Os\nexames laboratoriais evidenciaram hiperamilasemia, e a ecografia de abdome superior indicou\ncolelitíase e coledocolitíase. No que se refere a esse caso clínico hipotético, julgue o próximo\nitem.\nA ultrassonografia de abdome é um exame essencial nos casos de pancreatite, para elucidar causa\nbiliar.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-266447","number":"266447","sourceNumber":"266447","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Uma paciente do sexo feminino, de 40 anos de idade, procurou a emergência médica\npor apresentar dor abdominal em andar superior\nde abdome, de forte intensidade, em barra,\ninédita, iniciada havia cerca de uma hora, associada a vômitos. Ela referiu ingesta prévia de comida\ngordurosa e negou etilismo e tabagismo. A paciente tem sobrepeso e dislipidemia não tratada. Os\nexames laboratoriais evidenciaram hiperamilasemia, e a ecografia de abdome superior indicou\ncolelitíase e coledocolitíase. No que se refere a esse caso clínico hipotético, julgue o próximo\nitem.\nO tratamento da pancreatite aguda envolve uso de antibióticos endovenosos, independentemente\nde achado radiológico ou do quadro clínico do paciente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-263413","number":"263413","sourceNumber":"263413","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Um homem com 34 anos de idade, em acompanhamento e tratamento ambulatorial há\n5 anos por retocolite ulcerativa, é\ninternado em hospital terciário para investigação diagnóstica de\nquadro de prurido generalizado. Seu exame físico é normal, salvo pela presença de escoriações\ndifusas e de cicatriz cutânea antiga no membro inferior direito por pioderma gangrenoso. Exames\nlaboratoriais recentes revelam níveis séricos extremamente elevados (cerca de 10 vezes acima do\nlimite superior normal [LSN]) da fosfase alcalina e níveis cerca de 2 vezes o LSN das\naminotransferases, sendo normais os níveis séricos de bilirrubinas. As concentrações sanguíneas\nde IgG, em particular da fração IgG4, são normais e as pesquisas de anticorpos anti-mitocôndria,\nanti-LKM1 e anti-músculo liso se revelam negativas. É solicitada uma colangiopancreatografia por\nressonância magnética, que revela a presença de múltiplas estenoses fibróticas nas vias biliares\nintra-hepáticas, sendo tais estenoses entremeadas por dilatações saculares de áreas\naparentemente normais, conferindo um aspecto em \"contas de rosário\". Qual é o diagnóstico do\nquadro colestático desse paciente?","options":{"A":"Peri-hepatite aguda.","B":"Cirrose biliar primária.","C":"Colangite esclerosante.","D":"Hepatite crônica autoimune."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-263432","number":"263432","sourceNumber":"263432","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Um paciente com 70 anos de idade foi atendido no pronto-socorro de hospital de nível\nsecundário, relatando dor abdominal com irradiação para região dorsal, além de emagrecimento, há\n4 meses. Há 2 meses, começou a apresentar prurido cutâneo progressivo e urina escura. Há 15\ndias, notou que os ''olhos ficaram amarelos''. Na ocasião do exame físico, encontrava-se\nemagrecido, ictérico (++/4+), com escoriações dérmicas provocadas pelo ato de coçar. A borda do\nfígado era palpada a 1,5 cm abaixo de rebordo costal direito, com palpação não dolorosa. Com\nbase no caso clínico, os resultados dos exames laboratoriais que confirmam a hipótese diagnóstica\nsão","options":{"A":"aumento da bilirrubina indireta e aumento da amilase.","B":"aumento da bilirrubina direta e aumento da fosfatose alcalina.","C":"aumento da bilirrubina indireta e aumento da alanina aminotransferase.","D":"aumento da bilirrubina direta e diminuição do tempo de protrombina em segundos."},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-244462","number":"244462","sourceNumber":"244462","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"A respeito de pancreatite, assinale a alternativa correta.","options":{"A":"Pancreatite aguda em paciente que se apresenta na admissão com idade abaixo de 70 anos,\nglicemia abaixo de 220 mg/dL e LDH sérico menos que 350 IU/L e leucograma abaixo de 18.000\nleucócitos totais é considerada leve, independentemente da etiologia.","B":"O tratamento inicial de pancreatite aguda grave é reposição volêmica, estabilização do quadro\nclínico e colangiopancreatografia retrógrada endoscópica com papilostomia.","C":"A presença de coleção peripancreática identificada em tomografia sempre indica drenagem\ncirúrgica.","D":"Nunca é indicado o uso de nutrição parenteral para paciente com pancreatite em razão do risco\nde hiperlipidemia.","E":"Alcoolismo, hiperparatireoidismo e hiperlipidemia são fatores de risco para pancreatite crônica."},"answer":"E","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-227372","number":"227372","sourceNumber":"227372","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente de sessenta e oito anos de idade, tabagista, procurou atendimento médico\ncom quadro de colestase iniciado havia duas\nsemanas. Apresentava icterícia, colúria, acolia e\nprurido generalizado, além de perda ponderal de 4 kg desde o início das queixas. No exame físico,\nconstataram-se icterícia 3+/4+ e tumoração palpável arredondada e indolor, no quadrante superior\ndireito do abdome. No que se refere a esse caso clínico, julgue o item subsecutivo. Se a hipótese\ndiagnóstica principal for coledocolitíase, o exame mais indicado para a confirmação do diagnóstico\né a tomografia computadorizada de abdome.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-244467","number":"244467","sourceNumber":"244467","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Existem três tipos de abscessos hepáticos; piogênico, amebiano e fúngico. Acerca\ndesse tema, assinale a alternativa correta.","options":{"A":"No abscesso piogênico, pode ocorrer infecção bacteriana secundária, principalmente, por\nestafilococos, estreptococos e E. coli.","B":"O tratamento do abscesso amebiano consiste em quimioterapia combinada com aspiração ou\ndrenagem cirúrgica em casos selecionados.","C":"Geralmente o lobo hepático esquerdo é mais acometido por abcessos amebianos que o lobo\ndireito.","D":"A presença de um halo (edema) ao redor do abscesso é raro, mas enfatiza o diagnóstico de\nabscesso fúngico.","E":"O abscesso do tipo piogênico é o mais raro entre os abscessos hepáticos."},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-227373","number":"227373","sourceNumber":"227373","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente de sessenta e oito anos de idade, tabagista, procurou atendimento médico\ncom quadro de colestase iniciado havia duas\nsemanas. Apresentava icterícia, colúria, acolia e\nprurido generalizado, além de perda ponderal de 4 kg desde o início das queixas. No exame físico,\nconstataram-se icterícia 3+/4+ e tumoração palpável arredondada e indolor, no quadrante superior\ndireito do abdome. No que se refere a esse caso clínico, julgue o item subsecutivo. No caso em\napreço, há risco de colangite supurativa aguda, que está associada a mortalidade de até 30% nos\ncasos mais graves.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-227374","number":"227374","sourceNumber":"227374","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente de sessenta e oito anos de idade, tabagista, procurou atendimento médico\ncom quadro de colestase iniciado havia duas\nsemanas. Apresentava icterícia, colúria, acolia e\nprurido generalizado, além de perda ponderal de 4 kg desde o início das queixas. No exame físico,\nconstataram-se icterícia 3+/4+ e tumoração palpável arredondada e indolor, no quadrante superior\ndireito do abdome. No que se refere a esse caso clínico, julgue o item subsecutivo. Entre os\ntumores periampulares, o de melhor prognóstico é o adenocarcinoma de papila duodenal.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-244469","number":"244469","sourceNumber":"244469","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Professora de 40 anos de idade apresenta-se no hospital com início súbito de dor\nabdominal intensa tipo pontada, com irradiação para o dorso esquerdo, associada a náuseas e\nvômitos iniciados há 24 horas, com fatores de alívio em se sentar e inclinar-se para a frente, e\nfatores de agravo em decúbito dorsal. Ela nega o uso de álcool e não fuma. Possui diabetes tipo 2\nem metformina e obesidade centrípeta. Ela é G2P2A0. Ao exame físico, encontra-se anictérica,\nacianótica, com palidez e sudorese fria, IMC = 40; PA = 80 mmHg x 40 mmHg, FC = 110/minuto,\nFR = 25 irpm, Tax = 38,5 ºC, SatO2 = 88%. Ao exame abdominal, constatam-se presença de\nequimoses em flanco esquerdo associado a região periumbilical, sensibilidade difusa em todo o\nabdome no exame abdominal, Blumberg negativo. RHA estão ausentes. Acerca desse caso clínico\ne tendo em vista os conhecimentos médicos relativos à pancreatite aguda (PA), assinale a\nalternativa correta.","options":{"A":"Pacientes com pancreatite grave podem apresentar febre, taquipneia, hipoxemia e hipotensão.\n\nEm 3% dos pacientes com PA, pode-se observar descoloração equimótica na região periumbilical\n(sinal de Cullen) ou ao longo do flanco (sinal\nde Gray Turner).","B":"Muitos medicamentos têm sido associados à PA, sendo comum a associação do uso de\nmetformina e PA, que é provável etiologia do paciente.","C":"A paciente apresenta o diagnóstico de PA, conforme critérios de Ransom para o qual dois\ncritérios maiores estejam presentes: dor\nabdominal sugestiva de pancreatite; uma elevação da\namilase sérica ou lipase sérica três vezes acima do normal; e evidência de TC ou RM consistente\ncom pancreatite.","D":"De acordo com a classificação de Atlanta, a paciente apresenta um quadro de PA edematosa\nintersticial, caracterizada por inflamação aguda do parênquima pancreático e dos tecidos\nperipancreáticos, com necrose tecidual reconhecível.","E":"O sistema de pontuação para prever a gravidade da PA com base em parâmetros clínicos,\nlaboratoriais, radiológicos e marcadores séricos,\nmais utilizado em PA é o escore de APACHE II;\ndevem ser usados na admissão e após 48 horas do diagnóstico."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-227375","number":"227375","sourceNumber":"227375","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente de sessenta e oito anos de idade, tabagista, procurou atendimento médico\ncom quadro de colestase iniciado havia duas\nsemanas. Apresentava icterícia, colúria, acolia e\nprurido generalizado, além de perda ponderal de 4 kg desde o início das queixas. No exame físico,\nconstataram-se icterícia 3+/4+ e tumoração palpável arredondada e indolor, no quadrante superior\ndireito do abdome. No que se refere a esse caso clínico, julgue o item subsecutivo. O paciente em\nquestão apresenta o sinal de Curvosier-Terrier.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-227376","number":"227376","sourceNumber":"227376","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente de sessenta e oito anos de idade, tabagista, procurou atendimento médico\ncom quadro de colestase iniciado havia duas\nsemanas. Apresentava icterícia, colúria, acolia e\nprurido generalizado, além de perda ponderal de 4 kg desde o início das queixas. No exame físico,\nconstataram-se icterícia 3+/4+ e tumoração palpável arredondada e indolor, no quadrante superior\ndireito do abdome. No que se refere a esse caso clínico, julgue o item subsecutivo. Em razão da\npresença de tumor palpável no quadrante superior direito do abdome, o diagnóstico principal é de\ntumor de vesícula biliar.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-227377","number":"227377","sourceNumber":"227377","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente de sessenta e oito anos de idade, tabagista, procurou atendimento médico\ncom quadro de colestase iniciado havia duas\nsemanas. Apresentava icterícia, colúria, acolia e\nprurido generalizado, além de perda ponderal de 4 kg desde o início das queixas. No exame físico,\nconstataram-se icterícia 3+/4+ e tumoração palpável arredondada e indolor, no quadrante superior\ndireito do abdome. No que se refere a esse caso clínico, julgue o item subsecutivo. O referido\npaciente pode apresentar distúrbios de coagulação relacionados à doença de base apresentada.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-203047","number":"203047","sourceNumber":"203047","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Um paciente de 30 anos de idade realizou tomografia computadorizada de abdome em\nrazão de dor abdominal com achado de lesão sólido-cística de 8 cm x 10 cm em região de\n\ncorpo-cauda de pâncreas. Quanto a esse caso clínico, é correto afirmar que o diagnóstico mais\nprovável é:","options":{"A":"tumor de Frantz.","B":"Adenocarcinoma de pâncreas.","C":"Tumor neuroendócrino.","D":"Pseudocisto pancreático.","E":"Nesidioblastose."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-203080","number":"203080","sourceNumber":"203080","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Um paciente de 45 anos de idade procura o ambulatório de cirurgia geral em razão de\nachado incidental de um pólipo de vesícula de 5\nmm ao ultrassom de abdome. Acerca desse caso\nclínico, em relação à conduta adequada, assinale a alternativa CORRETA:","options":{"A":"Deve-se realizar uma colecistectomia videolaparoscópica.","B":"Deve-se completar a investigação com uma colangiorressonância.","C":"Não é necessário realizar nenhum exame ou acompanhamento.","D":"Deve-se realizar ultrassom, a cada três meses, para acompanhar o crescimento.","E":"Deve-se manter uma conduta expectante, com novo ultrassom em seis meses."},"answer":"E","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-212046","number":"212046","sourceNumber":"212046","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente do sexo feminino, de 37 anos de idade, faxineira, quatro filhos, foi atendida no\npronto-socorro hospitalar com índice de massa corporal de 32 e histórico de crises dispépticas e\ncólicas abdominais, localizadas em epigástrio. O quadro clínico evoluiu nas últimas 8 horas com dor\nforte e contínua no epigástrio e hipocôndrio direito, houve remissão transitória, com o uso de\nanalgésicos orais, e dois episódios de vômitos. No exame físico, apresentava-se ansiosa,\nhipocorada (+/4+), taquicárdica (90 bm) e levemente ictérica. No que tange a esse caso clínico e\naos múltiplos aspectos a ele relacionados, julgue o item subsecutivo. Se for constatado que essa\npaciente é diabética e se ela apresentar, em um exame de imagem, um halo gasoso em torno da\nvesícula biliar, deve-se indicar cirurgia de urgência.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-212053","number":"212053","sourceNumber":"212053","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente do sexo feminino, de 37 anos de idade, faxineira, quatro filhos, foi atendida no\npronto-socorro hospitalar com índice de massa corporal de 32 e histórico de crises dispépticas e\ncólicas abdominais, localizadas em epigástrico. O quadro clínico evoluiu nas últimas 8 horas com\ndor forte e contínua no epigástrico e hipocôndrio direito, houve remissão transitória, com o uso de\nanalgésicos orais, e dois episódios de vômitos. No exame físico, apresentava-se ansiosa,\nhipocorada (+/4+), taquicárdica (90 bpm) e levemente ictérica. No que tange a esse caso clínico e\naos múltiplos aspectos a ele relacionados, julgue o item subsecutivo. A presença do sinal clínico de\nMurphy no exame físico leva ao diagnóstico de síndrome de Budd-Chiari.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-212062","number":"212062","sourceNumber":"212062","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente do sexo feminino, de 37 anos de idade, faxineira, quatro filhos, foi atendida no\npronto-socorro hospitalar com índice de massa corporal de 32 e histórico de crises dispépticas e\ncólicas abdominais, localizadas em epigástrico. O quadro clínico evoluiu nas últimas 8 horas com\ndor forte e contínua no epigástrico e hipocôndrio direito, houve remissão transitória, com o uso de\nanalgésicos orais, e dois episódios de vômitos. No exame físico, apresentava-se ansiosa,\nhipocorada (+/4+), taquicárdica (90 bpm) e levemente ictérica. No que tange a esse caso clínico e\naos múltiplos aspectos a ele relacionados, julgue o item subsecutivo. A ultrassonografia de abdome\né um exame de imagem que pode ser utilizado para o diagnóstico do caso clínico em tela.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-212069","number":"212069","sourceNumber":"212069","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente do sexo feminino, de 37 anos de idade, faxineira, quatro filhos, foi atendida no\npronto-socorro hospitalar com índice de massa corporal de 32 e histórico de crises dispépticas e\ncólicas abdominais, localizadas em epigástrico. O quadro clínico evoluiu nas últimas 8 horas com\ndor forte e contínua no epigástrico e hipocôndrio direito, houve remissão transitória, com o uso de\nanalgésicos orais, e dois episódios de vômitos. No exame físico, apresentava-se ansiosa,\nhipocorada (+/4+), taquicárdica (90 bpm) e levemente ictérica. No que tange a esse caso clínico e\naos múltiplos aspectos a ele relacionados, julgue o item subsecutivo. A ocupação da paciente\njustifica o diagnóstico de uma doença relacionada ao trabalho para o quadro clínico em questão.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-203018","number":"203018","sourceNumber":"203018","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Um paciente de 40 anos de idade, portador de Retocolite Ulcerativa (RCU) em\ntratamento adequado e regular, evolui com\nicterícia colestática, cujo laudo do US não evidenciou\nsinais de litíase biliar. A pesquisa de anticorpos antimitocondriais é negativa. A respeito desse\ncaso\nclínico, e no contexto dos pacientes portadores de RCU, qual é a hipótese diagnóstica da outra\ndoença autoimune que pode acompanhar esses pacientes?","options":{"A":"Cirrose biliar primária.","B":"Hepatite autoimune.","C":"Doença de Wilson.","D":"Hemocromatose.","E":"Colangite esclerosante."},"answer":"E","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-206096","number":"206096","sourceNumber":"206096","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Assinale a alternativa INCORRETA com relação ao câncer da vesícula biliar.","options":{"A":"É uma neoplasia agressiva que traz um prognóstico sombrio.","B":"É comum a identificação em estádio avançado.","C":"Geralmente se apresenta na quarta e quinta décadas de vida.","D":"É 2-3 vezes mais comum em mulheres que em homens."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-206107","number":"206107","sourceNumber":"206107","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Assinale a alternativa INCORRETA com relação aos pseudocistos pancreáticos:","options":{"A":"Ocorrem em 5-15% dos pacientes que tem retenção de secreções peripancreáticas após um\nepisódio de pancreatite aguda.","B":"A observação está indicada para os pacientes assintomáticos, isso porque tem sido assinalada a\nregressão espontânea em até 70% dos casos, principalmente naqueles menores que 4 cm de\ndiâmetro, localizados na cabeça e sem evidência de obstrução ou comunicação com ducto\npancreático principal.","C":"A cápsula de um pseudocisto é composta por colágeno e tecido de granulação e não é revestida\npor epitélio.","D":"A reação fibrótica exige pelo menos de quatro a oito semanas para se desenvolver."},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-206158","number":"206158","sourceNumber":"206158","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"A Hiperplasia nodular regenerativa HNR é uma condição de pequenos nódulos\nregenerativos no parênquima hepático. Sendo INCORRETO que","options":{"A":"a HNR tem sido reconhecida em pacientes infectados pelo HIV com doença hepática\ncriptogênica.","B":"apesar de a etiologia ainda ser pouco clara, o uso prolongado de didanosina-ddI e trombofilia\ntêm sido associados à doença.","C":"a Hiperplasia nodular regenerativa HNR é uma condição caracterizada por múltiplos e grandes\nnódulos degenerativos no parênquima hepático.","D":"a HNR deve ser considerada em portadores do HIV com hipertensão portal de causa inaparente,\nespecialmente naqueles que fizeram uso de didanosina-ddI."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-183872","number":"183872","sourceNumber":"183872","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"No que se refere às enfermidades gastrointestinais, julgue o item que se segue. Na\npresença de múltiplos cálculos, o empiema de vesícula biliar é a complicação mais grave da\ncolelitíase.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-177256","number":"177256","sourceNumber":"177256","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente do sexo feminino, de 83 anos de idade, com diagnóstico prévio de colelitíase\nem ecografia abdominal total, realizada há 3\nanos, procura um pronto-socorro com queixa de dor\nem abdome superior, associada a náuseas e vômitos. Refere ter tido um episódio de febre e\ntremor, além de estar com a urina escura e as fezes esbranquiçadas. Exames laboratoriais\ndemonstraram leucócitos em 24.300 com 11% de bastões, bilirrubina total em 8,2 e direta em 7,3,\nTGO, TGP, Gama-GT e FA com elevação, além de lipase e amilase normais. Considerando-se o\nreferido quadro clínico e os conhecimentos médicos relacionados a ele, é correto afirmar que a\nconduta correta para esse caso é","options":{"A":"realizar colangiopancreatografia retrógrada endoscópica (CPRE), por ser um exame diagnóstico\ne terapêutico.","B":"realizar colangiorressonância magnética, para avaliar a presença de coledocolitíase.","C":"realizar colecistectomia videolaparoscópica primeiramente.","D":"fazer o manejo clínico com NPO e sintomáticos apenas.","E":"repetir a ecografia abdominal total."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-183907","number":"183907","sourceNumber":"183907","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Julgue o próximo item, referente à colelitiase e à colecistite aguda. O exame mais\nespecífico para diagnóstico de colecistite aguda é a cintilografia hepatobiliar com ácido\niminodiacético (HIDA) marcado com tecnécio, considerando-se ainda que a confiabilidade desse\nexame é maior em pacientes com níveis séricos de bilirrubina total abaixo de 5 mg/dL.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-183909","number":"183909","sourceNumber":"183909","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Julgue o próximo item, referente à colelitiase e à colecistite aguda. A inabilidade da\nvesícula biliar para manter colesterol livre em solução na bile e para realizar movimentos de\ncontração representa papel fisiopatológico importante na formação de cálculos biliares.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-175125","number":"175125","sourceNumber":"175125","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"De acordo com o guideline do Colégio Americano de Gastroenterologia, assinale a\nalternativa INCORRETA sobre pancreatite aguda:","options":{"A":"Pseudocistos sempre requerem abordagem cirúrgica tardia.","B":"O uso de antibióticos profilático na pancreatite aguda grave não é recomendado.","C":"Nas pancreatites leves, dieta oral deve ser iniciada precocemente.","D":"A eficácia da dieta enteral via gástrica é semelhante à via jejunal."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-175130","number":"175130","sourceNumber":"175130","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"São características da Colecistite Aguda Litiásica, EXCETO:","options":{"A":"O quadro clínico é caracterizado por febre, dor em quadrante superior direito, hipersensibilidade\ne defesa à palpação.","B":"A TC de abdome com contraste é mais sensível para o diagnóstico que o ultrassom.","C":"Antibióticos de amplo espectro devem ser administrados, pensando na cobertura de\ngram-negativos, anaeróbios e gram-positivos.","D":"O preenchimento da vesícula durante a cintilografia afasta o diagnostico de colecistite."},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-159624","number":"159624","sourceNumber":"159624","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente do sexo feminino, de sessenta e três anos de idade, apresentava\nempachamento e desconforto abdominal\nsemelhante à cólica de caratér frequente e que cedia sem\nnecessidade de analgesia. Durante a investigação diagnóstica, ela foi submetida a exame\nlaboratorial e ultrassonografia abdominal total. Os resultados dos exames laboratoriais não\napresentaram anormalidades. Contudo, a ultrassonografia mostrou a presença de cisto de 4 cm de\ndiâmetro na cabeça do pâncreas. Procedeu-se, então, à realização de tomografia computadorizada\nde abdome com contraste, pela qual se identificou cisto pancreático de 4 cm de diâmetro de\nsuperfície regular, com múltiplos pequenos cistos no seu interior, espesso estroma fibroso, sem\ncomunicação com ducto pancreático principal e com calcificações esparsas próximas da periferia\ndo cisto. Considerando esse caso clínico, julgue o item que se segue. Os resultados obtidos na\ntomografia computadorizada da paciente indicam baixa possibilidade de ela ser portadora de\nneoplasia intraductal papilar mucinosa.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-159620","number":"159620","sourceNumber":"159620","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente do sexo feminino, de sessenta e três anos de idade, apresentava\nempachamento e desconforto abdominal\nsemelhante à cólica de caratér frequente e que cedia sem\nnecessidade de analgesia. Durante a investigação diagnóstica, ela foi submetida a exame\nlaboratorial e ultrassonografia abdominal total. Os resultados dos exames laboratoriais não\napresentaram anormalidades. Contudo, a ultrassonografia mostrou a presença de cisto de 4 cm de\ndiâmetro na cabeça do pâncreas. Procedeu-se, então, à realização de tomografia computadorizada\nde abdome com contraste, pela qual se identificou cisto pancreático de 4 cm de diâmetro de\nsuperfície regular, com múltiplos pequenos cistos no seu interior, espesso estroma fibroso, sem\ncomunicação com ducto pancreático principal e com calcificações esparsas próximas da periferia\ndo cisto. Considerando esse caso clínico, julgue o item que se segue. O exame adequado para\ndeterminar a malignidade do cisto pancreático é a ultrassonografia endoscópica, sendo dispensável\na análise citológica e a medida da concentração de marcadores tumorais.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-154511","number":"154511","sourceNumber":"154511","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Em paciente do sexo masculino, 50 anos de idade, portador de cirrose hepática de\netiologia alcoólica, foi identificado em tomografia computadorizada de abdome em nódulo hepático\nde 3 cm de diâmetro, hipervascularizado na fase arterial e radiolucente na fase venosa do exame.\nRealizada dosagem de alfafetoproteína sérica, com resultado de 700 ng/mL. A principal hipótese\ndiagnóstica para o nódulo hepático é:","options":{"A":"Metástase de câncer colorretal.","B":"Hepatoblastoma.","C":"Hepatocarcinoma.","D":"Adenoma hepático.","E":"Colangiocarcinoma."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-159607","number":"159607","sourceNumber":"159607","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente de cinquenta e três anos de idade, do sexo feminino, procurou ambulatório\ncom diagnóstico de pólipo de vesícula biliar,\npara avaliação pré-operatória de colecistectomia. Ela\napresentou, ainda, o resultado do exame de ultrassonografia abdominal com Doppler, que indicava\npólipo de 7 mm de diâmetro localizado na parede anterior do corpo da vesícula biliar, com fluxo\npositivo. Em relação a esse caso clínico, julgue o item subsequente. Litíase biliar, lesões\npolipoides\nde vesícula biliar, cisto de colédoco, infecções bacterianas e colangite esclerosante primária são\ncondições relacionadas com câncer de vesícula biliar.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-159608","number":"159608","sourceNumber":"159608","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente de cinquenta e três anos de idade, do sexo feminino, procurou ambulatório\ncom diagnóstico de pólipo de vesícula biliar,\npara avaliação pré-operatória de colecistectomia. Ela\napresentou, ainda, o resultado do exame de ultrassonografia abdominal com doppler, que indicava\npólipo de 7 mm de diâmetro localizado na parede anterior do corpo da vesícula biliar, com fluxo\npositivo. Em relação a esse caso clínico, julgue o item subsequente. Nesse caso, o tratamento\ncirúrgico pode ser postergado, mas a paciente deve ser submetida a acompanhamento ambulatorial\ncom ultrassonografia anual e realização de dosagem de marcadores tumorais.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-158053","number":"158053","sourceNumber":"158053","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Com relação à tríade de Charcot (dor, icterícia e febre com calafrios), assinale a\nalternativa CORRETA.","options":{"A":"Ocorre em apenas 10% dos pacientes com colangite.","B":"Significa infecção das vias biliares mas não está relacionada a infecção bacteriana.","C":"Febre e calafrios são sintomas incomuns.","D":"É sintoma sugestivo de uma entidade clínica de baixa morbimortalidade.","E":"É causada por obstrução da via biliar associada a infecção bacteriana."},"answer":"E","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-158015","number":"158015","sourceNumber":"158015","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Na avaliação prognóstica da pancreatite aguda, faz parte dos critérios de Ranson.","options":{"A":"Frequência respiratória > 25 irpm.","B":"Leucócitos > 16.000 /ml.","C":"TGP > 250 U/dL.","D":"Frequência cardíaca > 100 bpm.","E":"Pressão sistólica > 120 mmHg."},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-168497","number":"168497","sourceNumber":"168497","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Uma mulher com 26 anos de idade, obesa e multípara, com passado de dores biliares\nrecorrentes, é atendida no Pronto-Socorro, queixando-se de dor abdominal de início abrupto, de\nforte intensidade, iniciada há aproximadamente 2 horas. Refere que a dor se localiza no andar\nsuperior do abdome, irradiando-se para o dorso, tendo ainda apresentado náuseas e vômitos. Ao\nexame físico, a paciente mostra-se hipo-hidratada (+/4+) e sente dor à palpação do abdome, que\nse encontra levemente distendido e com peristalse diminuída e sinal de Murphy ausente. Os\nexames laboratoriais mostram: aumento de lipase (370 UI/L; valor de referência: 0 a 160 UI/L);\nleucócitos = 18.700/mm³ (valor de referência 6.000 a 10.000/mm³); glicose sérica = 230 mg/dL\n(valor de referência 60 a 110 mg/dL); ALT = 260 UI/L (valor de referência 0 a 35 UI/L). AST = 360\nUI/L (valor de referência 0 a 35 UI/L) e desidrogenase tática = 425 UI/L (valor de referência: 88 a\n230 UI/L). A paciente é internada na Unidade de Tratamento Intensivo, mas a despeito de ser\ntratada de forma adequada (pausa alimentar, hidratação venosa, reposição eletrolítica e analgesia\nparenteral), evolui de forma grave. Após 48 horas, a paciente apresenta piora da dor abdominal,\ntaquipneia, icterícia (2+/4+), febre elevada (39 ºC) e calafrios. Os exames complementares\nrealizados nesse dia revelam piora do leucograma, com desvio à esquerda (17% de bastões; valor\nde referência: 0 a 5 %), queda de 11% do hematócrito e aumento das escórias nitrogenadas, com\nelevação da ureia sérica de 15 mg/dL em relação ao exame feito na admissão. Uma tomografia\ncomputadorizada dinâmica de abdome revela a presença de necrose pancreática que ocupa cerca\nde 35% do parênquima e dilatação significativa das vias biliares extra-hepáticas, com presença de\ncálculo impactado no colédoco terminal. Nesse caso, o tratamento adequado e imediato para a\npaciente e instituir","options":{"A":"hidratação parenteral vigorosa, nutrição parenteral total e antibioticoterapia com\nciproflixacina e\nampicilina","B":"hidratação parenteral vigorosa, antibioticoterapia de amplo espectro e realizar colecistectomia\nde\nurgência","C":"antibioticoterapia de amplo espectro e realizar colangiopancreatografia retrógrada endoscópica\n\ncom esfincterotomia.","D":"nutrição enteral com cateter posicionado distalmente ao duodeno, antibioticoterapia e proceder a\nnecrosectomia extensa."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-129009","number":"129009","sourceNumber":"129009","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Assinale a alternativa que apresenta a melhor definição para o sinal de Blumberg.","options":{"A":"Sensibilidade dolorosa transitória em rebote na parede abdominal.","B":"Dor no ombro à inspiração.","C":"Dor provocada por elevação e extensão da perna contra resistência.","D":"Dor à inspiração enquanto se aplica pressão no abdome superior direito.","E":"Dor no ponto de McBurney quando se comprime o abdome inferior esquerdo."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-133987","number":"133987","sourceNumber":"133987","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"A respeito do divertículo de Meckel, assinale a alternativa correta.","options":{"A":"É a anomalia congênita mais comum do trato alimentar e reportada em 1% a 4% da população.","B":"Ocorre em razão do fechamento completo do ducto onfalomesentérico ou incompleto do ducto\nvitelínico durante a gestação.","C":"A maioria é sintomático.","D":"É associado à regra dos 10: fica há 10 cm da válvula ileocecal, é 10 vezes mais frequente em\nhomens, 10% são sintomáticos e aflige crianças aos 10 anos de idade.","E":"Raramente pode estar presente em saco herniário em uma hérnia inguinal encarcerada, que é\nchamada de Hérnia de Pasteur."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-133940","number":"133940","sourceNumber":"133940","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Acerca do íleo paralítico ou adinâmico, assinale a alternativa incorreta.","options":{"A":"Refere a dismotilidade do intestino na ausência de obstrução mecânica.","B":"Por definição, é considerado ausência de peristalse por 10 ou mais dias.","C":"Os sinais e sintomas podem simular obstrução intestinal.","D":"Devem ser afastados distúrbios metabólicos.","E":"É diagnóstico diferencial com brida precoce."},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-111354","number":"111354","sourceNumber":"111354","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"O achado clínico mais comumente observado nos pacientes portadores de carcinoma\nde cólon direito é:","options":{"A":"A alteração do hábito intestinal.","B":"O tenesmo.","C":"A hematoquezia.","D":"A obstrução.","E":"A anemia."},"answer":"E","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-111270","number":"111270","sourceNumber":"111270","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"A Doença de Crohn (DC) e a Retocolite Ulcerativa (RCU) são as principais doenças\ninflamatórias intestinais. São causadas pela interação de fatores genéticos, microbiota intestinal e\nimunorregulação da mucosa. Em relação à abordagem cirúrgica eletiva em pacientes que sofrem\nde RCU, são indicações, EXCETO:","options":{"A":"Atraso no crescimento em crianças.","B":"Manifestações intestinais (pioderma gangrenoso).","C":"Presença de displasia de alto grau.","D":"Presença de adenocarcinoma no segmento colorretal.","E":"Megacólon tóxico."},"answer":"E","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-80697","number":"80697","sourceNumber":"80697","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Assinale a alternativa que apresenta um fator que aumenta o risco para o\ndesenvolvimento de câncer colorretal em um paciente com retocolite ulcerativa.","options":{"A":"Gravidade da doença.","B":"Uso de drogas imunossupressoras.","C":"Extensão da doença.","D":"Uso prolongado de esteroides.","E":"Acometimento exclusivo do reto."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-97761","number":"97761","sourceNumber":"97761","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Um homem com 55 anos de idade procura Unidade Básica de Saúde (UBS)\nqueixando-se que há três meses apresenta cor\namarelada da pele e dos \"olhos\", com coceira e\nurina muito escura. Refere piora progressiva dos sintomas há cerca de 25 dias. Sente cansaço\nprogressivo, que associa a emagrecimento de 20 kg nos últimos seis meses. Eventualmente refere\ndor em mesogástrio e nas costas, que melhora com antiácidos e jejum. História pregressa de\netilismo (destilados) há mais de 30 anos. Retorna à UBS após 45 dias da primeira consulta,\n\ntrazendo ultrassonografia abdominal que evidencia dilatação de vias biliares intra e\nextra-hepáticas.\nA hipótese diagnóstica e a conduta correta são:","options":{"A":"Hepatite alcoólica e realização de biópsia hepática transparietal.","B":"Adenocarcinoma de pâncreas e realização de colangiorressonância magnética.","C":"Adenocarcinoma de pâncreas e realização de tomografia abdominal contrastada.","D":"Pancreatite aguda e realização de colangiopancreatografia endoscópica retrógrada."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-97782","number":"97782","sourceNumber":"97782","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Um homem com 35 anos de idade, etilista há 20 anos, procura a Unidade Básica de\nSaúde com queixa de dor moderada em\nhipocôndrio direito, febre não aferida, calafrios há 15 dias.\nAo exame físico apresenta temperatura axilar de 38°C, fígado aumentado e dor à palpação\nabdominal em hipocôndrio direito. Uma imagem da ultrassonografia abdominal é mostrada abaixo.\n(VER IMAGEM). O diagnóstico CORRETO e o próximo passo na conduta em relação a esse\npaciente são:","options":{"A":"Cirrose alcoólica; o paciente deve ser encaminhado para serviço de transplante hepático.","B":"Litíases intra-hepáticas; o paciente deve ser encaminhado para drenagem transparieto-hepática.","C":"Hepatite alcoólica; o paciente deve ser encaminhado para desintoxicação e tratamento\npsiquiátrico.","D":"Abscesso hepático; o paciente deve ser encaminhado para drenagem do abscesso o mais\nrapidamente possível."},"answer":"D","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":["question_bank/media/medcurso/medcurso-gastrologia-gas-3/97782.png"],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-97808","number":"97808","sourceNumber":"97808","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Em uma consulta regular na unidade básica de saúde, uma adolescente, com 16 anos\nde idade e diagnóstico de anemia falciforme,\nrefere que tem apresentado crises de dor tipo cólica\nlocalizada em hipocôndrio direito, que se acentua após a alimentação e melhora com o uso de\nhioscina por via oral. Nega outros sintomas. São achados relevantes ao exame físico: paciente\nlevemente hipocorada, apresentando dor à palpação profunda de hipocôndrio direito. O exame\nindicado para o esclarecimento da causa da dor nessa paciente é:","options":{"A":"Laparoscopia diagnóstica, pois trata-se de endometriose, comum em anemia falciforme.","B":"Ultrassom de abdome superior, pois trata-se de cólica biliar por colelitíase, comum na anemia\nfalciforme.","C":"Hemograma, pois trata-se de crise de falcização com dor localizada em hipocôndrio direito por\ntrombose de artéria hepática.","D":"Tomografia de abdome superior, para avaliação de esplenomegalia e também investigação de\ncolelitíase, ambos comuns na anemia falciforme."},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-97855","number":"97855","sourceNumber":"97855","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Uma mulher, com 76 anos de idade, apresenta antecedentes de hipertensão arterial,\ndislipidemia e obesidade, e faz uso de\nenalapril -20 mg/dia e sinvastatina -20 mg/dia. A paciente\ndeu entrada no Pronto-Socorro com quadro de dor abdominal de início súbito há cerca de sete\nhoras, de forte intensidade, em região epigástrica, com irradiação para o dorso, sem relação com a\nalimentação e acompanhada por náuseas e vômitos. Refere haver leve melhora da dor com\ninclinação do corpo para frente. Na admissão hospitalar estava consciente, orientada, anictérica,\ncom palidez cutâneo-mucosa. Temperatura axilar = 36 °C, pressão arterial = 100 x 60 mmHg,\nfrequência cardíaca = 105 bpm, frequência respiratória = 18 irpm, índice de massa corporal = 34,2\nkg/m² (valor de referência = até 30 kg/m²). As auscultas cardíacas e pulmonar não demonstram\nalterações. Abdome obeso, muito doloroso à palpação superficial e profunda em epigástrio, sem\nmassas ou organomegalias palpáveis. Ruídos hidroaéreos ausentes . Não havia edema de\nmembros inferiores. Os exames laboratoriais iniciais revelaram: Leucócitos = 14.500/mm³ (Valor de\nreferência: 4.500 a 11.000/mm³), com 84% de segmentados, 0% de eosinófilos, 10% de linfócitos);\nhemoglobina = 13,0 g/dl ( Valor de referência 12-16 g/dl); hematócritos = 39% (Valor de referência:\n36% - 46%); plaquetas = 231.000/mm³ (Valor de referência: 150.000 - 350.000/mm³); glicemia =\n106 mg/dl (Valor de referência: 80 - 100/mg/dl); ureia = 70 mg/dl(Valor de referência: 20 -\n35/mg/dl);\nCreatinina = 1,2 mg/dl (Valor de referência: 0,8 - 1,2 mg/dl); amilase = 2560 U/L (Valor de\nreferência: 4 - 400 U/L); AST = 26 U/L (Valor de referência: < 35 U/L); ALT = 31 U/L (Valor de\nreferência: < 35 U/L); bilirrubina total = 1,5 mg/dl (Valor de referência: 0,3 - 1,2 mg/dl);\nbilirrubina\ndireta = 0,4 mg/dl (Valor de referência: < 0,2 mg/dl); bilirrubina indireta = 0,8 mg/dl (Valor de\nreferência: < 1,0 mg/dl); LDH = 200 U/L (Valor de referência: 135-214 U/L). Considerando o\ndiagnóstico da paciente, assinale a alternativa que contém critérios clínicos e/ou laboratoriais de\nmaior gravidade e pior prognóstico que sugerem a necessidade de internação em Unidade de\nTratamento Intensivo.","options":{"A":"Obesidade e elevação da ureia.","B":"Taquicardia e elevação da amilase.","C":"Sexo feminino e elevação das bilirrubinas.","D":"Dor abdominal intensa e elevação da glicemia."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-75460","number":"75460","sourceNumber":"75460","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Mulher com 38 anos de idade procurou o Serviço de Urgência referindo há 1 dia a\nocorrência de dor abdominal intensa em andar superior do abdome, acompanhada de vômitos\n\npós-alimentares. Ao exame físico encontrava-se com hálito etílico, dor difusa à palpação abdominal,\ncom descompressão brusca positiva. Sobre a\ninvestigação diagnóstica dessa paciente, é correto\nafirmar que:","options":{"A":"a dosagem de amilase sérica normal afasta o diagnóstico de pancreatite.","B":"a radiografia de tórax auxilia na investigação de\ndoença ulcerosa péptica complicada.","C":"a ultrassonografia abdominal é o exame de escolha para a investigação de pancreatite.","D":"o diagnóstico de hepatite alcoólica pode ser afastado devido à presença de descompressão\nbrusca positiva.","E":"deve ser realizada laparotomia exploratória com\nurgência, pois a paciente está com sinais de abdome agudo."},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-75467","number":"75467","sourceNumber":"75467","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Homem com 45 anos de idade, obeso, procura consulta médica por apresentar\nepisódios de cólica em hipocôndrio direito há\nseis meses. Trouxe consigo um resultado de\nultrassonografia que mostra múltiplos pequenos cálculos em vesícula biliar sem outros achados\nanormais. O paciente inicia a consulta dizendo que não quer realizar cirurgia. Qual a melhor\norientação para esse paciente?","options":{"A":"Iniciar tratamento sintomático, prescrever\nmedicamentos e dieta para perda ponderal, realizando\nreavaliação em seis meses.","B":"Agendar data para realização de cirurgia por\n\nvideolaparoscopia pela faixa etária do paciente e pelos riscos caso não se submeta à cirurgia.","C":"Esclarecer sobre o diagnóstico, a indicação cirúrgica e o risco de complicações caso não se\nsubmeta à\n\ncirurgia.","D":"Solicitar uma ressonância de abdome superior e\n\norientar para tomar medicamentos sintomáticos com continuação de acompanhamento\nambulatorial.","E":"Encaminhar para psiquiatra a fim de descartar\nsíndrome do pânico e prescrever medicamentos\nsintomáticos até o paciente decidir submeter-se à\ncirurgia."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-137544","number":"137544","sourceNumber":"137544","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Uma mulher de 40 anos de idade, branca, casada, procura o Serviço de Emergência\nqueixando-se de dor abdominal epigástrica em todo o hemi-abdome superior, intensa, contínua,\ncom irradiação para o dorso e acompanhada de náuseas e vômitos há 24 horas. Não refere história\nde doença pregressa, etilismo, tabagismo e uso de medicamentos. Informa ter 4 filhos. Ao exame\nfísico apresenta-se desconfortável no leito. Encontra-se afebril, com FC = 110 bpm,\n\nPA = 100 x 60 mmHg, pele com discreta sudorese, mucosas coradas e escleróticas ictéricas 1+/4+.\nAo exame do abdome observam-se ruídos\nhidroaéreos presentes; abdome flácido,\n\ncom dor à palpação no hemi-abdome superior e ausência de visceromegalias. Os exames\nlaboratoriais mostram: hemograma com 15 400 leucócitos/mm³ (valores de referência\n\n3 = 3 800 a 10 600/mm ) com neutrofilia; glicose = 130 mg/dL (valor de referência = 99 mg/dL);\namilase = 1 240 U/L (valor de referência =\n30 a 225 U/L); lipase = 600 U/L (valor de referência = 3 a\n43 U/L), bilirrubinas totais = 5,2 mg/dL (valor de referência < 1,3 mg/dL), com fração direta de 2,0\nmg/dL (valor de referência < 0,4 mg/dL); alanino-amino-transferase = 162 UI/L (valor de referência\n\n= < 35 UI/L); aspartato-aminotransferase = 87 UI/L (valor de referência < 30 UI/L). A\n\nradiografia simples de abdome mostra padrão inespecífico de distribuição de gases, sem vidência\nde pneumoperitônio. Diante do quadro apresentado, a\nprincipal hipótese diagnóstica é","options":{"A":"cólica biliar.","B":"pancreatite biliar.","C":"obstrução intestinal.","D":"isquemia mesentérica.","E":"úlcera gástrica perfurada"},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-137536","number":"137536","sourceNumber":"137536","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Uma mulher de 57 anos de idade, portadora de litíase biliar diagnosticada há 12\nanos por ultrassonografia abdominal, tem\nantecedentes de três episódios sugestivos de colecistite\naguda tratados clinicamente. Não tem outras comorbidades. Submetida à ultrassonografia\nabdominal há cerca de duas semanas, em decorrência de novo quadro de dor abdominal\nem cólica, o exame mostrou, além de vários cálculos pequenos no interior da vesícula, placas\nopacificando os contornos da parede, sugerindo \"vesícula em porcelana\". Qual a conduta\nmais indicada nesse caso?","options":{"A":"Litotripsia extracorpórea.","B":"Tratamento cirúrgico.","C":"Emprego do ácido ursodesoxicólico.","D":"Colangioressonância.","E":"Mudanças de dieta e analgésicos sob demanda."},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-137532","number":"137532","sourceNumber":"137532","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Um homem de 47 anos de idade é internado para investigação de icterícia e prurido\nque se iniciou há 3 semanas. Nega doenças\nanteriores, perda de peso ou qualquer outra queixa. É\netilista crônico (3 a 5 doses de bebida alcoólica destilada/dia há 30 anos). Ao exame físico,\nencontra-se em bom estado geral. Apresenta icterícia de escleras; o restante do exame físico é\nnormal. A ultrassonografia do abdome revelou dilatação de vias biliares intra e extra-hepáticas. A\nvesícula está dilatada e não foram identificados cálculos em seu interior. Considerando a relação\ncusto-efetividade, qual o exame complementar que deve ser solicitado na sequência da\nultrassonografia com vista ao diagnóstico do caso?","options":{"A":"Dosagem de CA19 - 9 sérico.","B":"Tomografia computadorizada contrastada do abdome.","C":"Ressonância magnética do abdome.","D":"Laparoscopia diagnóstica do abdome.","E":"Colangiopancreatografia retrógrada endoscópica."},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-137597","number":"137597","sourceNumber":"137597","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Uma mulher de 45 anos de idade foi admitida na Unidade de Emergência com febre,\ndor no hipocôndrio D e vômitos há 48 horas.\nApresenta piora progressiva do quadro e, no\nmomento, encontra-se sonolenta, confusa, com facies de sofrimento, desidratada (+++/4+) e\nictérica (++/4+), com extremidades frias, pulsos finos, sem cianose. Sinais vitais: T = 39°C, FC =\n130 bpm, FR = 35 irpm, PA = 110 x 60 mmHg. Ausculta cardíaca e pulmonar sem alterações.\n\nAbdome com distensão abdominal moderada, dor à palpação superficial do epigástrio e hipocôndrio\nD, sem sinais de irritação peritoneal, com\nruídos hidroaéreos reduzidos. Exames complementares:\nhematócrito = 36% (valor de referência: 42± 6%), hemoglobina = 12,3 g/dL (valor de referência:\n13,82 ± 2,5 g /dL), leucócitos = 18.200 /mm3 (valor de referência: 3.800 a10.600/mm3 ) com 17%\nde bastões, Proteína C Reativa = 8,3 mg/dL (valor de referência = 0,3 a 0,5 mg/dL), bilirrubina\ntotal\n\n= 5,2 mg/dL (valor de referência = até 1,2 mg/dL), bilirrubina direta = 4,1 mg /dL (valor de\nreferência\n\n= até 0,4 mg /dL), glicemia = 300 mg /dL (valor de referência < 99 mg /dL). Ultrassonografia\nabdominal: ausência de líquido livre em cavidade\nperitoneal, distensão de alças que prejudica a\ntécnica do exame, vias biliares dilatadas. Além da reposição volêmica, qual a conduta inicial\nrequerida para o caso?","options":{"A":"Laparotomia exploradora.","B":"Colecistectomia videolaparoscópica.","C":"Antibioticoterapia de amplo espectro.","D":"Drenagem percutânea de vias biliopancreáticas.","E":"Colangiografia endoscópica retrógrada com papilotomia."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-138385","number":"138385","sourceNumber":"138385","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Um homem de 50 anos de idade é hospitalizado por apresentar quadro de dor em\nhipocôndrio direito, de moderada intensidade, com períodos de acalmia. A dor é acompanhada de\nfebre, náuseas e vômitos, iniciados 24 horas antes da internação. Ao exame físico, apresenta dor à\npalpação do hipocôndrio direito, com sinal de Murphy positivo. Os exames laboratoriais revelaram\n13000 leucócitos/mm³ (valor de referência = 3800 a 10600/mm³ ), discreta elevação das\ntransaminases e da amilase sérica. O paciente foi submetido a colecistectomia laparoscópica, sem\ncolangiografia. No segundo dia de pós-operatório, o achado de icterícia com elevação de\nbilirrubina, sem sinais de peritonismo e sem febre tem como diagnóstico mais provável","options":{"A":"colangite bacteriana aguda.","B":"coledocolitíase.","C":"fístula de coto de ducto cístico.","D":"ligadura inadvertida do ducto hepático direito.","E":"lesão iatrogênica do ducto comum."},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-138394","number":"138394","sourceNumber":"138394","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Mulher com 54 anos de idade, Índice de Massa Corpórea (IMC) = 32,6, portadora de\ndiabetes tipo 2, controlado com medidas dietéticas e uso de glibenclamida, comparece à Unidade\nBásica de Saúde com queixa de dor, do tipo cólica, em hipocôndrio direito, que se irradia para o\nombro direito e piora após ingestão de alimentos, especialmente gordurosos. Relata episódios de\nvômitos durante algumas crises. Disse, ainda, que o quadro iniciou-se há mais ou menos seis\nmeses, agravando-se no último mês. Após a realização do exame físico, o médico solicitou\nultrassonografia de abdome que evidenciou ?colecistopatia calculosa crônica?. Ao explicar o\ndiagnóstico para a paciente, ela informou que gostaria de passar seis meses visitando a filha que\nmora em Portugal. Baseado nessa situação, você diria à paciente que seu quadro clínico","options":{"A":"é crônico e o tratamento cirúrgico pode ser adiado.","B":"requer tratamento cirúrgico antes da viagem.","C":"requer tratamento cirúrgico imediato.","D":"requer acompanhamento imediato quando\naparecerem indícios de complicações","E":"requer antibioticoterapia imediata e uso de\nantiespasmódicos."},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-138560","number":"138560","sourceNumber":"138560","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Uma mulher, com 36 anos de idade, casada, procura a Unidade de Pronto Atendimento\ncom dor tipo cólica, intensa e constante há\ntrês dias, náuseas, vômitos, tendo feito várias\naplicações de analgésicos parenterais. Há cerca de seis meses, vem apresentando crises de dor\nabdominal semelhantes, porém de intensidade menor em hipocôndrio direito com irradiação para o\ndorso, do tipo cólica, predominantemente noturnas e após a ingestão de alimentos gordurosos. No\nmomento, ela está com temperatura de 38,1°C, com fácies de dor, taquicárdica, com dor intensa à\npalpação do hipocôndrio direito e com a presença de sinal de Murphy. Com base nessas\ninformações, a conduta mais adequada é","options":{"A":"administrar novamente analgésicos, com alta e orientação para procurar ambulatório de cirurgia\npara programar colecistectomia eletiva.","B":"administrar analgésicos e antibióticos, com alta e orientação para procurar ambulatório de\ncirurgia para programar colecistectomia eletiva.","C":"administrar analgésicos, com internação hospitalar\naté melhora da dor e alta para programar\ncolecistectomia eletiva.","D":"administrar analgésicos e antibióticos, com internação hospitalar até ?esfriar o processo?\nseguida de alta para programar colecistectomia.","E":"administrar analgésicos e antibióticos, com internação hospitalar e programar colecistectomia."},"answer":"E","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-138594","number":"138594","sourceNumber":"138594","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Mulher, com 44 anos de idade, apresenta quadro de dor epigástrica, com irradiação em\nfaixa para hipocôndrio direito e esquerdo, com vômitos e distensão abdominal, de início súbito sem\nrelação com esforço, ocorrendo há seis horas. Relata dois episódios semelhantes anteriores, de\nmenor intensidade, nos últimos três anos, dos quais se recuperou apenas com restrição de dieta.\n\nRelata ainda trombose de retina à esquerda após um desses episódios. Durante o exame físico,\nforam visualizadas mucosas descoradas, anictérica, pele com turgor e elasticidade reduzidos.\n\nPressão arterial = 40x90 mmHg. Pulso radial = 120 bpm, rítmico e fino. Ausculta respiratória -\nexpansibilidade reduzida em base de hemitórax esquerdo, com submacicez local. Ausculta\ncardíaca - bulhas taquicárdicas em dois tempos. Abdome distendido, com equimoses nos flancos.\nRuídos hidroaéreos diminuídos e dor difusa à palpação. Extremidades: pulsos periféricos palpáveis\ne simétricos. Exame laboratoriais mostram Ht = 52%, Hb = 14 g/L. Amilase = 104 U/L (Valor normal\n\n= 27 a 131U/L). Glicemia na admissão = 230 mg/dL. Creatinina = 1,5 mg/ dL (Valor normal = 0,7 a\n1,3 mg/dL). Troponina Sérica = 0,5 ng/mL (Valor normal < 0,1 ng/mL). ECG sem alterações. O\nlaboratório informa que o soro apresenta aspecto francamente leitoso na centrifugação.\n\nUltrassonografia de abdome mostra vias biliares não dilatadas e vesícula biliar de paredes finas,\nsem cálculos. O retroperitôneo não foi visualizado. Qual o diagnóstico compatível com o quadro\ndescrito?","options":{"A":"Pancreatite aguda.","B":"Dissecção de aorta.","C":"Infarto do miocárdio.","D":"Colecistite aguda.","E":"Infarto mesentérico."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-359200","number":"359200","sourceNumber":"359200","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"O tratamento cirúrgico do cisto de colédoco do tipo I deverá ser,\nPREFERENCIALMENTE, feito por:","options":{"A":"Ressecção completa e hepaticojejunostomia em Y de Roux.","B":"Ressecção completa e hepaticoduodenostomia.","C":"Cistoenterostomia em Y de Roux.","D":"Portoenterostomia em reconstrução intestinal em Y de Roux."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-359206","number":"359206","sourceNumber":"359206","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"A pancreatite aguda é um processo inflamatório agudo do pâncreas, de etiologia\ndiversa, caracterizada por:","options":{"A":"Resposta inflamatória sistêmica, que requer antibioticoterapia intravenosa, sob regime de\ninternação.","B":"Início súbito dos sintomas, que tendem a se resolver espontaneamente após alguns dias do\ninício do quadro.","C":"Dor crônica e sintomas diversos, cujo diagnóstico requer exames por imagem para confirmação\nda inflamação.","D":"Deterioração clínica, em geral, de 7 dias a 10 dias do início da internação."},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-352194","number":"352194","sourceNumber":"352194","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente feminina, 67 anos, deu entrada no Pronto Socorro com perda ponderal\niniciada há 4 meses, associada a icterícia,\ndor abdominal em hipocôndrio direito, colúria e acolia\nfecal nos últimos 7 dias. Apresentava-se emagrecida, com temperatura axilar de 38°C, mucosas\nhipocoradas, icterícia 3+/3+, pressão arterial de 92/54 mmHg, frequência cardíaca de 106 bpm,\nabdome flácido, vesícula biliar distendida, palpável e indolor, fígado palpável com bordos\nirregulares. Foram solicitados exames laboratoriais que mostraram hemoglobina: 9,2 g/dL,\nleucócitos: 2.750/mm³, plaquetas: 85.000/mm³, creatinina: 2,4mg/dL, bilirrubina total: 16,3mg/dL.\nUltrassom do abdome: vesícula biliar distendida, paredes finas, sem cálculos no interior; dilatação\ndas vias biliares intra e extra-hepáticas, sem identificação de fatores obstrutivos. Sobre o caso,\npodemos afirmar que:","options":{"A":"A colangiorressonância é um exame fundamental para definir a conduta inicial na unidade de\nemergência.","B":"De acordo com os dados apresentados, a causa mais provável é a presença de cálculos no\ncolédoco.","C":"De acordo com a classificação de gravidade, esta paciente deve ser submetida a drenagem\nbiliar o mais precocemente possível.","D":"O início da antibioticoterapia deve ser postergado até confirmação do fator etiológico."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-368190","number":"368190","sourceNumber":"368190","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Assinale a alternativa que apresenta os critérios para o diagnóstico de colangite.","options":{"A":"Inflamação sistêmica (leucocitose e / ou aumento de proteína C-reativa (PCR), função renal\nalterada com creatinina duas vezes o valor basal e imagem detectando dilatação de vias biliares.","B":"Inflamação sistêmica (leucocitose e / ou aumento de PCR), exames hepáticos anormais\n(fosfatase alcalina, gama GT, TGO/P) e imagem\ndetectando a presença de ar nas vias biliares.","C":"Inflamação sistêmica (leucocitose e / ou aumento de PCR), exames hepáticos anormais\n(fosfatase alcalina, gama GT, TGO/P) e imagem detectando dilatação de vias biliares.","D":"Inflamação sistêmica (leucocitose e / ou aumento de PCR), exames hepáticos anormais\n(fosfatase alcalina, gama GT, TGO/P) e a\nidentificação de cálculo obstrutivo em vias biliares à\ncolangiorressonância."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-368191","number":"368191","sourceNumber":"368191","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"As principais complicações com indicação de cirurgia da pancreatite crônica são","options":{"A":"formação de pseudocisto, sangramento e associação com adenocarcinoma de pâncreas.","B":"icterícia por obstrução do colédoco intrapancreático, pseudocistos e derrames cavitários e\nperfuração de alças intestinais, principalmente o cólon.","C":"sangramento, icterícia por obstrução do colédoco intrapancreático e diabete melito.","D":"icterícia por obstrução do colédoco intrapancreático, pseudocistos e derrames cavitários e\nobstrução da luz duodenal."},"answer":"D","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-368195","number":"368195","sourceNumber":"368195","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Um paciente com queixa de dor à palpação do quadrante superior direito, com a\npresença de defesa muscular involuntária, apresenta o achado de gás na vesícula biliar em\nradiografia de abdome. Nesse caso, o diagnóstico é de","options":{"A":"cólica biliar.","B":"colecistite enfisematosa.","C":"peritonite difusa.","D":"vesícula hidrópica."},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-351588","number":"351588","sourceNumber":"351588","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Marque a opção CORRETA. Durante uma colecistectomia considerada difícil, com\ngangrena de vesícula, a opção da realização de colecistectomia à Torek significa:","options":{"A":"Colecistectomia parcial, deixando-se a parede posterior aderida ao fígado, com cauterização da\nmesma e drenagem da cavidade.","B":"Colecistectomia fundo-cística e drenagem da cavidade.","C":"Punção esvaziadora, colecistectomia fundo- cística e sutura do infundíbulo vesicular com\ndrenagem da cavidade.","D":"Colecistectomia com coledocoplastia e drenagem em tubo T da via biliar."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-368164","number":"368164","sourceNumber":"368164","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente de 48 anos de idade, tabagista, uso habitual de bebidas alcoólicas, queixa-se\nde náuseas e dor abdominal tipo cólica em faixa\nsuperior, que irradia para o dorso. Ao exame físico,\napresenta icterícia leve. São solicitados estes exames de sangue: I. Amilase; II. Lipase; III.\nBilirrubina indireta; IV. Bilirrubina direta; V. Albumina. Os resultados laboratoriais esperados\nnesse\ncaso são elevação nos índices de","options":{"A":"I, II, III, apenas.","B":"III, IV e V, apenas.","C":"I, II e IV, apenas.","D":"I, II, III, IV e V."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-354096","number":"354096","sourceNumber":"354096","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente, 44 anos, com quadro de dor em hipocôndrio direito recorrente associado a\nnáuseas e vômitos. Submetida a\nultrassonografia abdominal com evidências de vesícula biliar de\nparedes de 1mm, com imagens hiperecogênicas em seu interior e sombra acústica posterior e\ncolédoco de 1,2 cm de diâmetro e com imagens hiperecogênicas e sombra acústica posterior. Qual\na melhor abordagem terapêutica para a paciente?","options":{"A":"Colecistectomia Videolaparoscópica com exploração de via biliar e anastomose entre\nhepático-jejunal em Y de Roux.","B":"Colecistectomia aberta com exploração de vias biliares e colocação de dreno de Kher.","C":"Colangiopancreatografia retrógrada (CPRE) seguido de Colecistectomia Videolaparoscópica.","D":"Colecistectomia Videolaparoscópica seguida de Colangiopancreatografia retrógrada (CPRE).","E":"Colecistectomia Videolaparoscópica com exploração de vias biliares."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-337616","number":"337616","sourceNumber":"337616","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Mulher, 45 anos, portadora de hipertensão arterial sistêmica, deu entrada no Pronto\nAtendimento com dor abdominal difusa e vômitos. No exame físico: corada, desidratada ++/4,\ndispneica +/4, febril, ictérica ++/4, acianótica, dor abdominal difusa no abdome, descompressão\nbrusca ausente. Realizados exames laboratoriais mostrando hemograma mostrava leucocitose de\n16.000, ionograma normal, amilase de 890mgr/dl, ALT de 120, AST de 134, Glicemia de 140mgr/dl,\nbilirrubina total de 3,8 com 2,8 de direta e 1,0 de indireta. Ultrassom revela cálculos na vesícula\ne\ndilatação de vias biliares intra e extra-hepática, com imagem suspeita de cálculo em colédoco\ndistal. Considerando o caso descrito, assinale a alternativa que apresenta a MELHOR conduta para\nessa paciente.","options":{"A":"Iniciar tratamento clínico e após 24 horas colecistectomia laparoscópica com coledocotomia\nemergencial.","B":"Iniciar antibioticoterapia, fazer a TC de abdome e após melhora realizar a colecistectomia com\ncerca de 2 meses de intervalo.","C":"Realizar tratamento clínico inicial, indicar a colangiopancreatoregrafia retrograda e a seguir\ncolecistectomia.","D":"Iniciar antibióticos por se trata de uma pancreatite grave, com RANSOM acima de 3 pontos, e\navaliar critérios de Balthazar pela TC de abdome na admissão."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-345699","number":"345699","sourceNumber":"345699","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"O diagnóstico do carcinoma hepatocelular (CHC) deve ser realizado:","options":{"A":"Preferencialmente, por exames de imagem invasivos, tais como a ultrassonografia (US),\ntomografia computadorizada (TC) ou ressonância\nmagnética (RM), as quais também podem ser\nutilizadas para o estadiamento.","B":"Preferencialmente, por exames de imagem não invasivos, tais como a ultrassonografia (US),\ntomografia computadorizada (TC) ou ressonância magnética (RM), as quais não podem ser\nutilizadas para o estadiamento.","C":"Preferencialmente, por exames de imagem não invasivos, tais como a ultrassonografia (US),\ntomografia computadorizada (TC), mas nunca pela ressonância magnética (RM), as quais também\nsomente podem ser utilizadas para o estadiamento.","D":"Preferencialmente, por exames de imagem não invasivos, tais como a ultrassonografia (US),\ntomografia computadorizada (TC) ou ressonância magnética (RM), as quais também podem ser\nutilizadas para o estadiamento."},"answer":"D","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-336258","number":"336258","sourceNumber":"336258","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Mulher, 40 anos, dá entrada ao PS com dor em hipocôndrio direito há 5 dias, intensa,\nassociada a náuseas, vômitos e calafrios. Relato por familiares de urina de coloração escurecida,\ncom forte odor. Exame físico: letárgica, desorientada, pálida, desidratada, ictérica 3+/4+, TAX\n38,9°C, FC: 120bpm; FR: 28 irpm, PA: 80x30mmHg. Abdome doloroso à palpação em região logo\nabaixo do rebordo costal direito. Abdome doloroso difusamente, plastrão palpável em hipocôndrio\ndireito, ruídos hidroaéreos não audíveis. Trouxe ultrassonografia de abdome total realizado há 3\nmeses com múltiplos cálculos em vesícula, paredes finas e sem dilatação da árvore biliar ao\nmétodo. A principal hipótese diagnóstica e terapêutica, são:","options":{"A":"Coledocolitíase: prescrever antibioticoprofilaxia para evitar translocação bacteriana, solicitar\ncolangiopancreatografia retrógrada endoscópica (CPRE).","B":"Colecistite: realizar colecistectomia após estabilização clínica.","C":"Colangite: internação em UTI e drenagem de via biliar.","D":"Sepse urinária: internação com antibioticoterapia venosa."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-337622","number":"337622","sourceNumber":"337622","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Homem de 40 anos, portador de drepanocitose foi submetido a colecistectomia\nlaparoscópica para colecistite aguda. Na\ncirurgia, vesícula bem inflamada e houve avulsão da\nartéria cística durante a dissecção do triângulo de Calot. Foi necessário transfusão de 600ml de\npapa de hemácias, a fim de manter estabilidade hemodinâmica. Recebeu alta hospitalar após 7\ndias de internação. Após cerca de 45 dias o paciente retorna ao hospital com icterícia, tendo\nbilirrubinas totais de 8mg/dl, sendo 4,8mg/dl às custas de direta, associado à elevação da fosfatase\nalcalina e ultrassom com colédoco de 8mm. Considerando o caso descrito, assinale a alternativa\nque apresenta o diagnóstico MAIS provável para esse paciente.","options":{"A":"Icterícia hemolítica devido à transfusão prévia.","B":"Crise falciforme.","C":"Icterícia devido obstrução iatrogênica de via biliar principal.","D":"Hepatite transmitida pela transfusão."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-345704","number":"345704","sourceNumber":"345704","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"O diagnóstico anatomopatológico do carcinoma hepatocelular (CHC):","options":{"A":"Deve ser vetado para pacientes não cirróticos e para aquelas situações em que os exames de\nimagem sejam inconclusivos.","B":"Deve ser reservado para pacientes não cirróticos e para aquelas situações em que os exames\nde imagem sejam inconclusivos.","C":"Deve ser reservado para pacientes não cirróticos e não para aquelas situações em que os\nexames de imagem sejam inconclusivos.","D":"Deve ser reservado para pacientes não cirróticos e para aquelas situações em que os exames\nde imagem sejam conclusivos."},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-335076","number":"335076","sourceNumber":"335076","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Um paciente com pancreatite aguda deteriora clinicamente e é submetido à aquisição\nde novas imagens. O exame de tomografia\ncomputadorizada revela achados de uma coleção\nlíquida consistente, com uma necrose pancreática infectada, que está aderida à parede gástrica\nposterior e próxima da cabeça pancreática. Nesse caso, o melhor tratamento é","options":{"A":"drenagem endoscópica.","B":"cistogastrostomia.","C":"cistojejunostomia Y de Roux.","D":"drenagem percutânea."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-346863","number":"346863","sourceNumber":"346863","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Um paciente portador de anastomose bileodigestiva, realizada para tratamento de lesão\niatrogênica da via biliar, evolui com estenose da anastomose e episódios repetidos de febre com\ncalafrios. Há uma semana também passou a apresentar icterícia e foi internado com quadro de\ncolangite aguda grave. Nesse caso, é CORRETO afirmar que o tratamento completo desse\npaciente deve ser realizado com:","options":{"A":"Antibioticoterapia com cobertura para gram-negativos, enterococos e anaeróbios e desobstrução\nbiliar.","B":"Antibioticoterapia com cobertura para gram-negativos, enterococos e anaeróbios.","C":"Antibioticoterapia com cobertura para gram-negativos e enterococos.","D":"Antibioticoterapia de amplo espectro."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-320448","number":"320448","sourceNumber":"320448","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Homem diabético em uso irregular das medicações, obeso, 45 anos, se apresenta ao\nhospital com dor mesogástrica crescente com irradiação para o dorso, associada a náuseas. Nega\nuso de álcool. Ao exame físico FC: 110 BPM, restante dos sinais vitais normais; abdome\ndiscretamente distendido e doloroso a palpação em região mesogástrica, sem irritação peritoneal,\nruídos hidroaéreos reduzidos. Laboratorio: amilase 420 U/I (VR < 132 U/L); lipase 1.800 (VR < 52\nU/L). USG de abdome: infiltração gordurosa do fígado, vesícula biliar normal, vias biliares sem\ndilatação, pâncreas discretamente aumentado de tamanho com presença de pequena quantidade\nde líquido peripancreatico. Qual das opções abaixo é a etologia mais provável para a pancreatite\ndesse paciente?","options":{"A":"Medicamentoso.","B":"Pancreas divisium.","C":"Auto-imune.","D":"Biliar.","E":"Hipertrigliceridemia."},"answer":"E","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-320461","number":"320461","sourceNumber":"320461","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Uma mulher de 47 anos, procura o pronto socorro com queixa de dor intensa em\nhipocôndrio direito há 72 horas, náuseas,\nvômitos e sensação de febre. Ao exame físico, apresenta\ndor a palpação em hipocôndrio direito, com interrupção da inspiração. FC: 80 bpm e PA: 120x80\nmmHg. O ultrassom de abdômen evidencia espessamento da parede da vesícula biliar, com líquido\nperi-vesicular. Possui amilase de 110 U/L e leucócitos de 19.000/mm3. Segundo o guideline de\nTókio de 2018, podemos afirmar que se trata de uma colecistite aguda:","options":{"A":"Leve, Grau I.","B":"Moderada, Grau II.","C":"Severa, Grau IV.","D":"Severa, Grau I.","E":"Severa, Grau III."},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-313289","number":"313289","sourceNumber":"313289","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Na realização da Colecistectomia aberta, após realizar a incisão da serosa da vesícula\na 0,5 cm da borda do leito hepático, o\ncirurgião deverá realizar o seguinte procedimento:","options":{"A":"Ligadura com fio de seda (duas ligaduras proximais e uma distal), com reparo dos fios entre\npinças, e secção da artéria Cística ao nível do infundíbulo da vesícula (saco de Hartmann); após\nrevisão, os fios reparados são seccionados.","B":"Dissecção fundocística da serosa da vesícula. Neste momento, é importante manter a dissecção\no mais próxima possível da vesícula biliar,\npara evitar lesão hepática e subsequente sangramento.","C":"Tração do fundo da vesícula (na bolsa de Hartman), clampeando área puncionada, com pinça\nde Foerster (em anel), expondo o ligamento hepatoduodenal (pedículo hepático).","D":"Ligadura (duas ligaduras proximais e uma distal) e secção do ducto cístico entre os nós.","E":"Cauterização do leito hepático e peritonização do ligamento hepatoduodenal, ?sepultando? o\ncoto do ducto cístico."},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-291948","number":"291948","sourceNumber":"291948","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente de 35 anos sem comorbidades, admitida com colecistite aguda calculosa\nconfirmada ao ultrassom e icterícia leve,\nbilirrubina total de 3,5mgr/dl. Foi iniciado antibioticoterapia,\nhouve melhora clínica. Nesse contexto, é CORRETO afirmar que a conduta mais adequada\nanalisando o custo-benefício do paciente deve ser de:","options":{"A":"Indicar uma Colangiopancreatografia Retrógrada Endoscópica (CPRE) por suspeita alta de\ncoledocolitíase.","B":"Manter a antibioticoterapia e adotar tratamento clínico para posterior reavaliação e cirurgia em\num segundo tempo.","C":"Indicar colecistectomia vídeo laparoscópica com colangiografia per-operatória.","D":"Fazer uma tomografia de abdômen e se alterada indicar a colangioressonância."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-306734","number":"306734","sourceNumber":"306734","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"J.L.A, 56 anos, tabagista e etilista de longa data, dá entrada no hospital com dor\nintensa em andar superior do abdome e\nvômitos. Foram identificados níveis elevados de amilase e\nlipase. Os demais exames laboratoriais demonstraram glicemia = 230mg/dL, desidrogenase lática =\n300UI/L, TGO = 300UI/L, TGP = 320UI/L, hemoglobina = 12g/dL, leucócitos = 17.500 cels/mm³ e\nplaquetas = 180.000/mm3. Assinale a alternativa correta com relação ao caso apresentado.","options":{"A":"O paciente apresenta quadro de pancreatite aguda grave e deverá receber tratamento\nnutricional com preferência para a nutrição enteral em relação à nutrição parenteral.","B":"Por se tratar de um caso grave de pancreatite aguda, o paciente deverá ser tratado com dieta\nzero por pelo menos 7 dias, hidratação vigorosa com solução balanceada e antibioticoterapia.","C":"Neste momento ainda não é possível definir a gravidade do quadro, mas o paciente apresenta\npancreatite aguda e deverá receber tratamento com hidratação, analgesia e dieta zero.","D":"Após 48 horas da admissão, deverão ser avaliados os critérios de RANSON para definição da\ngravidade do quadro, caso apresente sinais de gravidade, deverá então ser internado em UTI."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-306738","number":"306738","sourceNumber":"306738","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"J.P.L., 72 anos, internado há 10 dias por quadro de cólica biliar refratária associada a\ninfecção do trato urinário, em tratamento com ceftriaxone há 5 dias. Tem história de tabagismo e\nprovável doença pulmonar obstrutiva crônica, sem sintomas respiratórios no momento. Qual das\nalternativas abaixo confere, ao paciente, maior risco de mortalidade relacionada à abordagem\noperatória?","options":{"A":"Idade avançada","B":"Tabagismo","C":"Infecção urinária","D":"Internação hospitalar"},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-291652","number":"291652","sourceNumber":"291652","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Mulher, obesa, 55 anos com antecedentes de empachamento, dor em abdome superior\nhá 6 meses principalmente após alimentação\ngordurosa. Procura Emergência com dor em\nhipocôndrio há 12 horas temperatura axilar de 38,5ºC, leucocitose e ultrassonografia demonstrando\nvesícula com várias imagens hiperecogênicas com sombra acústica posterior e paredes com\nespessura de 0,8cm. Assinale a conduta mais apropriada:","options":{"A":"Tratamento com sintomáticos por tratar-se de cólica biliar, devendo ser submetida à\ncolecistectomia eletiva.","B":"Tratamento imediato com colecistectomia laparotômica em virtude do risco de lesões de\ncolédoco associado à colecistite aguda.","C":"Tratamento com colecistectomia laparoscópica eletivo, após melhora clínica obtida com dieta\nzero, sintomáticos e antibiótico intravenoso.","D":"Colangiorressonância magnética para avaliação de vias biliares, seguido de tratamento com\ncolecistectomia laparoscópica.","E":"Tratamento imediato com colecistectomia laparoscópica em virtude da colecistite aguda,\nassociado a antibiótico intravenoso."},"answer":"E","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-287846","number":"287846","sourceNumber":"287846","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Em relação à Colecistite Aguda, analisar a sentença abaixo: Deve ser solicitada\namilasemia para o diagnóstico diferencial com\npancreatite aguda (1ª parte). Há dor à palpação no\nhipocôndrio direito, com sinal de Murphy presente, que consiste na parada abrupta de uma\ninspiração profunda por dor quando a mão do examinador palpa a vesícula biliar em processo\ninflamatório (2ª parte). A inflamação que corresponde ecograficamente ao espessamento das\nparedes da vesícula, com ou sem presença de cálculos, é essencial para o diagnóstico de\ncolecistite (3ª parte). A sentença está:","options":{"A":"Correta somente em sua 1ª parte.","B":"Correta somente em sua 2ª parte.","C":"Correta somente em suas 1ª e 3ª partes.","D":"Correta somente em suas 2ª e 3ª partes.","E":"Totalmente correta."},"answer":"E","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-287849","number":"287849","sourceNumber":"287849","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Em relação à intervenção cirúrgica no câncer de pâncreas, assinalar a alternativa\nCORRETA:","options":{"A":"Pancreatectomia distal é sinônimo de cirurgia de Whipple.","B":"A cirurgia de Whipple é a técnica mais frequentemente utilizada para remover o câncer de\ncabeça do pâncreas.","C":"A técnica mais frequentemente utilizada é a pancreatectomia total.","D":"A duodenopancreatectomia é uma técnica raramente utilizada.","E":"A cirurgia de Whipple retira somente a parte distal do pâncreas."},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-287859","number":"287859","sourceNumber":"287859","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Sobre as patologias da vesícula biliar, analisar os itens abaixo: I. Obesidade, estase\nbiliar e gravidez estão entre os fatores de\nrisco para a formação de cálculos biliares. II. Pólipos de\ncolesterol geralmente são solitários e medem mais do que 1cm. III. O adenocarcinoma é o tipo\nhistológico mais comum nas neoplasias malignas da vesícula biliar. Está(ão) CORRETO(S):","options":{"A":"Somente o item II.","B":"Somente os itens I e II.","C":"Somente os itens I e III.","D":"Somente os itens II e III.","E":"Todos os itens."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-283905","number":"283905","sourceNumber":"283905","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Durante o exame abdominal, você observa um sinal de hematoma periumbilical. Na\nsemiologia, qual nome desse sinal?","options":{"A":"Sinal de Aaron.","B":"Sinal de Charcot.","C":"Sinal de Cullen.","D":"Sinal de Grey-Turner.","E":"Sinal de Danforth."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-266400","number":"266400","sourceNumber":"266400","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente feminina, 52 anos, há 02 dias apresenta dor em hipocôndrio direito de forte\nintensidade, febre alta, calafrios, icterícia, colúria e acolia fecal. O exame de ultrassonografia\nabdominal mostrou litíase em vesícula biliar, associado à dilatação moderada das vias biliares\nextra-hepáticas. Foi diagnosticada como doença litiásica da via biliar e colangite. Considerando os\nCritérios de Tókio de 2018, qual critério listado abaixo não é utilizado para o diagnóstico de\ncolangite?","options":{"A":"Dor em hipocôndrio direito.","B":"Febre.","C":"Icterícia.","D":"Dilatação de vias biliares."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-260713","number":"260713","sourceNumber":"260713","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Qual o tumor funcionante mais comum do pâncreas?","options":{"A":"Vipoma.","B":"Gastrinoma.","C":"Insulinoma.","D":"Adenocarcinoma.","E":"Glucagonoma."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-283931","number":"283931","sourceNumber":"283931","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Homem, 62 anos, hipertenso e dislipidêmico desde 55 anos, etilista desde os 50 anos.\nIniciou ingesta alcóolica após demissão de seu trabalho. No último ano, está ingerindo 1 garrafa de\ncachaça a cada 2 dias, segundo o relato da esposa. É trazido à consulta devido quadro de dor\nabdominal, sensação de estufamento abdominal, náuseas e vômitos, dor em membros inferiores.\nAcompanhante relata hábito intestinal regular. A revisão rápida de exames solicitados em consulta\nanterior revela hipertrigliceridemia com valores de triglicerídeos de 958 mg/dL. Qual a hipótese\ndiagnóstica mais provável?","options":{"A":"Síndrome de Wernicke-Korsakoff.","B":"Volvo intestinal.","C":"Pancreatite aguda.","D":"Síndrome de Aldoff.","E":"Parasitose intestinal."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-255629","number":"255629","sourceNumber":"255629","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Solange, 34 anos, hígida, agenda uma consulta com a médica da UBS para mostrar o\nresultado da ultrassonografia de abdome total que havia sido pedida devido a episódios recorrentes\nde dor abdominal periumbulical. Qual é a opção de descrição de laudo que necessita um\nencaminhamento para o cirurgião? MARQUE A CORRETA:","options":{"A":"Lesão polipóide na vesícula biliar","B":"Pequeno nódulo hepático sugestivo de hemangioma","C":"Esteatose hepática","D":"Múltiplos cistos renais bilaterais"},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-234439","number":"234439","sourceNumber":"234439","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente de 35 anos, masculino, retorna no seu consultório para controle pós\ninternação de um quadro de pancreatite aguda\nalcóolica há cerca de 6 semanas. Paciente se\nencontra estável e no momento assintomático. Relata estar se alimentando melhor, sem ingerir\nbebida alcóolica e em acompanhamento psiquiátrico. Ele traz junto uma tomografia que foi\nsolicitada na consulta anterior, de controle do quadro apresentado e que mostra uma lesão cística\nde 6 cm no andar superior do abdômen. Considerando o caso descrito, assinale a alternativa que\napresenta a conduta MAIS ADEQUADA a ser tomada.","options":{"A":"Como se trata de uma coleção líquida deve ser puncionada e esvaziada para evitar\ncomplicações.","B":"Como já tem 6 semanas a conduta é cirúrgica e indica a necessidade de uma cistogastrostomia.","C":"Como o paciente está assintomático a lesão pode ser observada e acompanhada clinicamente.","D":"O melhor tratamento nesse caso deve ser a drenagem endoscópica."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-227111","number":"227111","sourceNumber":"227111","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente de 70 anos admitido com quadro suspeito de neoplasia da cabeça do\npâncreas confirmado na tomografia de abdômen. No\nexame físico desse paciente, é CORRETO\nencontrar:","options":{"A":"Sinal courvoisier e vascolejo.","B":"Icterícia obstrutiva e sinal de Kernig.","C":"Sinal do vascolejo e transaminases acima de 2000 unidades.","D":"Sinal de Grey Turner e icterícia padrão obstrutivo."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-232151","number":"232151","sourceNumber":"232151","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Em pacientes com pancreatite aguda, o aumento da amilasemia é um fator importante\npara o diagnóstico, porém existem outras\ncausas que podem cursar com essa condição e\nassociar-se com dor abdominal, muitas vezes dificultando o diagnóstico correto. Assinale a\nassertiva que contenha causas de hiperamilasemia:","options":{"A":"Carcinoma pancreático, cetoacidose diabética, angiodisplasia colônica.","B":"Apendicite aguda, carcinoma pancreático, tireoidite.","C":"Cirrose hepática, úlcera péptica perfurada, prenhez tubária.","D":"Pênfigo bolhoso, insuficiência renal, parotidite.","E":"Coledocotlitíase, pneumonia, obstrução intestinal."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-246774","number":"246774","sourceNumber":"246774","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Com relação ao quadro de Colangite Aguda, considere as afirmações abaixo: I. O\ndiagnóstico de Colangite Aguda é dado quando paciente evolui com Tríade de Charcot, pois possui\nespecificidade e sensibilidade elevados. II. O seu diagnóstico só é definitivo na presença de\nicterícia clinica constatada. III. Para o diagnóstico definitivo de Colangite Aguda é necessário,\nobrigatoriamente, exame de imagem. IV. Quando suspeito o diagnóstico de Colangite Aguda Grave\na Ressonância Magnética de Abdomem deve ser o exame de imagem de escolha. V. Na Colangite\nAguda, devido à sua gravidade, deve-se iniciar antibioticoterapia empiricamente, imediatamente,\ncom Ceftriaxona e Metronidazol. VI. Na Colangite Aguda Grau III, o tratamento deverá ser instituído\ncom antibioticoterapia e, caso não se obtenha melhora clínica importante nas primeiras 24 horas, o\npaciente deverá ser submetido à procedimento cirúrgico e/ou CPRE. Quais questões estão\ncorretas?","options":{"A":"Apenas I.","B":"Apenas III.","C":"Apenas I,II, IV,V e VI","D":"Todas estão corretas.","E":"Apenas I, II, V e VI."},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-246782","number":"246782","sourceNumber":"246782","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Com relação ao diagnóstico e tratamento da Colecistite Aguda, considere as afirmações\nabaixo: I. Para o diagnóstico definitivo\nde Colecistite Aguda é necessário, obrigatoriamente, exame\nde imagem. II. Na Colecistite Aguda Grau III, icterícia clínica, alteração neurológica e alteração\nrespiratória, estão relacionadas com uma maior taxa de mortalidade em 30 dias. III. Paciente\nevoluindo com quadro de Colecistite Aguda devem receber sempre antibioticoterapia\nempiricamente a partir de seu diagnóstico. Podendo ser iniciado Ceftriaxona associado à\nMetronidazol. IV. Paciente com Colecistite Aguda devem receber antibioticoterapia via oral, assim\nque estiverem tolerando dieta via oral. Quais questões estão corretas?","options":{"A":"Apenas I.","B":"Apenas II, III e IV.","C":"Apenas I e III","D":"Apenas I, II e IV.","E":"Apenas II e III."},"answer":"E","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-246783","number":"246783","sourceNumber":"246783","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"O adenocarcinoma de pâncreas tem na ressecção cirúrgica como único tratamento com\nintuito curativo. No entanto, no momento do diagnóstico pequena parcela torna-se candidata ao\nprocedimento cirúrgico. Assim, analise os achados descritos abaixo e assinale aquele que NÃO\nCONTRA-INDICA a cirurgia curativa:","options":{"A":"Lesão de 4 cm com invasão da parede posterior do antro gástrico por contiguidade","B":"Nódulo de 0,5cm sugestivo de implante no peritoneo do diafragma","C":"Lesão de 3cm com acometimento circunferencial da artéria mesentérica superior","D":"Lesão de 2cm em paciente com nódulo supraclavicular esquerdo endurecido e fixo","E":"tumor de 2cm limitado ao pâncreas em paciente com doença coronariana grave e sinais de ICC\nlimitante"},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-246787","number":"246787","sourceNumber":"246787","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"São achados no exame físico do paciente com adenocarcinoma pancreático\ncompatíveis com doença avançada, exceto:","options":{"A":"Prateleira de Blumer","B":"Nódulo de Irish","C":"sinal de Troisier","D":"nódulo da Irmã Maria José","E":"sinal de Fox"},"answer":"E","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-243060","number":"243060","sourceNumber":"243060","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Qual dos itens seguintes mostrou diminuir a incidência de abscesso pancreático em\npacientes com pancreatite necrotizante grave?","options":{"A":"antibióticos profiláticos.","B":"exame frequente de imagens com amostragem percutâneas de novas coleções e fluidos.","C":"nutrição parenteral.","D":"nutrição enteral.","E":"abordagem cirúrgica precoce."},"answer":"D","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-220289","number":"220289","sourceNumber":"220289","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Homem de 60 anos se queixa de urina ?cor de coca-cola? e fezes ?cor de palha?\n(aspecto de massa de vidraceiro) há 10 dias,\nalém de prurido generalizado. Estava em uso de\nnaproxeno por causa de epigastralgia há 3 semanas. Ao exame físico, o paciente estava\nhipocorado e ictérico. A vesícula biliar era palpável, distendida, compressível e indolor, abaixo do\nrebordo costal direito. Sobre o caso descrito, assinale a alternativa que apresenta uma hipótese\netiológica CORRETA:","options":{"A":"Anemia hemolítica autoimune.","B":"Síndrome de Crigler-Najjar tipo II.","C":"Adenocarcinoma pancreático.","D":"Hepatite medicamentosa."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-196727","number":"196727","sourceNumber":"196727","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente com múltiplos cálculos no colédoco e dilatação coledociana > de 2,0 cm, na\nqual existe a dificuldade ou impossibilidade de retirá-los pela papiloesfincterotomia, a melhor\nopção\ncirúrgica é:","options":{"A":"Coledocoduodenostomia.","B":"Coledocostomia.","C":"CPRE.","D":"Hepaticojejunoanastomose."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-199608","number":"199608","sourceNumber":"199608","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Em relação à pancreatite aguda assinale a alternativa CORRETA.","options":{"A":"O diagnóstico de pancreatite aguda é estabelecido na presença de dor abdominal característica\ne níveis séricos de amilase e/ou lipase acima\nde duas vezes o limite superior da normalidade.","B":"A tomografia computadorizada do abdome utilizando contraste endovenoso permite avaliar com\nprecisão a presença e a extensão da necrose pancreática quando realizada precocemente, antes\ndo 3° dia do início do quadro.","C":"De acordo com os critérios de Atlanta, revisados em 2013, a presença de falência orgânica que\npersiste por mais de 48 horas caracteriza a presença de pancreatite aguda grave.","D":"Pacientes com pancreatite aguda grave que apresentam necrose pancreática devem receber\nantibioticoprofilaxia com objetivo de prevenir complicações infeciosas."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-212969","number":"212969","sourceNumber":"212969","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente do sexo feminino, 56 anos, etilista (200 ml destilados/dia), tabagista,\napresenta quadro de icterícia progressiva sem\ndor abdominal nas últimas 3 semanas, associada a\nperda de 15 kg nos últimos 40 dias. Ao exame físico, apresenta sinal de Courvoisier. Qual seria o\ndiagnóstico menos provável neste caso?","options":{"A":"Adenocarcinoma de papila duodenal.","B":"Adenocarcinoma de cabeça de pâncreas.","C":"Tumor de Klatskin.","D":"Colangiocarcinoma em colédoco distal.","E":"Metástases linfonodais comprimindo segunda porção duodenal e papila duodenal."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-212980","number":"212980","sourceNumber":"212980","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Assinale a única estrutura, dentre as seguintes, não mencionada para definição do\ntrígono de Calot:","options":{"A":"Artéria cística.","B":"Ducto hepático comum.","C":"Ducto cístico.","D":"Artéria hepática comum.","E":"Borda inferior do fígado."},"answer":"D","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-212977","number":"212977","sourceNumber":"212977","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente de 36 anos, sexo feminino, procura o hospital com quadro de dor em andar\nsuperior do abdome, de forte intensidade,\ncom irradiação para dorso e vômitos com início há 1 dia.\nOs exames mais importantes para elucidar o DIAGNÓSTICO e a ETIOLOGIA MAIS PROVÁVEL,\nsão respectivamente:","options":{"A":"Hemograma e tomografia computadorizada do abdome.","B":"PCR e ultrassonografia do abdome.","C":"Amilasemia e ultrassonografia do abdome.","D":"Amilasemia e tomografia computadorizada do abdome.","E":"Hemograma e ultrassonografia do abdome."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-212953","number":"212953","sourceNumber":"212953","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente com 42 anos, feminino, com dor abdominal há 24hs em abdome superior e\nirradiação para dorso. Na admissão, apresenta fácies de dor, taquicárdica, taquipneica, agitada,\ncom dor forte à palpação do abdome superior. PA 110 x 70 mmHg, FC 108 bpm, SATO2 88% em\nar ambiente, sendo então administrado O2 sob máscara de Venturi 6 L/min (com FiO2 de 40%).\nLeucócitos de 13.500, PCR 228, glicose 118, amilase 2.281, TGO 118, TGP 90, FA 138, GGT 152,\nbilirrubina total 1,1. Gasometria arterial (após O2 suplementar): pH: 7,34 / pCO2: 33 / pO2: 80 /\nSatO2: 95% / HCO3- : 18 / BE: -2. Assinale o critério clínico/laboratorial que corrobora a\nclassificação de gravidade previamente indicada:","options":{"A":"Leucocitose.","B":"PCR elevado.","C":"Amilase.","D":"Taquicardia.","E":"Relação PaO2/FiO2."},"answer":"E","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-199517","number":"199517","sourceNumber":"199517","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"M.G.H., homem, 60 anos, queixa-se de dor abdominal contínua, em hipocôndrio direito\ne epigástrio há 2 dias. Relata ainda febre baixa\ne vômitos e informa que o início da dor se dá após\nalimentação. Ao exame físico, apresenta-se ictérico +/4+; desidratado; febril 37,8°C; abdome\nlevemente distendido; flácido; doloroso à palpação em hipocôndrio direito com sinal de Murphy\npositivo. Hemograma com 11.000 leucócitos; 5% de bastões; 70% de segmentados. Considerando\n\no caso descrito, assinale a alternativa que apresenta CORRETAMENTE o exame a ser solicitado e\n\no achado esperado.","options":{"A":"Endoscopia digestiva alta e lesão ulcerosa duodenal.","B":"Tomografia de abdome e pneumoperitônio.","C":"Tomografia de abdome e colelitíase.","D":"Ultrassom de abdome e halo hipoecoico perivesicular."},"answer":"D","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-212964","number":"212964","sourceNumber":"212964","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Homem, 65 anos, com história de colelitíase assintomática, apresenta dor em barra e\nvômitos de início há 5 dias. Após dar entrada no hospital, exames laboratoriais evidenciaram\nleucocitose com 14.000 leucócitos por mm³ sem desvio, amilase 900 U/L, lipase 1900 U/L e lactato\n1,8 mg/dl. TC de abdome solicitada pelo clínico do plantão evidenciou pâncreas aumentado, com\nborramento da gordura e pequenas coleções peripancreáticas e imagem sugestiva de pequena\nárea de necrose em cauda de pâncreas. Com esse resultado, é então solicitado um parecer para\ncirurgia geral para avaliar o paciente. Em relação ao tratamento inicial do paciente, assinale a\nalternativa mais adequada.","options":{"A":"Dieta oral zero, hidratação venosa, analgesia e demais sintomáticos, ceftriaxona 2 g EV dose\ndiária.","B":"Dieta oral zero, hidratação venosa, analgesia e demais sintomáticos.","C":"Dieta oral zero, hidratação venosa, laparotomia com necrosectomia e drenagem dos abscessos.","D":"Punção venosa profunda para nutrição parenteral total, hidratação venosa, analgesia e demais\nsintomáticos.","E":"Passagem de sonda nasoentérica por endoscopia digestiva, nutrição enteral, hidratação venosa,\nanalgesia e demais sintomáticos."},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-212890","number":"212890","sourceNumber":"212890","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Mulher, 45 anos, em pré-operatório para colecistectomia devido à microlítiase em\nvesícula biliar procura o PS devido dor\nabdominal em HCD de início há 3 dias, associada a icterícia,\nfebre, náuseas e vômitos. Ao exame físico, apresenta abdome flácido, dor forte a palpação em\nHCD, PA 110 x 70 mmHG, FC 78 bpm. USG de abdome realizado no PS confirma colelitíase, e\nevidencia borramento da gordura em torno do colédoco distal. Qual a principal suspeita diagnóstica\ne o tratamento inicial?","options":{"A":"Colecistite aguda complicada. Colecistectomia de urgência.","B":"Colecistite aguda. Antibioticoterapia.","C":"Colangite aguda. Antibioticoterapia.","D":"Colangite aguda. Drenagem da via biliar de urgência.","E":"Pancreatite aguda de cabeça de pâncreas. Dieta zero, hidratação venosa e analgesia"},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-199496","number":"199496","sourceNumber":"199496","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"A paciente R.F.T., 47 anos, apresentou quadro de pancreatite aguda e foi internada\ncom 2 critérios de Ranson médicos após 48\nhoras. Depois de uma semana, recebeu alta. Duas\nsemanas após sua alta, retornou ao hospital com quadro de dor leve e vômitos. Realizada\ntomografia de abdome que apresentou sinais de aumento na área pancreática, borramento da\ngordura peripancreática, associada à coleção líquida adjacente. Considerando o caso descrito,\nassinale a alternativa que apresenta a conduta CORRETA a ser adotada para essa paciente.","options":{"A":"Tratamento conservador.","B":"Punção percutânea com agulha fina da coleção líquida.","C":"Punção e drenagem percutânea da coleção líquida.","D":"Laparotomia para drenagem ampla da coleção."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-220324","number":"220324","sourceNumber":"220324","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente de 67 anos apresenta-se com quadro de icterícia padrão colestático e sem dor\nabdominal. Sua suspeita é de obstrução das vias biliares e uma possível neoplasia de pâncreas.\n\nConsiderando o caso descrito, assinale a alternativa CORRETA:","options":{"A":"A possibilidade de neoplasia de corpo ou cauda do pâncreas, que muitas vezes já apresenta\nmetástases à distância, deve ser considerada na admissão.","B":"A dor é um sintoma comum no câncer de pâncreas, usualmente causada pela invasão neural\nperipancreática, e já indica pior prognóstico.","C":"A mortalidade operatória das duodenopancreatectomias é cerca de 10-20%, mas, quando\nrealizada, a taxa de sobrevida pode chegar em até 50% em 5 anos.","D":"O sinal de Courvoisier, se presente no exame clínico, indica possível tumor de Klatskin."},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-202743","number":"202743","sourceNumber":"202743","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"A importância do reconhecimento do triângulo de Calot é inegável ao cirurgião geral,\nsendo um marco anatômico que facilita a progressão segura de uma colecistectomia. Assim,\nestruturas relevantes encontradas no interior deste triângulo são:","options":{"A":"Artéria cística, artéria hepática direita e linfonodo do ducto cístico.","B":"Artéria cística, ducto cístico e linfonodo do ducto cístico.","C":"Artéria hepática direita, ducto cístico e linfonodo do ducto cístico.","D":"Artéria cística, artéria hepática comum e ducto hepático comum.","E":"Artéria hepática comum, ducto cístico e linfonodo do hepático comum."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-215146","number":"215146","sourceNumber":"215146","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"O achado incidental de nódulos hepáticos é uma preocupação muito frequente em\npacientes assintomáticos submetidos a exames de\nimagem, embora a maioria das vezes não seja\nnecessário nenhum tratamento. Qual o tipo histológico de nódulo hepático benigno mais frequente?","options":{"A":"Hiperplasia nodular focal.","B":"Hemangioma.","C":"Adenoma hepático.","D":"Hamartoma de vias biliares.","E":"Abscesso hepático."},"answer":"B","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-202749","number":"202749","sourceNumber":"202749","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"A dosagem de amilase no sangue tem se mostrado um marcador significativo para o\ndiagnóstico de pancreatite aguda. Sobre a amilasemia, é correto afirmar:","options":{"A":"Seus valores têm correlação direta com o grau de necrose pancreática na pancreatite aguda.","B":"Hiperamilasemia permanece presente com frequência até o 12° dia após o início dos sintomas\nde pancreatite aguda.","C":"Macroamilasemia é um achado comumemente presente na pancreatite aguda medicamentosa.","D":"10% dos pacientes com pancreatite aguda fatal podem apresentar níveis de amilase normais ou\nquase normais.","E":"Sua presença associada ao quadro de pneumoperitônio é patognomônica de úlcera péptica\nperfurada."},"answer":"D","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-199559","number":"199559","sourceNumber":"199559","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Escolar, masculino, 7 anos de idade, hígido previamente, iniciou dor abdominal,\nlocalizada em região epigástrica, de forte\nintensidade, associada à posição antálgica (flexão de\nquadril e joelhos), há 2 dias. Evoluiu com vômitos (3 episódios), distensão abdominal e febre, nas\núltimas 24 horas. Refere queda no banheiro da casa da avó com trauma de abdome em pia do\nbanheiro há 3 dias. Ao exame apresenta-se com palidez cutaneomucosa, levemente desidratado,\neupneico, eucardico, com dor intensa à palpação de andar superior do abdome. Mediante este\nquadro, qual seria sua principal hipótese e qual seria o exame de escolha para confirmação\ndiagnóstica?","options":{"A":"Pancreatite aguda. Amilase, lipase séricas.","B":"Cisto de colédoco. Aminotransferases e ultrassonografia abdominal.","C":"Hepatite aguda. Aminotranferases, bilirrubinas e ultrassonografia abdominal.","D":"Rotura de baço. Ressonância nuclear magnética de abdome para avaliar intervenção cirúrgica."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-199631","number":"199631","sourceNumber":"199631","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"J.A.M.C., 43 anos, previamente hígido, iniciou quadro de dor abdominal intensa em\nepigástrio e hipocôndrio direito, associado a náuseas e vômitos há cerca de 02 dias. Ao exame de\nadmissão no pronto-socorro, apresentava-se com fácies de dor, corado, desidratado, istérico +/4+,\nafebril, acianótico, sem edemas, eupneico, frequência cardíaca de 86 bpm, pressão arterial de\n130/90 mmHg. Exames de entrada: hemoglobina 14,1 g/dL (valor de referência entre 12 e 16 g/dl),\nhematócrito 42% (valor de referência entre 40% e 50%), leucócitos 10.500/mm3 (valor de referência\n4.000 - 11.000/mm3), plaquetas 305.00/mm3 (valor de referência entre 150.000 - 400.00/mm3),\namilase 130 U/L (valor de referência entre 50 e 150 U/L), bilirrubina total 2,3 mg/dl (valor de\nreferência menor que 1,0 mg/dl), bilirrubina direta 1.8 mg/dl, AST 45 U/L (valor de referência menor\nque 35 U/L), ALT: 30 U/L (valor de referência menor que 35 U/L), gama-GT 150 U/L (valor de\nreferência entre 8-78 U/L), fosfatase alcalina 230 U/L (valor de referência entre 36-92 U/L). A\nultrassonografia abdominal visualizou dilatação de colédoco, medindo 1,2 cm, colelitíase, distensão\nda vesícula biliar e paredes finas, sem outras alterações. Qual o risco de coledocolitíase e qual a\npropedêutica a seguir?","options":{"A":"Baixo; colecistectomia por laparoscopia sem colangiografia eletiva.","B":"Intermediário; colecistectomia por laparoscopia com colangiografia eletiva.","C":"Alto; colangioressonância.","D":"Alto; Colangiopancreatografia Retrógrada Endoscópica (CPRE)."},"answer":"D","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-174389","number":"174389","sourceNumber":"174389","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"A tríade diagnóstica encontrada na síndrome de Verner-Morrison caracteriza-se por:","options":{"A":"Altos níveis de peptídeo intestinal vasoativo no sangue, tumor pancreático e diarreia\nsecretória.","B":"Altos níveis de gastrina no sangue, tumor pancreático e úlcera gástrica recidivante.","C":"Altos níveis de somastostatina no sangue, tumor hepático e diarreia aquosa.","D":"Altos níveis de 5-HT no sangue, tumor hepático e rubor facial.","E":"Altos níveis de aldosterona no sangue, tumor de supra-renal, hipertensão arterial sistêmica."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-172766","number":"172766","sourceNumber":"172766","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Os marcadores tumorais são macromoléculas presentes no tumor, no sangue ou em\noutros líquidos biológicos, cujo aparecimento e/ou alterações em suas concentrações estão\nrelacionados com a gênese e o crescimento de células neoplásicas. Dentre os marcadores\ntumorais, quais indicam o diganóstico de adenocarcinoma de pâncreas e de carcinoma\nhepatocelular, respectivamente, quando alterados?","options":{"A":"CA 125 e Alfafetoprotéina.","B":"Alfafetoprotéina e CEA.","C":"CA 19.9 e Alfafetoprotéina.","D":"CA 19.9 e CEA."},"answer":"C","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-155350","number":"155350","sourceNumber":"155350","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente de 57 anos, sexo feminino, é admitida pela manhã com dor abdominal intensa\nque durou por toda a noite. A dor teve\ninício na véspera, após ela ter chegado de uma festa.\n\nComeçou gradual, mas tornou-se constante e intensa, de localização epigástrica, irradiando para a\nregião lombar esquerda. Posteriormente, surgiram vômitos esverdeados e náuseas. No exame\nfísico, a temperatura axilar era de 37,7°C; PA = 90 x 60 mmHg; FC = 119 bpm; FR = 25 irpm. Há\ndistensão abdominal, dor à palpação profunda do epigástrio e peristalse de difícil detecção. O toque\nretal foi normal. Assinale a opção que indica os exames bioquímicos que serão mais úteis para\nestabelecer o diagnóstico desse caso:","options":{"A":"Glicose, ureia e creatinina séricas.","B":"Aminotransferases séricas (AST e ALT).","C":"Sódio e potássio urinário.","D":"Amilase e lipase séricas.","E":"Pesquisa de cristais no sedimento urinário e sódio sérico"},"answer":"D","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-162596","number":"162596","sourceNumber":"162596","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Com relação à pancreatite aguda, assinale a alternativa CORRETA:","options":{"A":"A colangiopacreatografia endoscópica retrógrada está indicada em todos os casos de\npancreatite.","B":"Abuso de álcool, trauma, hipertrigliceridemia, hipocalcemia, hipercalcemia e cálculos biliares\nsão\npossíveis causas de pancreatite.","C":"A cirurgia está indicada para todos os casos de pancreatite necrosante.","D":"Antibioticoterapia precoce está indicada em todos os casos de pancreatite.","E":"Níveis de amilase não se correlacionam com gravidade e prognóstico na pancreatite aguda."},"answer":"E","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-148595","number":"148595","sourceNumber":"148595","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente do sexo masculino, 53 anos, etilista crônico, foi internado na enfermaria de\ngastroenterologia de um Hospital Universitário apresentando dor em andar superior de abdome,\niniciada há cerca de três anos, mas que se tornaram mais intensas nos últimos seis meses, com\npiora pós alimentação. Refere emagrecimento não quantificado. Realizou tomografia de abdome\nque evidenciou calcificações no parênquima pancreático e dilatação do ducto de Wirsung. Qual a\nmelhor conduta para esse paciente?","options":{"A":"Complementar investigação com a realização de colangiopancreatografia retrógrada\nendoscópica.","B":"Complementar investigação com a realização de ultrassonografia endoscópica.","C":"Complementar investigação com a realização de colangioressonância.","D":"Iniciar reposição de enzimas pancreáticas.","E":"Prescrever dieta zero e hidratação endovenosa."},"answer":"D","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-149120","number":"149120","sourceNumber":"149120","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente feminina, 47 anos, previamente hígida, deu entrada no pronto atendimento às\n20h, com história de dor em hipocôndrio direito de forte intensidade, de início na manhã do mesmo\ndia, associado a náuseas e vômitos biliosos. Nega episódios prévios semelhantes. Sem outras\ncomorbidades. Ao exame físico, encontra-se estável hemodinamicamente, anictérica, com dor à\npalpação abdominal em quadrante superior direito e sinal de Murphy positivo. Restante do exame\nfísico sem alterações. Referente ao possível diagnóstico, assinale a alternativa CORRETA:","options":{"A":"O sintoma mais importante do quadro de colecistite aguda é a dor em hipocôndrio direito. Ao\ncontrário da cólica biliar, a dor da colecistite geralmente tem duração prolongada até por mais de 6\nhoras.","B":"A paciente do caso apresenta quadro sugestivo de cólica biliar. Pode ser medicada para controle\nda dor e liberada para investigação\nambulatorial.","C":"A tomografia de abdome é o exame diagnóstico de eleição e deve ser realizada de rotina na\nabordagem desses casos.","D":"A pedra fundamental do tratamento é o início precoce e a manutenção de antibióticos. O\ntratamento cirúrgico é uma opção para casos mais graves e refratários ao uso de antibióticos.","E":"A colecistectomia deve ser realizada rotineiramente em no máximo 24 horas devido ao alto risco\nde evolução para choque séptico grave de foco abdominal."},"answer":"A","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-3-149129","number":"149129","sourceNumber":"149129","collectionBlock":"medcurso:medcurso-gastrologia-gas-3","collectionLabel":"Medcurso · GAS 3","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 3","subtopic":"","stem":"Paciente 68 anos, hipertenso, previamente revascularizado, é admitido pronto- socorro\nà noite com queixas de dor de moderada\nintensidade em hipocôndrio direito de mais de 24 horas\nde evolução, com piora últimas horas motivando a procura por atendimento. Refere também febre\nbaixa nesse intervalo e fezes amolecidas e volume maior que o habitual. Refere episódios prévios\nde leve dor nesse local. Hábito intestinal constipado. Na admissão exame clínico revelando dor a\npalpação profunda em hipocôndrio direito, sem sinais de peritonite. Restante sem alterações\nimportantes. Médico do pronto Socorro decide realizar uma TC de abdome de urgência com o\nseguinte laudo verbal: ?ausência de pneumoperitôneo e/ou líquido livre na cavidade abdominal;\npâncreas normal; baço e fígado normais; vesícula com paredes espessadas sugerindo diagnóstico\nde colecistite alitiásica?; e os seguintes exames: Hemograma com 13000 leucócitos, bilirrubina total\n1, gama GT e fosfatase alcalina normais, PCR 90. De posse dos exames o medico do PS solicita\npresença dos medicos residentes da clínica médica e do cirurgia geral, que após análise do caso\ndevem?:","options":{"A":"Manter a hipótese diagnóstica de colecistite alitiásica, solicitar hemoculturas e iniciar\nantibióticos.","B":"Manter a hipótese diagnóstica de colecistite alitiásica. Todavia, solicitar ultrassonografia (US)\nabdome para confirmação diagnóstica. Caso\nUS, por sua maior especificidade também demonstrar\no espessamento de parede vesícula biliar, iniciar antibióticos e preparar paciente para\ncolecistectomia se possível nas próximas 48-72h.","C":"Manter a hipótese diagnóstica de colecistite alitiásica. Todavia, solicitar ultrassonografia (US)\nabdome para confirmação diagnóstica. Caso\nUS, por sua maior especificidade também demonstrar\no espessamento de parede vesícula biliar, iniciar antibióticos, preparar paciente para\ncolecistectomia e internar paciente em CTI, uma vez que a colecistite alitiásica é uma patologia\ngrave e potencialmente fatal.","D":"Questionar a hipótese diagnóstica de colecistite alitiásica. Não iniciar antibióticos, rever a\nhistória\nclínica em detalhes buscando possíveis razões que possam justificar o suposto diagnóstico, rever a\ntomografia junto com o radiologista e\n\ndiscutir diagnósticos diferenciais com seus respectivos preceptores.","E":"Questionar a hipótese diagnóstica de colecistite alitiásica. Todavia, solicitar ultrassonografia\n(US)\nabdome para confirmação diagnóstica. Caso US, por sua maior especificidade também demonstrar\no espessamento de parede vesícula biliar, iniciar antibióticos e preparar paciente para\ncolecistectomia se possível nas próximas 48-72h."},"answer":"D","source":"Gastrologia/GAS 3/GAS 3.txt","sourceLabel":"Medcurso · GAS 3","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 3","Medcurso"],"answerSource":"explicit","commentDeferred":true}]};
